window.QUESTIONS = [{"id": "S1-LANG-0001", "subject": "analytical", "topic": "language", "subtopic": "main_idea", "difficulty": 1, "stem": "ข้อความต่อไปนี้มีใจความหลักว่าอย่างไร?\n\"การล้างมือบ่อย ๆ ช่วยลดการติดเชื้อทางเดินอาหารได้อย่างมาก องค์การอนามัยโลกจึงแนะนำให้ล้างมือก่อนปรุงอาหาร ก่อนรับประทาน และหลังใช้ห้องน้ำทุกครั้ง\"", "figure_svg": null, "choices": ["องค์การอนามัยโลกมีหน้าที่แนะนำประชาชน", "การล้างมือมีประโยชน์ต่อสุขภาพและถูกแนะนำให้ทำในจังหวะสำคัญ", "ทางเดินอาหารติดเชื้อจากมือไม่สะอาด", "การใช้ห้องน้ำต้องล้างมือทุกครั้ง"], "answer": 1, "explanation": "ใจความหลักคือประโยคแรก (ล้างมือลดการติดเชื้อ) และประโยคสุดท้ายขยายเป็นคำแนะนำ (จังหวะการล้างมือ) ตัวเลือก ข ครอบคลุมทั้งสองส่วน — ก กว้างเกินและไม่ใช่ใจความของย่อหน้า ค และ ง เป็นรายละเอียดย่อยเพียงส่วนเดียว", "shortcut": "ดูประโยคแรกกับประโยคสุดท้าย — ใจความมักอยู่ 2 จุดนี้", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0002", "subject": "analytical", "topic": "language", "subtopic": "main_idea", "difficulty": 1, "stem": "ข้อใดสรุปใจความสำคัญของข้อความได้ถูกต้องที่สุด?\n\"ในฤดูฝน หลายจังหวัดประสบปัญหาน้ำท่วมขัง เส้นทางสัญจรถูกตัดขาด เศรษฐกิจท้องถิ่นหยุดชะงัก หน่วยงานรัฐจึงเร่งสร้างระบบระบายน้ำและซ่อมแซมถนน\"", "figure_svg": null, "choices": ["หน่วยงานรัฐซ่อมถนนหลังน้ำท่วม", "น้ำท่วมในฤดูฝนสร้างความเสียหายต่อการสัญจรและเศรษฐกิจ และมีการเร่งแก้ไข", "เศรษฐกิจท้องถิ่นหยุดชะงักเสมอในฤดูฝน", "ระบบระบายน้ำสร้างไม่ทันในฤดูฝน"], "answer": 1, "explanation": "ข้อความมี 2 ส่วนคือปัญหา (น้ำท่วมทำลายการสัญจรและเศรษฐกิจ) และการแก้ไข (ระบายน้ำ ซ่อมถนน) ตัวเลือก ข ครอบคลุมทั้งคู่ — ก แคบเกิน (แค่ซ่อมถนน) ค มีคำว่า 'เสมอ' ที่เกินข้อความ ง ไม่มีข้อมูลว่า 'ไม่ทัน'", "shortcut": "หาตัวเลือกที่ครอบคลุมทั้ง 'ปัญหา + ทางแก้' ของย่อหน้า", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0003", "subject": "analytical", "topic": "language", "subtopic": "inference", "difficulty": 2, "stem": "ข้อใดอนุมานจากข้อความได้?\n\"สำนักงาน ก.พ. จัดอบรมหลักสูตรพัฒนาผู้นำรุ่นใหม่ให้ผู้เข้ารับราชการที่มีศักยภาพสูงทุกปี\"", "figure_svg": null, "choices": ["ผู้เข้ารับราชการทุกคนต้องผ่านหลักสูตรนี้", "สำนักงาน ก.พ. มองว่าผู้นำรุ่นใหม่ต้องมีการพัฒนาอย่างต่อเนื่อง", "หลักสูตรนี้ยกเลิกไม่ได้ในอนาคต", "ผู้เข้าอบรมทุกคนได้เลื่อนตำแหน่งหลังจบหลักสูตร"], "answer": 1, "explanation": "การที่หน่วยงานจัดอบรมซ้ำทุกปีต่อเนื่องกันแสดงว่าให้ความสำคัญกับการพัฒนาผู้นำ — ก ไม่มีคำว่า 'ทุกคน' ในข้อความ (มีแค่ผู้มีศักยภาพสูง) ค และ ง เป็นการคาดเดาเกินข้อความ (อนาคต/ผลลัพธ์ ไม่ได้ระบุ)", "shortcut": "อนุมาน = สรุปจากพฤติกรรมในข้อความเท่านั้น ห้ามแต่งอนาคตหรือเงื่อนไขที่ไม่มี", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0004", "subject": "analytical", "topic": "language", "subtopic": "detail", "difficulty": 1, "stem": "ตามข้อความ ข้อใดระบุไว้โดยตรง?\n\"โครงการหลวงพัฒนาอาชีพเสริมให้ชาวเขาปลูกกาแฟอาราบิก้าบนที่สูง เพื่อทดแทนการปลูกฝิ่นและเพิ่มรายได้ให้ชุมชน\"", "figure_svg": null, "choices": ["กาแฟอาราบิก้ามีรสชาติดีที่สุดในโลก", "โครงการหลวงส่งเสริมปลูกกาแฟบนที่สูงเพื่อทดแทนฝิ่นและเพิ่มรายได้", "ชาวเขาทุกคนปลูกกาแฟแล้ว", "ฝิ่นปลูกได้เฉพาะบนที่สูง"], "answer": 1, "explanation": "ข้อความระบุตรง ๆ ว่าส่งเสริมปลูกกาแฟบนที่สูง 'เพื่อทดแทนการปลูกฝิ่นและเพิ่มรายได้' — ก เป็นความเห็น ค มีคำว่า 'ทุกคน' เกินข้อความ ง ไม่ได้ระบุว่าฝิ่นปลูกได้ 'เฉพาะ' ที่สูง", "shortcut": "คำถาม detail → จับคำตรงในข้อความ ไม่ต้องตีความ", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0005", "subject": "analytical", "topic": "language", "subtopic": "inference", "difficulty": 2, "stem": "ผู้เขียนข้อความต่อไปนี้มีจุดมุ่งหมายใด?\n\"อย่ารอช้า วงเงินกองทุนหมู่บ้านปีนี้จำกัด ผู้ที่ยื่นคำขอก่อนมีสิทธิพิจารณาก่อน สมัครได้ที่องค์การบริหารส่วนตำบลภายในวันที่ 30 กันยายน\"", "figure_svg": null, "choices": ["บอกเล่าประวัติกองทุนหมู่บ้าน", "เชิญชวนและเร่งให้ประชาชนยื่นคำขอภายในเวลาที่กำหนด", "รายงานผลการดำเนินงานกองทุน", "เตือนว่ากองทุนจะปิดถาวร"], "answer": 1, "explanation": "คำว่า 'อย่ารอช้า' 'จำกัด' 'สมัครได้ภายในวันที่...' เป็นภาษาเร่งเร้าและให้ข้อมูลวิธีสมัคร — จุดมุ่งหมายคือเชิญให้ยื่นคำขอ ก และ ค ไม่มีข้อมูลในข้อความ ง 'ปิดถาวร' ไม่ได้ระบุ", "shortcut": "ดูคำเร่งเร้า (อย่าช้า/ด่วน/ภายใน) = จุดมุ่งหมายเพื่อกระตุ้นให้ทำ", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0006", "subject": "analytical", "topic": "language", "subtopic": "inconsistent", "difficulty": 3, "stem": "ข้อความใด 'ไม่สอดคล้อง' กับบทความต่อไปนี้?\n\"หน่วยงานภาครัฐหลายแห่งปรับมาให้บริการออนไลน์เต็มรูปแบบ ช่วยลดระยะเวลารอคอยและต้นทุนการเดินทางของประชาชน อย่างไรก็ดี ผู้ประสานงานยังพบว่าประชาชนสูงวัยส่วนหนึ่งยังต้องการความช่วยเหลือจากเจ้าหน้าที่หน้าเคาน์เตอร์\"", "figure_svg": null, "choices": ["บริการออนไลน์ช่วยลดเวลาและค่าเดินทาง", "ผู้สูงวัยบางส่วนยังต้องพึ่งเจ้าหน้าที่", "ประชาชนทุกกลุ่มเปลี่ยนมาใช้บริการออนไลน์แล้ว", "หน่วยงานภาครัฐให้บริการออนไลน์เพิ่มขึ้น"], "answer": 2, "explanation": "บทความระบุว่าผู้สูงวัยส่วนหนึ่งยังต้องพึ่งเคาน์เตอร์ ดังนั้น 'ทุกกลุ่มเปลี่ยนมาใช้แล้ว' จึงขัดแย้งโดยตรง — ก ค และ ง สอดคล้องกับข้อความทั้งหมด (ก: ลดระยะเวลาและต้นทุนการเดินทาง, ง: 'หลายแห่งปรับมาให้บริการออนไลน์')", "shortcut": "ข้อ 'ไม่สอดคล้อง' → หาตัวเลือกที่ขัดแย้งตรง ๆ มองหากลุ่มคำสุดโต่ง (ทุก/ทั้งหมด)", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0007", "subject": "analytical", "topic": "language", "subtopic": "main_idea", "difficulty": 2, "stem": "ใจความสำคัญที่สุดของย่อหน้าคือข้อใด?\n\"ความเครียดจากงานที่สะสมเป็นเวลานานส่งผลต่อทั้งสุขภาพกายและใจ ผู้ที่รับผิดชอบงานหนักอย่างต่อเนื่องมักมีอาการนอนไม่หลับ ปวดศีรษะ และขาดสมาธิ ผู้เชี่ยวชาญจึงเน้นย้ำความสำคัญของการพักผ่อนและการหาที่ปรึกษาเมื่อเริ่มมีอาการ\"", "figure_svg": null, "choices": ["ปวดศีรษะเกิดจากความเครียด", "การนอนไม่หลับเป็นเรื่องปกติของคนทำงาน", "ความเครียดจากงานส่งผลเสียต่อสุขภาพและควรได้รับการจัดการแต่เนิ่น ๆ", "ที่ปรึกษาแก้ความเครียดได้ทุกกรณี"], "answer": 2, "explanation": "โครงสร้างย่อหน้า: ปัญหา (ความเครียดสะสมส่งผลเสีย) → อาการ → คำแนะนำ (พัก/ปรึกษา) ตัวเลือก ค ครอบคลุมภาพรวม — ก และ ข เป็นรายละเอียดย่อย ง สุดโต่งเกินไป ('ทุกกรณี')", "shortcut": "ย่อหน้าปัญหา→วิธีแก้: ใจความคือ 'ปัญหา + ทิศทางการแก้'", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0008", "subject": "analytical", "topic": "language", "subtopic": "inference", "difficulty": 3, "stem": "จากข้อความ ข้อใด 'น่าจะเป็นความเห็นของผู้เขียน' มากที่สุด?\n\"ระบบการยื่นแบบออนไลน์ช่วยลดขั้นตอนเอกสารได้จริง แต่องค์กรยังตรวจเอกสารด้วยตนเองอยู่สองชั้น ทำให้เวลาโดยรวมไม่ได้ลดลงมากนัก ถ้าต้องการให้ระบบเกิดประโยชน์เต็มที่ องค์กรควรทบทวนขั้นตอนตรวจสอบซ้ำซ้อน\"", "figure_svg": null, "choices": ["ระบบออนไลน์ล้มเหลวโดยสิ้นเชิง", "องค์กรควรออกแบบขั้นตอนการทำงานให้สอดคล้องกับเทคโนโลยีที่ใช้", "การตรวจสอบเอกสารเป็นสิ่งไม่จำเป็น", "พนักงานทุกคนต่อต้านระบบใหม่"], "answer": 1, "explanation": "ผู้เขียนชี้ว่าเทคโนโลยีดีแต่ขั้นตอนเดิม (ตรวจซ้ำ 2 ชั้น) ทำให้ไม่เกิดประโยชน์ — ความเห็นคือควรปรับขั้นตอนให้สอดคล้องกับระบบ ก สุดโต่งเกิน ('ล้มเหลวสิ้นเชิง') ค และ ง เป็นการแต่งเรื่องที่ข้อความไม่ได้พูด", "shortcut": "หาประโยคท้ายย่อหน้าที่ขึ้นด้วย 'ถ้า/ควร' — มักเป็นจุดมุ่งหมายหรือความเห็นของผู้เขียน", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0009", "subject": "analytical", "topic": "language", "subtopic": "detail", "difficulty": 2, "stem": "ข้อความระบุสาเหตุหลักของปัญหาใด?\n\"หลังปรับขึ้นอัตราค่าทางด่วน ผู้ใช้ทางด่วนลดลง 15% ในสามเดือนแรก ทำให้รายได้ของการทางพิเศษฯ ลดลงตามไปด้วย แม้ว่ารัฐบาลจะคาดหวังว่ารายได้จะเพิ่มขึ้น\"", "figure_svg": null, "choices": ["การทางพิเศษฯ ขาดทุนเพราะบริหารผิดพลาด", "การขึ้นค่าทางด่วนทำให้อัตราการใช้ทางด่วนลดลง", "ผู้ใช้ทางด่วนย้ายไปใช้รถไฟฟ้า", "รัฐบาลตั้งใจเพิ่มรายได้ด้วยวิธีอื่น"], "answer": 1, "explanation": "ข้อความระบุเหตุ → ผล คือ 'หลังปรับขึ้นค่าทางด่วน ผู้ใช้ลดลง 15%' โดยตรง — ก หาเรื่องนอกข้อความ ค ไม่ได้ระบุ ง ไม่เกี่ยวกับสาเหตุของรายได้ลด", "shortcut": "คำถาม 'สาเหตุ' → หาประโยคเหตุ-ผล (หลัง.../เนื่องจาก.../ทำให้...)", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0010", "subject": "analytical", "topic": "language", "subtopic": "word_in_context", "difficulty": 3, "stem": "จากข้อความ คำว่า 'อุดหนุน' ในประโยค \"หน่วยงานได้รับงบประมาณอุดหนุนจากภาครัฐเพื่อขยายบริการ\" หมายถึงข้อใดใกล้เคียงที่สุด?", "figure_svg": null, "choices": ["กู้ยืมคืนภายหลัง", "สนับสนุนด้วยเงินหรือทรัพยากร", "ร่วมลงทุนเพื่อผลกำไร", "แลกเปลี่ยนบริการ"], "answer": 1, "explanation": "'เงินอุดหนุน' คือเงินที่รัฐให้โดยไม่ต้องชำระคืน เพื่อสนับสนุนการดำเนินงาน — ก ผิด (ไม่ต้องคืน) ค ผิด (ไม่ใช่การร่วมลงทุนเพื่อกำไร) ง ผิด (ไม่ใช่การแลกเปลี่ยน)", "shortcut": "ศัพท์ในบริบท → แทนความหมายแต่ละตัวเลือกในประโยคเดิม ดูว่าประโยคยังสมเหตุสมผลหรือไม่", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0011", "subject": "analytical", "topic": "language", "subtopic": "sentence_order", "difficulty": 1, "stem": "เรียงลำดับประโยคให้ต่อเนื่อง\n(ก) ทำให้หลายครัวเรือนประหยัดค่าไฟได้\n(ข) กระทรวงพลังงานรณรงค์ให้ประชาชนเปลี่ยนหลอดไฟเป็น LED\n(ค) ซึ่งใช้ไฟฟ้าน้อยกว่าหลอดไส้ถึง 80%", "figure_svg": null, "choices": ["ข-ก-ค", "ข-ค-ก", "ค-ข-ก", "ก-ข-ค"], "answer": 1, "explanation": "(ข) ปูนโยบาย → (ค) ขยายว่าทำไม LED ดี (ใช้ไฟน้อย 80%) → (ก) ผลที่ตามมา (ประหยัดค่าไฟ) — ข-ค-ก ต่อเนื่องกันที่สุด ก ต้องอยู่ท้ายสุดเพราะเป็นผลลัพธ์", "shortcut": "ประโยคเหตุนำ → ประโยคขยายกลาง → ประโยคผลปิด", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0012", "subject": "analytical", "topic": "language", "subtopic": "fill_blank", "difficulty": 2, "stem": "เติมประโยคที่เหมาะสมที่สุดในช่องว่าง\n\"หนังสือออนไลน์ช่วยให้เข้าถึงความรู้ได้ทุกที่ทุกเวลา ___ อย่างไรก็ตาม ผู้อ่านควรตรวจสอบความน่าเชื่อถือของแหล่งข้อมูลก่อนนำไปใช้ทุกครั้ง\"", "figure_svg": null, "choices": ["จึงทำให้ร้านหนังสือปิดตัวลง", "และเป็นประโยชน์ต่อการเรียนรู้ตลอดชีวิต", "เพราะฉะนั้นไม่ควรอ่านหนังสือเลย", "ขณะเดียวกันก็ทำให้คนอ่านน้อยลง"], "answer": 1, "explanation": "ประโยคก่อนช่องว่างกล่าวถึงข้อดีของหนังสือออนไลน์ และหลังช่องว่างมี 'อย่างไรก็ตาม' (ขัดแย้ง) ดังนั้นช่องว่างต้องเป็นข้อดีย่อยเพิ่มเติมก่อนถึงจะขัดแย้งได้อย่างสมเหตุสมผล — ก เป็นผลเชิงลบที่ 'อย่างไรก็ตาม' ขัดแย้งกับข้อความด้านหน้าไม่ได้กับประโยคท้าย ค ขัดแย้งตรง ๆ ง ขัดแย้งในตัวเอง", "shortcut": "ดูคำสันธานหลังช่องว่างก่อน — 'อย่างไรก็ตาม' ต้องมีข้อดีมาก่อนจึงจะขัดแย้งได้", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0013", "subject": "analytical", "topic": "language", "subtopic": "sentence_order", "difficulty": 2, "stem": "เรียงลำดับข้อความให้ต่อเนื่อง\n(ก) แต่พนักงานส่วนใหญ่ยังไม่คุ้นเคยกับระบบใหม่\n(ข) บริษัทนำระบบตรวจงานอัตโนมัติมาใช้ตั้งแต่ปี 2567\n(ค) จึงต้องจัดอบรมภายในอย่างต่อเนื่อง", "figure_svg": null, "choices": ["ข-ก-ค", "ก-ข-ค", "ข-ค-ก", "ค-ก-ข"], "answer": 0, "explanation": "(ข) ปูพื้น (เริ่มใช้ระบบปี 2567) → (ก) ปัญหา (พนักงานไม่คุ้น) นำด้วย 'แต่' → (ค) ทางแก้ นำด้วย 'จึง' — ข-ก-ค เท่านั้นที่ลื่นไหล", "shortcut": "'แต่' ตามด้วยประโยคก่อนหน้า · 'จึง' ตามหลังปัญหา", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0014", "subject": "analytical", "topic": "language", "subtopic": "opening_sentence", "difficulty": 1, "stem": "ประโยคใดเหมาะเป็นประโยคเปิดย่อหน้ามากที่สุด?\n(ก) ดังนั้นการปลูกป่าจึงต้องได้รับความร่วมมือจากชุมชน\n(ข) ป่าไม้มีความสำคัญต่อระบบนิเวศของประเทศ\n(ค) ซึ่งช่วยลดผลกระทบจากฝุ่น PM2.5", "figure_svg": null, "choices": ["(ก)", "(ข)", "(ค)", "ถูกทุกข้อ"], "answer": 1, "explanation": "(ข) เป็นประโยคทั่วไปปูพื้นเรื่องป่าไม้ — เปิดได้ ส่วน (ก) มี 'ดังนั้น' ต้องอยู่หลังเหตุ ส่วน (ค) มี 'ซึ่ง' ขยายคำนามต้องต่อท้ายประโยคหลัก", "shortcut": "ประโยคเปิด = ไม่มีสันธานนำ + ครอบคลุมเรื่องกว้าง", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0015", "subject": "analytical", "topic": "language", "subtopic": "fill_blank", "difficulty": 2, "stem": "เติมประโยคที่เหมาะสมที่สุด\n\"ฝุ่น PM2.5 สูงเกินมาตรฐานติดต่อกันหลายวัน ___ กรมควบคุมมลพิษจึงประกาศเตือนประชาชนกลุ่มเสี่ยงให้หลีกเลี่ยงกิจกรรมกลางแจ้ง\"", "figure_svg": null, "choices": ["แต่ประชาชนไม่ใส่ใจ", "ส่งผลต่อสุขภาพระบบทางเดินหายใจโดยเฉพาะผู้ป่วยและเด็กเล็ก", "อย่างไรก็ดีอากาศก็ยังดีอยู่", "ทั้งนี้กรมควบคุมมลพิษปิดทำการ"], "answer": 1, "explanation": "ประโยคถัดไปขึ้นด้วย 'จึงประกาศเตือน' แสดงว่าช่องว่างต้องเป็นสาเหตุ/ผลกระทบที่นำไปสู่การเตือน — (ข) ให้ผลกระทบต่อสุขภาพพอดี ก และ ค ขัดแย้งเชิงตรรกะ ง เป็นข้อมูลแปลกปลอมไม่เกี่ยว", "shortcut": "อ่านประโยคหลังช่องว่างก่อน — 'จึงเตือน' ต้องมีผลกระทบร้ายแรงนำ", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0016", "subject": "analytical", "topic": "language", "subtopic": "sentence_order", "difficulty": 3, "stem": "เรียงลำดับ\n(ก) แต่ผลตอบแทนยังต่ำกว่าค่าเฉลี่ยอุตสาหกรรม\n(ข) บริษัทปรับแผนการตลาดใหม่เมื่อต้นปี\n(ค) ทำให้ยอดขายไตรมาสแรกเพิ่มขึ้น 12%\n(ง) ผู้บริหารจึงมอบหมายทีมขายวิเคราะห์กลยุทธ์เพิ่มเติม", "figure_svg": null, "choices": ["ข-ค-ก-ง", "ข-ก-ค-ง", "ก-ข-ค-ง", "ข-ค-ง-ก"], "answer": 0, "explanation": "(ข) ปูแผนใหม่ → (ค) ผลคือยอดขาย +12% → (ก) 'แต่' ข้อดีแต่ผลตอบแทนต่ำ → (ง) 'จึง' ผู้บริหารสั่งวิเคราะห์เพิ่ม — ข-ค-ก-ง ต่อเนื่องถูกหลัก", "shortcut": "เรียงตาม: แผน → ผลที่ได้ → ข้อจำกัด (แต่) → ทางแก้ (จึง)", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0017", "subject": "analytical", "topic": "language", "subtopic": "pronoun_reference", "difficulty": 2, "stem": "คำว่า 'สิ่งนี้' ในประโยค \"สิ่งนี้ทำให้ไฟไหม้ลุกลามรวดเร็ว\" ควรแทนข้อใดในบริบทต่อไปนี้?\n\"ผู้พักอาศัยในแฟลตวางของติดบันไดทางออกฉุกเฉิน ทำให้เมื่อเกิดไฟไหม้ ประชาชนอพยพไม่ทัน\"", "figure_svg": null, "choices": ["ไฟไหม้", "แฟลต", "การวางของกีดขวางทางออกฉุกเฉิน", "ประชาชนอพยพ"], "answer": 2, "explanation": "'สิ่งนี้' ต้องอ้างถึงมโนทัศน์ที่กล่าวไว้ก่อนหน้าและเป็นสาเหตุของไฟลุกลาม — คือ 'การวางของกีดขวางทางออกฉุกเฉิน' ซึ่งเป็นพฤติกรรมที่ข้อความระบุว่าเป็นปัญหา ก คือผลไม่ใช่สาเหตุ ข และ ง ไม่ใช่สาเหตุโดยตรง", "shortcut": "สรรพนามแทน 'เรื่อง/สิ่ง' ข้างหน้า → หาคำนามที่ 'สิ่งนี้' ชี้ถึง ต้องเป็นสาเหตุที่สอดคล้องกับผล", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0018", "subject": "analytical", "topic": "language", "subtopic": "fill_blank", "difficulty": 3, "stem": "เติมประโยคที่เหมาะสมที่สุด\n\"การรณรงค์เลิกใช้ถุงพลาสติกครั้งนี้ได้ผลดีกว่าทุกครั้งที่ผ่านมา ___ ร้านค้ากว่า 90% งดให้ถุงพลาสติกฟรี และประชาชนนำถุงผ้ามาเองมากขึ้นอย่างเห็นได้ชัด\"", "figure_svg": null, "choices": ["เพราะมีวัฒนาอย่างทั่วถึง", "เห็นได้จากพฤติกรรมของร้านค้าและประชาชน", "อย่างไรก็ตามยอดขายถุงพลาสติกลดลง", "ซึ่งสวนทางกับนโยบายรัฐบาล"], "answer": 1, "explanation": "ช่องว่างนำสู่ประโยคที่ยกหลักฐาน ('เห็นได้ชัดว่า...') ดังนั้นช่องว่างต้องเป็นประโยคที่บอกว่า 'มีหลักฐาน' — (ข) เหมาะที่สุด ก พิมพ์ผิด (วัฒนา ไม่ใช่คำไทยที่มีความหมายในบริบทนี้) ค ประโยคขัดแย้งใช้ 'อย่างไรก็ตาม' ผิดตำแหน่ง ง ขัดแย้งกับเนื้อหา", "shortcut": "ประโยคหลักฐาน → ต้องมีประโยคเกริ่นว่ามีหลักฐานนำ", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0019", "subject": "analytical", "topic": "language", "subtopic": "sentence_order", "difficulty": 1, "stem": "เรียงลำดับข้อความ\n(ก) เมื่อน้ำมาอย่างกะทันหัน พื้นที่ริมตลิ่งจึงเสียหายหนัก\n(ข) ปีนี้ฝนตกหนักติดต่อกันหลายวันในภาคเหนือ\n(ค) แม่น้ำที่เคยตื้นขึ้นสูงเกินตลิ่ง", "figure_svg": null, "choices": ["ข-ค-ก", "ค-ข-ก", "ก-ข-ค", "ข-ก-ค"], "answer": 0, "explanation": "(ข) ปูเหตุ (ฝนตกหนัก) → (ค) ผล (แม่น้ำสูงเกินตลิ่ง) → (ก) ผลสุดท้าย (น้ำมา/พื้นที่เสียหาย) — ข-ค-ก ตรงลำดับเหตุ→ผล", "shortcut": "เหตุ (ฝน) → กลาง (น้ำขึ้น) → ผล (เสียหาย)", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0020", "subject": "analytical", "topic": "language", "subtopic": "closing_sentence", "difficulty": 2, "stem": "ประโยคใดเหมาะเป็นประโยคปิดย่อหน้า\n\"การออกกำลังกายช่วยลดความเครียด (ก) เพราะร่างกายหลั่งสารเอ็นโดรฟิน (ข) ___ (ง) ดังนั้นผู้ที่เครียดบ่อยควรจัดเวลาออกกำลังกายสม่ำเสมอ\"", "figure_svg": null, "choices": ["ซึ่งสารนี้ทำให้รู้สึกสบายและผ่อนคลาย", "แม้ว่าจะไม่มีเวลาเลยก็ตาม", "แต่การออกกำลังกายทำให้เหนื่อย", "ทั้งนี้กีฬาคือสิ่งที่ทุกคนต้องชอบ"], "answer": 0, "explanation": "ช่องว่างอยู่ระหว่างเหตุ (สารเอ็นโดรฟิน) และข้อสรุป — ต้องเป็นประโยคขยายความสารเอ็นโดรฟิน → (ก) ลงตัว ข 'แม้ว่า' ขัดแย้งกับสรุปตรรกะ ค เป็นข้อเสียที่ทำลายน้ำหนักสรุป ง สุดโต่งเกิน", "shortcut": "ช่องว่างก่อน 'ดังนั้น' → ต้องเป็นหลักฐานสนับสนุนที่นำไปสู่ข้อสรุปนั้น", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0021", "subject": "analytical", "topic": "language", "subtopic": "word_choice", "difficulty": 1, "stem": "เติมคำให้เหมาะสมที่สุดในบริบททางราชการ\n\"หากผู้ประสงค์ยื่นคำขอไม่ครบถ้วน ให้เจ้าหน้าที่แจ้งให้ ___ ภายใน 15 วัน\"", "figure_svg": null, "choices": ["แก้ไข", "กลับบ้าน", "ยอมแพ้", "ร้องเรียน"], "answer": 0, "explanation": "บริบทเอกสารราชการพูดถึงเอกสารไม่ครบถ้วน — สิ่งที่ต้องทำคือแก้ไขเอกสารให้ครบ ✅ ตัวเลือกอื่นไม่เกี่ยวกับขั้นตอนราชการ", "shortcut": "ดูบริบท (คำขอ/เอกสาร/แจ้ง) → คำที่เหลือภาษาทางการเท่านั้น", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0022", "subject": "analytical", "topic": "language", "subtopic": "word_choice", "difficulty": 1, "stem": "ข้อใดใช้คำ 'ได้รับการ' ถูกต้อง", "figure_svg": null, "choices": ["ได้รับการเงินเดือน", "ได้รับการแต่งตั้ง", "ได้รับการเงินกู้", "ได้รับการสินค้า"], "answer": 1, "explanation": "'ได้รับการ' ต้องตามด้วยกริยา (แต่งตั้ง = กริยา) — ส่วน 'เงินเดือน/เงินกู้/สินค้า' เป็นคำนาม ต้องใช้ 'ได้รับ' ตรง ๆ (ได้รับเงินเดือน ได้รับเงินกู้ ได้รับสินค้า)", "shortcut": "ได้รับการ + กริยา · ได้รับ + คำนาม", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0023", "subject": "analytical", "topic": "language", "subtopic": "concision", "difficulty": 2, "stem": "เลือกประโยคที่กระชับและถูกต้องที่สุด", "figure_svg": null, "choices": ["เพื่อที่จะเป็นการลดปริมาณขยะ เทศบาลจึงได้ทำการดำเนินการแยกขยะ", "เทศบาลจึงได้กระทำการแยกขยะเพื่อเป็นการลดขยะ", "เพื่อลดปริมาณขยะ เทศบาลจึงดำเนินการแยกขยะ", "เรื่องก็คือเทศบาลจะแยกขยะเพื่อลดขยะ"], "answer": 2, "explanation": "ค. ตัดคำฟุ่มเฟือย 'เพื่อที่จะเป็นการ' → 'เพื่อ' และ 'ได้ทำการดำเนินการ' → 'ดำเนินการ' — ก และ ข ฟุ่มเฟือย ง เป็นภาษาพูด", "shortcut": "หาประโยคที่สั้นที่สุดที่ยังครบความหมายและเป็นทางการ", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0024", "subject": "analytical", "topic": "language", "subtopic": "word_choice", "difficulty": 2, "stem": "เติมคำ 'ประมาณ' หรือ 'คาด' ให้ถูกความหมาย\n\"มีผู้เข้าร่วมอบรม ___ 300 คน และ ___ ว่าจะเพิ่มขึ้นทุกปี\"", "figure_svg": null, "choices": ["ประมาณ / ประมาณ", "คาด / ประมาณ", "ประมาณ / คาด", "คาด / คาด"], "answer": 2, "explanation": "'ประมาณ' ใช้กับตัวเลข (≈ 300 คน) · 'คาด' ใช้กับการคาดการณ์อนาคต (คาดว่าจะเพิ่มขึ้น) — ดังนั้นคือ ประมาณ / คาด", "shortcut": "ตัวเลข → ประมาณ · อนาคต/การณ์ → คาด", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0025", "subject": "analytical", "topic": "language", "subtopic": "structure_error", "difficulty": 2, "stem": "ประโยคใดกำกวมมากที่สุด", "figure_svg": null, "choices": ["เขาพบผู้จัดการที่ตึก A", "เขาพบผู้จัดการกับพนักงานที่ตึก A", "เธออ่านหนังสือที่ห้องสมุด", "เราประชุมกันที่ห้องประชุม"], "answer": 1, "explanation": "'เขาพบผู้จัดการกับพนักงานที่ตึก A' — ใครอยู่ที่ตึก A? ผู้จัดการ? พนักงาน? ทั้งคู่? กำกวม — ก เป็นประโยคปกติ (เขาพบผู้จัดการ ที่ตึก A — ไม่มีคำว่า 'กับ' ที่ทำให้กำกวม) ค และ ง ชัดเจน", "shortcut": "คำว่า 'กับ' กลางประโยค → ดูว่าแปลว่า 'พร้อมกับ' หรือ 'และ' กำกวมแน่", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0026", "subject": "analytical", "topic": "language", "subtopic": "register", "difficulty": 3, "stem": "ข้อใดเป็นภาษาราชการที่ถูกต้อง", "figure_svg": null, "choices": ["ถ้ามีปัญหาให้ติดต่อสำนักงาน", "หากมีปัญหากรุณาติดต่อสำนักงาน", "ถ้าเกิดปัญหาขึ้นมาก็โทรมาได้เลย", "มีปัญหาก็ให้ติดต่อสำนักงานนะ"], "answer": 1, "explanation": "'หาก' ทางการกว่า 'ถ้า' และ 'กรุณา' สุภาพทางการ — ก ใช้ 'ถ้า' กึ่งทางการ ค และ ง เป็นภาษาพูด", "shortcut": "เอกสารราชการ: หาก / กรุณา / โปรด / ณ", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0027", "subject": "analytical", "topic": "language", "subtopic": "word_choice", "difficulty": 2, "stem": "เติมคำที่ถูกต้อง\n\"คณะกรรมการ ___ มติให้ขยายเวลาโครงการอีก 6 เดือน\"", "figure_svg": null, "choices": ["ทำ", "มี", "ให้", "เอา"], "answer": 1, "explanation": "'มีมติ' เป็นคำสำเร็จรูปทางราชการ (ใช้ 'มีมติว่า') — 'ทำมติ/ให้มติ/เอามติ' ไม่ถูกหลัก", "shortcut": "จดจำคำสำเร็จรูป: มีมติ · อนุมัติ · สั่งการ · รายงานต่อ", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0028", "subject": "analytical", "topic": "language", "subtopic": "structure_error", "difficulty": 3, "stem": "ข้อใดใช้คำเชื่อมประโยคได้ถูกต้อง", "figure_svg": null, "choices": ["ฝนตกหนัก ดังนั้นถนนจึงน้ำท่วม", "ฝนตกหนัก เพราะฉะนั้นถนนน้ำท่วม", "ฝนตกหนัก จึงเพราะถนนน้ำท่วม", "ฝนตกหนัก หากถนนน้ำท่วม"], "answer": 0, "explanation": "'ดังนั้น…จึง' เป็นคู่คำเชื่อมเหตุ→ผลที่ถูกหลัก — ข ตัด 'จึง' ทิ้ง ทำให้ประโยคหลวม ค สลับคำผิดที่ ง 'หาก' ใช้กับเงื่อนไข ไม่ใช่ผลที่เกิดแล้ว", "shortcut": "คู่คำเชื่อม: ดังนั้น…จึง · เพราะ…จึง · ถึงแม้…แต่ · หาก…ก็", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0029", "subject": "analytical", "topic": "language", "subtopic": "redundancy", "difficulty": 1, "stem": "ข้อใดมีคำฟุ่มเฟือยมากที่สุด", "figure_svg": null, "choices": ["หน่วยงานดำเนินการแก้ไขปัญหา", "เพื่อที่จะเป็นการอำนวยความสะดวก หน่วยงานจึงได้ทำการดำเนินการจัดเตรียมสถานที่", "เทศบาลซ่อมถนน", "กรมชลประทานขุดลอกคูคลอง"], "answer": 1, "explanation": "ข. มีคำฟุ่มเฟือยซ้ำซ้อน: 'เพื่อที่จะเป็นการ'→เพื่อ, 'ได้ทำการดำเนินการ'→ดำเนินการ — ก กระชับพอใช้ ค และ ง สั้นกระชับมาก", "shortcut": "นับจำนวนคำ 'การ/ที่จะ/เพื่อที่จะ/ได้ทำการ' — ยิ่งเยอะยิ่งฟุ่มเฟือย", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0030", "subject": "analytical", "topic": "language", "subtopic": "word_choice", "difficulty": 3, "stem": "เลือกคำให้เหมาะสมที่สุด\n\"คณะทำงาน ___ มติให้เลื่อนการประชุมออกไปอีกหนึ่งสัปดาห์\"", "figure_svg": null, "choices": ["ลง", "มี", "ทำ", "ให้"], "answer": 1, "explanation": "'มีมติ' เป็นศัพท์ราชการที่ถูก — ก/ค/ง ผิดหลัก ใช้กับ 'มติ' ไม่ได้", "shortcut": "'มติ' คู่กับ 'มี' เท่านั้น (มีมติว่า/มีมติให้)", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0031", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 1, "stem": "ดำ : ขาว :: ใหญ่ : ?", "figure_svg": null, "choices": ["เล็ก", "ยาว", "กว้าง", "มาก"], "answer": 0, "explanation": "ดำ↔ขาว เป็นคำตรงข้าม → ใหญ่↔เล็ก เป็นคำตรงข้ามเช่นกัน — ตัวเลือกอื่นไม่ใช่คู่ตรงข้ามของ 'ใหญ่'", "shortcut": "ระบุความสัมพันธ์คู่แรกก่อนเสมอ (ที่นี่คือคำตรงข้าม)", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0032", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 1, "stem": "มือ : นิ้ว :: เท้า : ?", "figure_svg": null, "choices": ["ขา", "นิ้วเท้า", "รองเท้า", "เดิน"], "answer": 1, "explanation": "นิ้ว คือส่วนประกอบส่วนปลายของมือ → นิ้วเท้า คือส่วนประกอบส่วนปลายของเท้า — ขารวมทั้งขา ไม่ใช่ส่วนปลายเหมือนนิ้ว รองเท้าเป็นเครื่องสวมใส่ เดินเป็นกริยา", "shortcut": "มือ→นิ้ว คือ 'ส่วนปลายของร่างกาย' เท้าจึง→นิ้วเท้า", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0033", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 2, "stem": "นาฬิกา : บอกเวลา :: แว่นตา : ?", "figure_svg": null, "choices": ["ตา", "มองเห็น", "แสง", "อ่านหนังสือ"], "answer": 1, "explanation": "นาฬิกามีหน้าที่บอกเวลา → แว่นตามีหน้าที่ช่วยให้มองเห็นได้ชัด — ตาคืออวัยวะไม่ใช่หน้าที่ แสงไม่ใช่หน้าที่ อ่านหนังสือแคบเกิน (แว่นใช้มากกว่าอ่าน)", "shortcut": "เครื่องมือ : หน้าที่ของเครื่องมือ", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0034", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 2, "stem": "กุหลาบ : ดอกไม้ :: จระเข้ : ?", "figure_svg": null, "choices": ["บ่อน้ำ", "สัตว์เลื้อยคลาน", "ฟัน", "น่านน้ำ"], "answer": 1, "explanation": "กุหลาบคือชนิดหนึ่งของดอกไม้ (ตัวอย่างของกลุ่ม) → จระเข้คือชนิดหนึ่งของสัตว์เลื้อยคลาน — บ่อน้ำ/น่านน้ำคือถิ่นที่อยู่ ฟันคือส่วนประกอบ แต่ไม่ใช่ความสัมพันธ์ 'ตัวอย่าง/กลุ่ม'", "shortcut": "ตัวอย่าง : กลุ่มใหญ่", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0035", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 2, "stem": "เสื้อ : ผ้า :: เก้าอี้ : ?", "figure_svg": null, "choices": ["ไม้", "โต๊ะ", "ห้อง", "นั่ง"], "answer": 0, "explanation": "เสื้อทำจากผ้า (วัตถุทำจากวัสดุ) → เก้าอี้ทำจากไม้ — โต๊ะคือของคู่กัน ห้องคือที่เก็บ นั่งคือหน้าที่", "shortcut": "วัตถุ : วัสดุที่ใช้ทำ", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0036", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 3, "stem": "จับ : จับกุม :: ช่วย : ?", "figure_svg": null, "choices": ["ช่วยเหลือ", "ช่วยงาน", "ช่วยชีวิต", "ช่วยดูแล"], "answer": 0, "explanation": "'จับกุม' เป็นคำซ้อนความหมาย (คำเดียว + คำพ้องความหมาย) แบบศัพท์ราชการ → 'ช่วยเหลือ' เป็นคำซ้อนแบบเดียวกัน — ช่วยงาน/ช่วยชีวิต/ช่วยดูแล เป็นคำประสมที่จำกัดความหมาย (b ชนิดของ A ไม่ใช่รูปซ้อน)", "shortcut": "คำซ้อนทางราชการ: จับ→จับกุม · ช่วย→ช่วยเหลือ · สั่ง→สั่งการ", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0037", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 2, "stem": "ฝน : น้ำท่วม :: ภัยแล้ง : ?", "figure_svg": null, "choices": ["ฝน", "พืชผลเสียหาย", "ร้อน", "ฤดู"], "answer": 1, "explanation": "ฝนเป็นสาเหตุที่ทำให้น้ำท่วม → ภัยแล้งเป็นสาเหตุที่ทำให้พืชผลเสียหาย — ร้อนคือลักษณะ ฝนคือสิ่งตรงข้าม ฤดูคือบริบทกว้าง", "shortcut": "เหตุ : ผล", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0038", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 3, "stem": "ชาวนา : นา :: ชาวเรือ : ?", "figure_svg": null, "choices": ["ทะเล", "เรือ", "ปลา", "ท่าเรือ"], "answer": 0, "explanation": "ชาวนาทำงานในนา → ชาวเรือทำงานในทะเล (ถิ่นทำงาน) — เรือคือเครื่องมือ ปลาคือผลผลิต ท่าเรือคือสถานที่แวะพัก ไม่ใช่ถิ่นทำงานโดยตรงในความหมายเดียวกัน", "shortcut": "อาชีพ : สถานที่ทำงาน", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0039", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 1, "stem": "ปลอด : มัวหมอง :: สะอาด : ?", "figure_svg": null, "choices": ["สวย", "สว่าง", "สกปรก", "ขาว"], "answer": 2, "explanation": "ปลอด↔มัวหมอง คือคำตรงข้ามเชิงคุณภาพ → สะอาด↔สกปรก คือคำตรงข้ามเชิงคุณภาพเช่นเดียวกัน — สวย/สว่าง/ขาว ไม่ใช่คู่ตรงข้ามของสะอาดโดยตรง", "shortcut": "กลับมาที่ความสัมพันธ์คู่แรก: คำตรงข้าม", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0040", "subject": "analytical", "topic": "language", "subtopic": "analogy", "difficulty": 3, "stem": "กฎหมาย : บังคับ :: ศีลธรรม : ?", "figure_svg": null, "choices": ["ลงโทษ", "แนะนำ", "ชี้แนะ", "ควบคุม"], "answer": 1, "explanation": "กฎหมายมีลักษณะบังคับ (enforceable) → ศีลธรรมมีลักษณะแนะนำ/ชี้แนะด้วยมโนธรรม ไม่บังคับ — ระหว่าง 'แนะนำ' กับ 'ชี้แนะ': คำสำเร็จรูปคู่กับ ศีลธรรม คือ 'แนะนำ' (คู่ที่มักออกสอบ: กฎหมาย=บังคับ, ศีลธรรม=แนะนำ, มารยาท=กริยาอาการ) ลงโทษ/ควบคุมคืออำนาจกฎหมาย", "shortcut": "กฎหมาย=บังคับ · ศีลธรรม=แนะนำ · มารยาท=พึงประพฤติ", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0041", "subject": "analytical", "topic": "language", "subtopic": "conditionals", "difficulty": 1, "stem": "เงื่อนไข: 'ถ้าฝนตก ถนนจะเปียก' — ข้อใดสรุปได้ถูกต้อง?", "figure_svg": null, "choices": ["ถนนเปียก แสดงว่าฝนตก", "ถ้าถนนไม่เปียก แสดงว่าฝนไม่ตก", "ฝนไม่ตก ถนนไม่เปียก", "ฝนตกเสมอ"], "answer": 1, "explanation": "P→Q สมมูลกับ contrapositive: ไม่ Q→ไม่ P คือ 'ถนนไม่เปียก → ฝนไม่ตก' — ก สลับทิศโดยไม่ negate (ถนนอาจเปียกจากรถน้ำ) ค คือ inverse ไม่สมมูล ง ไม่เกี่ยว", "shortcut": "P→Q → จำกฎ: ไม่ Q ไม่ P", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0042", "subject": "analytical", "topic": "language", "subtopic": "conditionals", "difficulty": 1, "stem": "เงื่อนไข: 'ข้าราชการทุกคนต้องเคารพกฎหมาย' — ข้อใดถูกต้อง?", "figure_svg": null, "choices": ["คนที่เคารพกฎหมายทุกคนเป็นข้าราชการ", "ถ้าไม่เคารพกฎหมาย แสดงว่าไม่ใช่ข้าราชการ", "ข้าราชการบางคนไม่เคารพกฎหมาย", "ไม่มีคนเคารพกฎหมายที่เป็นข้าราชการ"], "answer": 1, "explanation": "ข้าราชการ → เคารพกฎหมาย (P→Q) contrapositive: ไม่เคารพ → ไม่ใช่ข้าราชการ — ก เป็น Q→P ไม่สมมูล ค และ ง ขัดแย้งกับเงื่อนไขเดิม", "shortcut": "'ทุกคนที่ X ต้อง Y' = X→Y · กลับโดย negate ทั้งคู่", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0043", "subject": "analytical", "topic": "language", "subtopic": "necessary_condition", "difficulty": 2, "stem": "เงื่อนไข: 'หากโครงการจะเริ่มดำเนินการได้ ต้องได้รับความเห็นชอบจากคณะรัฐมนตรี' — ข้อใดถูกต้อง?", "figure_svg": null, "choices": ["ได้รับความเห็นชอบแล้ว → เริ่มได้ทันที", "เริ่มดำเนินการได้ → ได้รับความเห็นชอบแล้ว", "ไม่ได้รับความเห็นชอบ → เริ่มได้", "คณะรัฐมนตรีเห็นชอบทุกโครงการเสมอ"], "answer": 1, "explanation": "'ต้อง…จึงจะ…' = เงื่อนไขจำเป็น: เริ่มได้ → เห็นชอบแล้ว (Q→P) — ก สลับเป็นเพียงพอซึ่งไม่จำเป็น (เห็นชอบแล้วยังอาจขาดเงื่อนไขอื่นได้) ค ขัดแย้งกับเงื่อนไข ง สุดโต่งเกิน", "shortcut": "'ต้อง…จึงจะ…' อ่านกลับ: สิ่งที่ได้ → สิ่งที่ต้องมี", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0044", "subject": "analytical", "topic": "language", "subtopic": "chain", "difficulty": 2, "stem": "เงื่อนไข: (1) ถ้า A แล้ว B (2) ถ้า B แล้ว C (3) C เท็จ — สรุปได้ว่าอย่างไร?", "figure_svg": null, "choices": ["A จริง", "A เท็จ", "B จริง", "ไม่มีข้อสรุป"], "answer": 1, "explanation": "จาก (2) B→C และ C เท็จ → contrapositive: ไม่ C → ไม่ B → B เท็จ จาก (1) A→B และ B เท็จ → ไม่ B → ไม่ A → A เท็จ", "shortcut": "ไล่ contrapositive ทีละขั้นจากสิ่งที่รู้สุดท้าย (C เท็จ) ย้อนกลับ", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0045", "subject": "analytical", "topic": "language", "subtopic": "biconditional", "difficulty": 2, "stem": "เงื่อนไข: 'พนักงานจะเลื่อนตำแหน่งได้ก็ต่อเมื่อผลงานดีเยี่ยมติดต่อกัน 2 ปี' — ข้อใดถูกต้อง?", "figure_svg": null, "choices": ["ผลงานดีเยี่ยม 2 ปี → เลื่อนตำแหน่ง", "เลื่อนตำแหน่ง → ผลงานดีเยี่ยม 2 ปี", "ถูกทั้ง ก และ ข", "ผลงานดีเยี่ยม 1 ปีก็เลื่อนได้"], "answer": 2, "explanation": "'ก็ต่อเมื่อ' (if and only if) หมายถึง ↔ ทั้งไปและกลับ: เลื่อน → ดีเยี่ยม 2 ปี และ ดีเยี่ยม 2 ปี → เลื่อน จึงถูกทั้ง ก และ ข — ง ขัดแย้งกับเงื่อนไข (ต้อง 2 ปี)", "shortcut": "'ก็ต่อเมื่อ' = สองทิศเสมอ (↔)", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0046", "subject": "analytical", "topic": "language", "subtopic": "some_vs_all", "difficulty": 3, "stem": "เงื่อนไข: 'พนักงานบางคนที่ทำงานเกินเวลาได้รับโบนัสพิเศษ' — ข้อใดสรุปได้?", "figure_svg": null, "choices": ["พนักงานทุกคนที่ทำงานเกินเวลาได้รับโบนัส", "มีพนักงานที่ทำงานเกินเวลาอย่างน้อย 1 คนที่ได้รับโบนัส", "ไม่มีพนักงานทำงานเกินเวลาที่ไม่ได้รับโบนัส", "โบนัสพิเศษให้เฉพาะผู้ทำงานเกินเวลา"], "answer": 1, "explanation": "'บางคน' = มีอย่างน้อย 1 คน ดังนั้นสรุปได้แค่ว่ามีอย่างน้อย 1 คนที่ทำงานเกินเวลาและรับโบนัส — ก เหมารวมเกิน (บาง ≠ ทุก) ค เป็น 'ไม่มี...ไม่' = ทุก (เกิน) ง ไม่มีข้อมูลว่าเฉพาะกลุ่มนี้", "shortcut": "'บางคน' สรุปได้แค่ 'มีอย่างน้อย 1 คน' ห้ามขยายเป็น 'ทุกคน'", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0047", "subject": "analytical", "topic": "language", "subtopic": "conditionals", "difficulty": 2, "stem": "เงื่อนไข: 'ถ้าเอกสารครบถ้วน เจ้าหน้าที่จะดำเนินการให้ทันที' — จากเงื่อนไข ข้อใด 'เป็นไปไม่ได้'?", "figure_svg": null, "choices": ["เอกสารครบ และดำเนินการทันที", "เอกสารครบ และเจ้าหน้าที่ไม่ดำเนินการ", "เอกสารไม่ครบ และดำเนินการก็ได้", "เอกสารไม่ครบ และไม่ดำเนินการ"], "answer": 1, "explanation": "P→Q เท็จเฉพาะกรณี P จริง Q เท็จ คือ 'เอกสารครบ แต่เจ้าหน้าที่ไม่ดำเนินการ' — เป็นไปไม่ได้ตามเงื่อนไข ตัวเลือกอื่นเกิดได้หมด (P เท็จแล้ว Q จะจริงหรือเท็จก็ได้)", "shortcut": "P→Q เท็จเฉพาะ P จริง + Q เท็จ — หากรณีนั้นเจอ ตอบเลย", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0048", "subject": "analytical", "topic": "language", "subtopic": "negation", "difficulty": 3, "stem": "เงื่อนไข: 'หากใบสมัครไม่ครบถ้วน หน่วยงานจะไม่พิจารณา' — ข้อใดสมมูลกับเงื่อนไขนี้?", "figure_svg": null, "choices": ["ถ้าหน่วยงานพิจารณา ใบสมัครต้องครบถ้วน", "ถ้าใบสมัครครบถ้วน หน่วยงานจะพิจารณา", "ถ้าหน่วยงานไม่พิจารณา ใบสมัครไม่ครบถ้วน", "ใบสมัครครบถ้วนทุกใบจะได้รับพิจารณา"], "answer": 0, "explanation": "เงื่อนไขคือ: ไม่ครบ → ไม่พิจารณา (¬P→¬Q) ซึ่งสมมูล contrapositive: Q→P คือ 'พิจารณา → ครบถ้วน' — ข คือ P→Q ที่ไม่เกี่ยวโดยตรง (ไม่ครบไม่พิจารณา ไม่ได้บอกว่าครบแล้วพิจารณา) ค คือ ¬Q→¬P ซึ่งคือ inverse ไม่สมมูล ง เกินเงื่อนไข", "shortcut": "เขียน symbolic: ¬P→¬Q มี contrapositive คือ Q→P", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0049", "subject": "analytical", "topic": "language", "subtopic": "chain", "difficulty": 3, "stem": "เงื่อนไข: (1) ถ้าระบบขัดข้อง งานจะล่าช้า (2) ถ้างานล่าช้า ลูกค้าจะร้องเรียน (3) ลูกค้าไม่ร้องเรียน — สรุปได้ว่า?", "figure_svg": null, "choices": ["ระบบขัดข้อง", "งานไม่ล่าช้า", "ทั้งระบบไม่ขัดข้องและงานไม่ล่าช้า", "ไม่มีข้อใดสรุปได้"], "answer": 2, "explanation": "จาก (2) งานล่าช้า→ร้องเรียน และ 'ไม่ร้องเรียน' → contrapositive: ไม่ร้องเรียน → งานไม่ล่าช้า จาก (1) ระบบขัดข้อง→ล่าช้า และ 'ไม่ล่าช้า' → ไม่ระบบขัดข้อง สรุปได้ทั้งสอง: งานไม่ล่าช้า และระบบไม่ขัดข้อง", "shortcut": "ไล่ contrapositive ย้อนขั้นตอน: ไม่ร้องเรียน → ไม่ล่าช้า → ระบบไม่ขัดข้อง", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-LANG-0050", "subject": "analytical", "topic": "language", "subtopic": "necessary_condition", "difficulty": 1, "stem": "เงื่อนไข: 'ผู้จะเข้ารับราชการต้องผ่านการสอบแข่งขัน' — ข้อใดสรุปได้?", "figure_svg": null, "choices": ["ผ่านสอบแข่งขัน → เข้ารับราชการ", "เข้ารับราชการ → ผ่านสอบแข่งขัน", "ไม่ผ่านสอบก็เข้ารับราชการได้", "ทุกคนที่ผ่านสอบจะได้เข้ารับราชการ"], "answer": 1, "explanation": "'ต้อง…จึง…' = เงื่อนไขจำเป็น: เข้ารับราชการ → ผ่านสอบ — ก เป็นทิศเพียงพอ (ผ่านสอบแล้วอาจไม่ครบขั้นตอนอื่น เช่น ตรวจสุขภาพ) ค ขัดแย้งชัด ง เหมารวมเกิน", "shortcut": "'ต้อง P' คือ P จำเป็นต่อ Q: Q→P", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0001", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 1, "stem": "5, 9, 13, 17, 21, ?", "figure_svg": null, "choices": ["23", "24", "25", "26"], "answer": 2, "explanation": "ผลต่างพจน์ติดกันคือ +4 เสมอ (9-5=4, 13-9=4, ...) ดังนั้น 21+4 = 25 — ข้ออื่นข้ามผลต่างคงที่ของอนุกรมเลขคณิตนี้", "shortcut": "เขียนผลต่างเหนือลูกศรระหว่างพจน์ — ถ้าคงที่ ตอบผลต่างนั้น", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0002", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 1, "stem": "2, 6, 18, 54, ?", "figure_svg": null, "choices": ["108", "144", "162", "216"], "answer": 2, "explanation": "อัตราส่วนพจน์ติดกันคือ ×3 (6÷2=3, 18÷6=3, 54÷18=3) ดังนั้น 54×3 = 162", "shortcut": "ลองหารพจน์ติดกัน — ถ้าคงที่เป็นอนุกรมเรขาคณิต", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0003", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 2, "stem": "1, 3, 6, 10, 15, ?", "figure_svg": null, "choices": ["18", "20", "21", "25"], "answer": 2, "explanation": "ผลต่างคือ +2, +3, +4, +5 เพิ่มทีละ 1 — ผลต่างถัดไปคือ +6 ดังนั้น 15+6 = 21 (เป็นเลขสามเหลี่ยม)", "shortcut": "ผลต่างเพิ่มขึ้นทีละ 1 เสมอ → ใช้ผลต่างถัดไป", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0004", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 2, "stem": "3, 7, 13, 21, 31, ?", "figure_svg": null, "choices": ["41", "43", "45", "47"], "answer": 1, "explanation": "ผลต่างชั้นที่ 1: +4, +6, +8, +10 (เพิ่มทีละ 2) → ผลต่างถัดไปคือ +12 → 31+12 = 43 (ผลต่างชั้นสองคงที่ = 2)", "shortcut": "ผลต่างชั้นสองคงที่ → บวกผลต่างล่าสุด + ผลต่างชั้นสอง", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0005", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 2, "stem": "2, 3, 5, 8, 13, ?", "figure_svg": null, "choices": ["18", "19", "20", "21"], "answer": 3, "explanation": "แต่ละพจน์ = ผลบวกของ 2 พจน์ก่อนหน้า (3=2+1, 5=3+2, 8=5+3, 13=8+5) → ถัดไป 8+13 = 21 (ฟีโบนักชี)", "shortcut": "ถ้าผลต่างไม่คงที่ ลองบวกสองพจน์ก่อนหน้า", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0006", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 1, "stem": "1, 4, 9, 16, 25, ?", "figure_svg": null, "choices": ["30", "32", "36", "49"], "answer": 2, "explanation": "เป็นกำลังสองของ 1,2,3,4,5 → ถัดไปคือ 6² = 36", "shortcut": "จำตารางกำลังสอง: 1,4,9,16,25,36,49,64,81,100", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0007", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 3, "stem": "3, 6, 12, 21, 33, ?", "figure_svg": null, "choices": ["42", "45", "46", "48"], "answer": 3, "explanation": "ผลต่าง: +3, +6, +9, +12 (เพิ่มทีละ 3) → ถัดไป +15 → 33+15 = 48", "shortcut": "ผลต่างชั้นเดียวโตเป็นลำดับเท่า ๆ กัน บวกพจน์ล่าสุดด้วยผลต่างถัดไป", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0008", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 1, "stem": "7, 14, 28, 56, ?", "figure_svg": null, "choices": ["96", "98", "112", "120"], "answer": 2, "explanation": "อัตราส่วนคงที่ ×2 → 56×2 = 112", "shortcut": "ตรวจอัตราส่วนก่อนเสมอถ้าเลขขยับเร็ว", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0009", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 3, "stem": "5, 7, 10, 15, 22, ?", "figure_svg": null, "choices": ["29", "31", "33", "35"], "answer": 2, "explanation": "ผลต่าง: +2, +3, +5, +7 เป็นจำนวนเฉพาะต่อเนื่อง → จำนวนเฉพาะถัดไปคือ 11 → 22+11 = 33", "shortcut": "ผลต่างเป็นจำนวนเฉพาะ 2,3,5,7,11 — จำลำดับจำนวนเฉพาะ", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0010", "subject": "analytical", "topic": "abstract", "subtopic": "number_sequence", "difficulty": 2, "stem": "1, 8, 27, 64, ?", "figure_svg": null, "choices": ["100", "121", "125", "216"], "answer": 2, "explanation": "เป็นกำลังสามของ 1,2,3,4 → ถัดไปคือ 5³ = 125", "shortcut": "จำกำลังสาม: 1,8,27,64,125,216", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0011", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 1, "stem": "B, D, G, K, P, ?", "figure_svg": null, "choices": ["U", "V", "W", "X"], "answer": 1, "explanation": "แปลงเป็นตัวเลข: B=2, D=4, G=7, K=11, P=16 → ผลต่าง +2, +3, +4, +5 → ถัดไป +6 → 16+6 = 22 = V", "shortcut": "เขียนตำแหน่ง A=1 ถึง Z=26 แล้วหาผลต่าง", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0012", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 2, "stem": "Z, X, V, T, ?", "figure_svg": null, "choices": ["P", "R", "S", "Q"], "answer": 1, "explanation": "ลำดับถอยหลังทีละ 2 ตัวอักษร (Z→X→V→T) → T ถอย 2 คือ R (T=20, 20-2=18=R)", "shortcut": "ลำดับถอย: ลบค่าตำแหน่งแล้วแปลงกลับ", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0013", "subject": "analytical", "topic": "abstract", "subtopic": "figure_sequence", "difficulty": 1, "stem": "รูปสี่เหลี่ยมจัตุรัสมีจุดอยู่ภายใน 1 จุด, 2 จุด, 3 จุด ตามลำดับ — รูปถัดไปมีกี่จุด?", "figure_svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 300 80' width='300' height='80' role='img' aria-label='กรอบสี่เหลี่ยมสามรูป มีจุด 1 2 3 จุด'><rect x='10' y='10' width='60' height='60' fill='none' stroke='#333' stroke-width='2'/><circle cx='40' cy='40' r='4' fill='#1d4ed8'/><rect x='110' y='10' width='60' height='60' fill='none' stroke='#333' stroke-width='2'/><circle cx='135' cy='32' r='4' fill='#1d4ed8'/><circle cx='148' cy='50' r='4' fill='#1d4ed8'/><rect x='210' y='10' width='60' height='60' fill='none' stroke='#333' stroke-width='2'/><circle cx='230' cy='30' r='4' fill='#1d4ed8'/><circle cx='245' cy='45' r='4' fill='#1d4ed8'/><circle cx='225' cy='55' r='4' fill='#1d4ed8'/></svg>", "choices": ["3 จุด", "4 จุด", "5 จุด", "6 จุด"], "answer": 1, "explanation": "จำนวนจุดเพิ่มขึ้นทีละ 1 (1, 2, 3) → รูปถัดไปคือ 4 จุด", "shortcut": "นับองค์ประกอบที่เปลี่ยนในแต่ละขั้น — จำนวนคือจุดเปลี่ยนแรกที่ควรดู", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0014", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 3, "stem": "A, Z, B, Y, C, ?", "figure_svg": null, "choices": ["D", "X", "W", "A"], "answer": 1, "explanation": "อนุกรมสลับ: พจน์คี่ไปหน้า A, B, C... (+1) พจน์คู่ถอยหลัง Z, Y... (–1) → พจน์ถัดไป (ลำดับ 6 คู่) คือ X (หลัง Y คือ X)", "shortcut": "อนุกรมสลับ → แยกพจน์คี่และพจน์คู่ดูทีละชุด", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0015", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 1, "stem": "A, C, E, G, I, ?", "figure_svg": null, "choices": ["J", "K", "L", "M"], "answer": 1, "explanation": "พยัญชนะ/สระ ไม่เกี่ยว — ตำแหน่งเลื่อน +2 เสมอ (A=1, C=3, E=5, G=7, I=9) → ถัดไป 11 = K", "shortcut": "ข้ามทีละ 2 ตำแหน่ง", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0016", "subject": "analytical", "topic": "abstract", "subtopic": "figure_sequence", "difficulty": 2, "stem": "ลูกศรชี้ทิศ ขวา, ลง, ซ้าย ตามลำดับ — รูปถัดไปชี้ทิศใด?", "figure_svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 300 80' width='300' height='80' role='img' aria-label='ลูกศรสามตัว ชี้ขวา ลง ซ้าย'><line x1='15' y1='40' x2='55' y2='40' stroke='#1d4ed8' stroke-width='3'/><polygon points='55,34 67,40 55,46' fill='#1d4ed8'/><line x1='115' y1='15' x2='115' y2='55' stroke='#1d4ed8' stroke-width='3'/><polygon points='109,55 115,67 121,55' fill='#1d4ed8'/><line x1='215' y1='40' x2='255' y2='40' stroke='#1d4ed8' stroke-width='3'/><polygon points='215,34 203,40 215,46' fill='#1d4ed8'/></svg>", "choices": ["ขวา", "ขึ้น", "ซ้าย", "ลง"], "answer": 1, "explanation": "ลูกศรหมุนตามเข็มนาฬิกา 90° ทุกขั้น (ขวา → ลง → ซ้าย → ) ถัดไปคือหมุน 90° อีกครั้ง = ชี้ขึ้น", "shortcut": "การหมุน 90° วนซ้ำทุก 4 ขั้น: ขวา-ลง-ซ้าย-ขึ้น", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0017", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 2, "stem": "C, E, H, L, Q, ?", "figure_svg": null, "choices": ["U", "V", "W", "X"], "answer": 2, "explanation": "C=3, E=5, H=8, L=12, Q=17 → ผลต่าง +2, +3, +4, +5 → ถัดไป +6 → 17+6 = 23 = W", "shortcut": "ผลต่างเพิ่มขึ้นทีละ 1 เสมอ", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0018", "subject": "analytical", "topic": "abstract", "subtopic": "figure_sequence", "difficulty": 3, "stem": "รูปสามเหลี่ยม, สี่เหลี่ยม, ห้าเหลี่ยม, ? — รูปถัดไปคือ?", "figure_svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 320 80' width='320' height='80' role='img' aria-label='รูปสามเหลี่ยม สี่เหลี่ยม ห้าเหลี่ยม'><polygon points='30,65 50,15 70,65' fill='none' stroke='#1d4ed8' stroke-width='2.5'/><rect x='105' y='18' width='46' height='46' fill='none' stroke='#1d4ed8' stroke-width='2.5'/><polygon points='205,15 240,32 226,68 178,68 165,32' fill='none' stroke='#1d4ed8' stroke-width='2.5'/></svg>", "choices": ["หกเหลี่ยม", "สามเหลี่ยม", "วงกลม", "สี่เหลี่ยมขนมเปียกปูน"], "answer": 0, "explanation": "จำนวนด้านของรูปหลายเหลี่ยมเพิ่มทีละ 1: 3 ด้าน → 4 ด้าน → 5 ด้าน → ถัดไป 6 ด้าน คือหกเหลี่ยม", "shortcut": "นับด้านของรูปทรง — จำนวนด้านเพิ่มทีละ 1", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0019", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 3, "stem": "B, E, J, Q, ?", "figure_svg": null, "choices": ["X", "Y", "Z", "W"], "answer": 2, "explanation": "B=2, E=5, J=10, Q=17 → ผลต่าง +3, +5, +7 (เพิ่มทีละ 2) → ถัดไป +9 → 17+9 = 26 = Z", "shortcut": "ผลต่างเป็นจำนวนคี่ เพิ่มทีละ 2: 3,5,7,9", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0020", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 1, "stem": "J, H, F, D, ?", "figure_svg": null, "choices": ["A", "B", "C", "Z"], "answer": 1, "explanation": "ตำแหน่งลดลงทีละ 2: J=10, H=8, F=6, D=4 → ถัดไป 2 = B", "shortcut": "ลำดับถอย: ลบ 2 ทุกขั้น", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0021", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 1, "stem": "4 : 16 :: 6 : ?", "figure_svg": null, "choices": ["24", "30", "36", "42"], "answer": 2, "explanation": "4² = 16 → กำลังสอง ดังนั้น 6² = 36", "shortcut": "ตัวเลขคู่กำลัง: 4=2², 16=4² เห็นกำลังสองชัดเจน", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0022", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 1, "stem": "3 : 27 :: 4 : ?", "figure_svg": null, "choices": ["48", "54", "64", "81"], "answer": 2, "explanation": "3³ = 27 → กำลังสาม ดังนั้น 4³ = 64", "shortcut": "3³=27 คือเลขที่ออกสอบบ่อย — จำ", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0023", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 1, "stem": "5 : 30 :: 7 : ?", "figure_svg": null, "choices": ["35", "40", "42", "45"], "answer": 2, "explanation": "5 × 6 = 30 → คูณด้วย 6 ดังนั้น 7 × 6 = 42", "shortcut": "หาตัวคูณร่วม: 30÷5=6 ใช้ 6 กับทุกคู่", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0024", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 3, "stem": "7 : 11 :: 13 : ?", "figure_svg": null, "choices": ["15", "16", "17", "19"], "answer": 2, "explanation": "7 และ 11 เป็นจำนวนเฉพาะเรียงต่อกัน (จำนวนเฉพาะถัดไปหลัง 7 คือ 11) → 13 เป็นจำนวนเฉพาะ จำนวนเฉพาะถัดไปคือ 17", "shortcut": "ดูว่าเลขทั้งคู่อยู่ในกลุ่มเดียวกัน (จำนวนเฉพาะ/คู่/คี่) แล้วหาตัวถัดไปในกลุ่ม", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0025", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 2, "stem": "2 : 6 :: 4 : ?", "figure_svg": null, "choices": ["6", "8", "10", "12"], "answer": 1, "explanation": "2 + 4 = 6 (บวก 4) → 4 + 4 = 8", "shortcut": "ลองบวกก่อน: 6-2=4 ใช้ผลต่างเดียวกัน", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0026", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 2, "stem": "1 : 2 :: 4 : ?", "figure_svg": null, "choices": ["4", "6", "8", "16"], "answer": 2, "explanation": "อัตราส่วนคงที่ ×2 (2÷1=2) → 4×2 = 8", "shortcut": "ลองคูณ/หารก่อนถ้าตัวเลขโตขึ้นแบบเร็ว", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0027", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 2, "stem": "9 : 3 :: 16 : ?", "figure_svg": null, "choices": ["2", "4", "6", "8"], "answer": 1, "explanation": "√9 = 3 (ถอดราก) → √16 = 4", "shortcut": "ตัวเลขกำลังสองลงท้ายด้วย 9 และ 16 → ถอดราก", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0028", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 3, "stem": "27 : 3 :: 64 : ?", "figure_svg": null, "choices": ["2", "4", "6", "8"], "answer": 1, "explanation": "∛27 = 3 (ถอดรากที่สาม) → ∛64 = 4", "shortcut": "27 คือ 3³, 64 คือ 4³ → ถอดรากที่สาม", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0029", "subject": "analytical", "topic": "abstract", "subtopic": "figure_analogy", "difficulty": 2, "stem": "รูปสี่เหลี่ยมมีจุด 2 จุด → รูปสี่เหลี่ยมมีจุด 4 จุด :: รูปสามเหลี่ยมมีจุด 1 จุด → ?", "figure_svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 320 80' width='320' height='80' role='img' aria-label='สี่เหลี่ยมจุด 2 และ 4 จุด สามเหลี่ยมจุด 1 จุด'><rect x='10' y='12' width='50' height='50' fill='none' stroke='#333' stroke-width='2'/><circle cx='28' cy='30' r='3.5' fill='#1d4ed8'/><circle cx='42' cy='48' r='3.5' fill='#1d4ed8'/><rect x='90' y='12' width='50' height='50' fill='none' stroke='#333' stroke-width='2'/><circle cx='107' cy='27' r='3.5' fill='#1d4ed8'/><circle cx='125' cy='27' r='3.5' fill='#1d4ed8'/><circle cx='107' cy='48' r='3.5' fill='#1d4ed8'/><circle cx='125' cy='48' r='3.5' fill='#1d4ed8'/><polygon points='200,60 225,12 250,60' fill='none' stroke='#333' stroke-width='2'/><circle cx='225' cy='45' r='3.5' fill='#1d4ed8'/></svg>", "choices": ["รูปสามเหลี่ยมมีจุด 1 จุด", "รูปสามเหลี่ยมมีจุด 2 จุด", "รูปสามเหลี่ยมมีจุด 3 จุด", "รูปสี่เหลี่ยมมีจุด 3 จุด"], "answer": 2, "explanation": "การเปลี่ยนแปลงคือ เพิ่มจุดอีกเท่าตัว (2→4) ดังนั้นรูปสามเหลี่ยม 1 จุด ต้องเพิ่มเป็น 3 จุด — คงรูปสามเหลี่ยมไว้ ไม่เปลี่ยนเป็นสี่เหลี่ยม", "shortcut": "ระบุการกระทำ: 'เพิ่มจุดอีกเท่าตัว' แล้วทำกับรูปที่สอง", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0030", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 1, "stem": "4 : 8 :: 6 : ?", "figure_svg": null, "choices": ["8", "9", "10", "12"], "answer": 2, "explanation": "4 + 4 = 8 (บวก 4) → 6 + 4 = 10", "shortcut": "หาผลต่าง: 8-4=4 บวกผลต่างเดียวกัน", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0031", "subject": "analytical", "topic": "abstract", "subtopic": "syllogism", "difficulty": 1, "stem": "กำหนด: (1) เจ้าหน้าที่ทุกคนเป็นข้าราชการ (2) สมศรีเป็นเจ้าหน้าที่ — ข้อใดสรุปได้?", "figure_svg": null, "choices": ["สมศรีเป็นเจ้าหน้าที่", "สมศรีเป็นข้าราชการ", "สมศรีไม่เป็นข้าราชการ", "ไม่มีข้อสรุป"], "answer": 1, "explanation": "เจ้าหน้าที่ ⊂ ข้าราชการ และสมศรี ∈ เจ้าหน้าที่ ดังนั้นสมศรี ∈ ข้าราชการ — ก เป็นข้อมูลที่ให้มาไม่ใช่การสรุปใหม่ ค ขัดแย้งกับเงื่อนไข", "shortcut": "วง A อยู่ในวง B — ถ้าอยู่ใน A ต้องอยู่ใน B", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0032", "subject": "analytical", "topic": "abstract", "subtopic": "syllogism", "difficulty": 2, "stem": "กำหนด: (1) วิศวกรทุกคนจบการศึกษาปริญญาตรี (2) ต่ายเป็นผู้จบปริญญาตรี — ข้อใดสรุปได้?", "figure_svg": null, "choices": ["ต่ายเป็นวิศวกร", "ต่ายไม่เป็นวิศวกร", "ต่ายอาจเป็นวิศวกรหรือไม่ก็ได้", "ข้อมูลไม่เพียงพอสรุปไม่ได้"], "answer": 2, "explanation": "วิศวกร → ปริญญาตรี ไม่ได้กลับกัน (คนจบปริญญาตรีไม่จำเป็นเป็นวิศวกร) ดังนั้นต่ายอาจเป็นวิศวกรหรือไม่ก็ได้ — ก คือ Q→P เกินขอบเขต ข ฟันธงเกินไป", "shortcut": "'ทุก A เป็น B' กลับไม่ได้ — คนที่เป็น B อาจเป็นหรือไม่เป็น A", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0033", "subject": "analytical", "topic": "abstract", "subtopic": "venn", "difficulty": 2, "stem": "นักเรียน 40 คน เรียนว่ายน้ำ 22 คน เรียนดำน้ำ 18 คน เรียนทั้งสอง 10 คน — เรียนอย่างน้อยหนึ่งกีฬาเท่าไร?", "figure_svg": null, "choices": ["30 คน", "28 คน", "32 คน", "40 คน"], "answer": 0, "explanation": "สูตรเวนน์: รวม = ว่ายน้ำ + ดำน้ำ − ทั้งสอง = 22 + 18 − 10 = 30 คน", "shortcut": "A ∪ B = A + B − (A ∩ B)", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0034", "subject": "analytical", "topic": "abstract", "subtopic": "venn", "difficulty": 3, "stem": "พนักงาน 50 คน ดื่มชา 25 คน ดื่มกาแฟ 30 คน ไม่ดื่มอะไรเลย 5 คน — ดื่มทั้งชาและกาแฟเท่าไร?", "figure_svg": null, "choices": ["5 คน", "8 คน", "10 คน", "15 คน"], "answer": 2, "explanation": "คนที่ดื่มอย่างน้อยหนึ่ง = 50 − 5 = 45 คน สูตร: 45 = 25 + 30 − ทั้งสอง → ทั้งสอง = 55 − 45 = 10 คน", "shortcut": "หา 'อย่างน้อยหนึ่ง' จากทั้งหมดก่อน แล้วแทนในสูตรเวนน์", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0035", "subject": "analytical", "topic": "abstract", "subtopic": "ordering", "difficulty": 2, "stem": "เงื่อนไข: เอ็มสูงกว่าบี · บีสูงกว่าซี · ดีสูงกว่าซีแต่เตี้ยกว่าบี — เรียงจากสูงไปต่ำ?", "figure_svg": null, "choices": ["เอ็ม บี ดี ซี", "เอ็ม ดี บี ซี", "บี เอ็ม ดี ซี", "เอ็ม บี ซี ดี"], "answer": 0, "explanation": "เอ็ม > บี > ซี และ บี > ดี > ซี → ลำดับ: เอ็ม > บี > ดี > ซี", "shortcut": "เขียนเส้นลงเรื่อย ๆ: เอ็ม _ บี _ ซี แล้วแทรกดีระหว่าง บี และ ซี", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0036", "subject": "analytical", "topic": "abstract", "subtopic": "syllogism", "difficulty": 3, "stem": "กำหนด: (1) นักกีฬาทุกคนสูง (2) ไม่มีคนสูงเป็นคนขี้อาย (3) แก้วเป็นนักกีฬา — สรุปได้ว่า?", "figure_svg": null, "choices": ["แก้วเป็นคนขี้อาย", "แก้วไม่เป็นคนขี้อาย", "แก้วอาจเป็นคนขี้อาย", "ไม่มีข้อสรุป"], "answer": 1, "explanation": "(1) นักกีฬา ⊂ คนสูง (2) คนสูง และ คนขี้อาย แยกกัน (no intersection) (3) แก้ว ∈ นักกีฬา → แก้ว ∈ คนสูง → แก้ว ∉ คนขี้อาย — ข้อ (2) คือ 'ไม่มีคนสูงเป็นคนขี้อาย' = ถ้าสูงแล้วไม่ขี้อาย", "shortcut": "ห่วงโซ่: A⊂B, B และ C แยกกัน, A∈ตัว → ∉C", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0037", "subject": "analytical", "topic": "abstract", "subtopic": "ordering", "difficulty": 1, "stem": "เรียงลำดับเหตุการณ์: (ก) ตั้งเครื่อง (ข) ตวงกาแฟ (ค) ต้มน้ำ (ง) ดื่ม — ลำดับที่ถูกต้อง?", "figure_svg": null, "choices": ["ค-ข-ก-ง", "ก-ข-ค-ง", "ค-ก-ข-ง", "ก-ค-ข-ง"], "answer": 0, "explanation": "ต้มน้ำก่อน → ตวงกาแฟ → ตั้งเครื่อง (ชง) → ดื่ม: ค-ข-ก-ง — ต้องต้มน้ำก่อนชงเสมอ", "shortcut": "จัดลำดับจากขั้นตอนที่เป็นไปไม่ได้ถ้าทำก่อน — ตัดตัวเลือกที่เริ่มด้วย 'ดื่ม' ออก", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0038", "subject": "analytical", "topic": "abstract", "subtopic": "syllogism", "difficulty": 2, "stem": "กำหนด: 'ไม่มีเสือในป่าแห่งนี้เป็นสัตว์เลี้ยง' — ข้อใดถูกต้อง?", "figure_svg": null, "choices": ["เสือทุกตัวในป่านี้เป็นสัตว์เลี้ยง", "เสือบางตัวในป่านี้เป็นสัตว์เลี้ยง", "เสือในป่านี้ทุกตัวไม่เป็นสัตว์เลี้ยง", "ไม่มีเสือในป่านี้เลย"], "answer": 2, "explanation": "'ไม่มี A เป็น B' หมายถึง A ทุกตัวไม่ใช่ B ดังนั้นเสือในป่านี้ทุกตัวไม่เป็นสัตว์เลี้ยง — ก และ ข ขัดแย้งตรงข้าม ง ไม่ได้กล่าว", "shortcut": "'ไม่มี A เป็น B' = 'A ทุกตัวไม่ใช่ B'", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0039", "subject": "analytical", "topic": "abstract", "subtopic": "ordering", "difficulty": 3, "stem": "ผู้เข้าเส้นชัย 5 คน: ก เข้าก่อน ข · ค เข้าก่อน ก แต่หลัง ง · ข เข้าก่อน จ — ใครเข้าเส้นชัยคนแรก?", "figure_svg": null, "choices": ["ก", "ค", "ง", "จ"], "answer": 2, "explanation": "เงื่อนไข: ก ก่อน ข · ค หลัง ง และก่อน ก (ง < ค < ก) · ข ก่อน จ — รวม: ง < ค < ก < ข < จ ดังนั้นคนแรกคือ ง", "shortcut": "แปลงเป็นสัญลักษณ์: ง<ค<ก<ข<จ แล้วตอบ", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0040", "subject": "analytical", "topic": "abstract", "subtopic": "venn", "difficulty": 1, "stem": "นักศึกษา 60 คน ชอบฟุตบอล 35 คน ชอบบาสเกตบอล 25 คน ชอบทั้งสอง 10 คน — ไม่ชอบกีฬาทั้งสองเท่าไร?", "figure_svg": null, "choices": ["20 คน", "10 คน", "8 คน", "0 คน"], "answer": 1, "explanation": "ชอบอย่างน้อยหนึ่ง = 35 + 25 − 10 = 50 คน → ไม่ชอบเลย = 60 − 50 = 10 คน", "shortcut": "ทั้งหมด − (A ∪ B) = ไม่ชอบทั้งสอง", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0041", "subject": "analytical", "topic": "abstract", "subtopic": "operation", "difficulty": 1, "stem": "นิยาม a ⊕ b = a + b ถ้า a เป็นคู่ และ a ⊕ b = a − b ถ้า a เป็นคี่ — ค่าของ 8 ⊕ 3 เท่ากับข้อใด?", "figure_svg": null, "choices": ["5", "11", "24", "13"], "answer": 1, "explanation": "a = 8 เป็นคู่ → ใช้กฎ a + b = 8 + 3 = 11 — ข้ออื่นใช้กฎผิดเงื่อนไข", "shortcut": "ตรวจเงื่อนไขของกฎก่อนคำนวณทุกครั้ง", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0042", "subject": "analytical", "topic": "abstract", "subtopic": "operation", "difficulty": 1, "stem": "นิยาม a ⊕ b = a + b ถ้า a เป็นคู่ และ a ⊕ b = a − b ถ้า a เป็นคี่ — ค่าของ 7 ⊕ 4 เท่ากับข้อใด?", "figure_svg": null, "choices": ["11", "3", "28", "1"], "answer": 1, "explanation": "a = 7 เป็นคี่ → ใช้กฎ a − b = 7 − 4 = 3", "shortcut": "7 คี่ → ลบ", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0043", "subject": "analytical", "topic": "abstract", "subtopic": "operation", "difficulty": 2, "stem": "นิยาม a * b = a × b ถ้า b เป็นคู่ และ a * b = a + b ถ้า b เป็นคี่ — ค่าของ 5 * 2 เท่ากับข้อใด?", "figure_svg": null, "choices": ["7", "10", "25", "12"], "answer": 1, "explanation": "b = 2 เป็นคู่ → a × b = 5 × 2 = 10", "shortcut": "มองที่ b ไม่ใช่ a — เงื่อนไขผูกกับ b", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0044", "subject": "analytical", "topic": "abstract", "subtopic": "symbol_cycle", "difficulty": 2, "stem": "ลำดับสัญลักษณ์ ★ ● ▲ ★ ● ▲ … สัญลักษณ์ตัวที่ 14 คือข้อใด?", "figure_svg": null, "choices": ["★", "●", "▲", "ไม่สามารถระบุได้"], "answer": 1, "explanation": "ความยาวรอบคือ 3 — 14 mod 3 = 2 (หาร 14÷3 ได้ 4 เศษ 2) → ตัวที่ 2 ของรอบ คือ ●", "shortcut": "ตำแหน่ง mod 3 · เศษ 0 = ตัวสุดท้ายของรอบ", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0045", "subject": "analytical", "topic": "abstract", "subtopic": "operation", "difficulty": 2, "stem": "นิยาม a # b = ผลต่างของ a กับ b (ค่ามากลบค่าน้อย) — ค่าของ 4 # 9 เท่ากับข้อใด?", "figure_svg": null, "choices": ["−5", "5", "13", "36"], "answer": 1, "explanation": "9 − 4 = 5 (ค่ามากลบค่าน้อยเสมอ) — ติดลบไม่ได้ตามนิยามนี้", "shortcut": "ผลต่างสัมบูรณ์: |a − b|", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0046", "subject": "analytical", "topic": "abstract", "subtopic": "operation_nested", "difficulty": 3, "stem": "นิยาม a ⊕ b = 2a + b — ค่าของ (3 ⊕ 2) ⊕ 1 เท่ากับข้อใด?", "figure_svg": null, "choices": ["9", "12", "17", "15"], "answer": 2, "explanation": "วงเล็บในก่อน: 3 ⊕ 2 = 2×3 + 2 = 8 จากนั้น 8 ⊕ 1 = 2×8 + 1 = 17", "shortcut": "วงเล็บในสุดก่อน ทีละชั้น อย่าข้ามขั้น", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0047", "subject": "analytical", "topic": "abstract", "subtopic": "symbol_cycle", "difficulty": 3, "stem": "ลำดับตัวอักษร A B C A B C A B C … ตัวที่ 25 คือข้อใด?", "figure_svg": null, "choices": ["A", "B", "C", "ไม่มีที่สิ้นสุด"], "answer": 0, "explanation": "ความยาวรอบคือ 3 — 25 mod 3 = 1 (24÷3 ลงตัว เหลือ 1) → ตัวที่ 1 ของรอบ คือ A", "shortcut": "หาร 25÷3 ได้ 8 เศษ 1 → ตัวแรกของรอบ", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0048", "subject": "analytical", "topic": "abstract", "subtopic": "operation_nested", "difficulty": 3, "stem": "นิยาม a ◇ b = a² − b — ค่าของ (3 ◇ 2) ◇ 1 เท่ากับข้อใด?", "figure_svg": null, "choices": ["48", "46", "47", "49"], "answer": 0, "explanation": "3 ◇ 2 = 3² − 2 = 9 − 2 = 7 จากนั้น 7 ◇ 1 = 7² − 1 = 49 − 1 = 48", "shortcut": "วงเล็บใน → ได้ 7 → 7² = 49 → −1 = 48", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0049", "subject": "analytical", "topic": "abstract", "subtopic": "symbol_cycle", "difficulty": 1, "stem": "ลำดับ X Y Z X Y Z … ตัวที่ 11 คือข้อใด?", "figure_svg": null, "choices": ["X", "Y", "Z", "W"], "answer": 1, "explanation": "ความยาวรอบคือ 3 — 11 mod 3 = 2 → ตัวที่ 2 ของรอบ คือ Y", "shortcut": "11 ÷ 3 เศษ 2 → Y", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-ABST-0050", "subject": "analytical", "topic": "abstract", "subtopic": "operation", "difficulty": 2, "stem": "นิยาม a $ b = (a + b) × 2 ถ้า a > b และ a $ b = a × b ถ้า a ≤ b — ค่าของ 5 $ 3 เท่ากับข้อใด?", "figure_svg": null, "choices": ["8", "15", "16", "30"], "answer": 2, "explanation": "a = 5 > b = 3 → ใช้กฎ (a + b) × 2 = (5 + 3) × 2 = 16 — 15 คือ a×b ซึ่งใช้เมื่อ a ≤ b เท่านั้น", "shortcut": "ตรวจเงื่อนไข a > b ก่อนเสมอ", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S3-ADMIN-0001", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "three_levels", "difficulty": 1, "stem": "การบริหารราชการแผ่นดินของไทยแบ่งออกเป็นกี่ระดับ (ตาม พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534)?", "figure_svg": null, "choices": ["2 ระดับ คือ ส่วนกลางและส่วนภูมิภาค", "3 ระดับ คือ ส่วนกลาง ส่วนภูมิภาค ส่วนท้องถิ่น", "4 ระดับ คือ ชาติ ภูมิภาค จังหวัด อำเภอ", "5 ระดับ คือ กระทรวง ทบวง กรม จังหวัด อำเภอ"], "answer": 1, "explanation": "โครงสร้างมาตรฐานของการบริหารราชการแผ่นดินของไทยแบ่งเป็น 3 ระดับ ได้แก่ ส่วนกลาง (กระทรวง ทบวง กรม) ส่วนภูมิภาค (จังหวัด อำเภอ ตำบล หมู่บ้าน) และส่วนท้องถิ่น (เทศบาล อบต. อบจ. กทม. เมืองพัทยา) ตาม พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534 (รอตรวจสอบมาตรา) ตัวเลือกอื่นแบ่งระดับผิด", "shortcut": "กลาง–ภูมิภาค–ท้องถิ่น (3 ระดับ)", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0002", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "local_government", "difficulty": 1, "stem": "ข้อใดเป็นราชการส่วนท้องถิ่นทั้งหมด?", "figure_svg": null, "choices": ["เทศบาล องค์การบริหารส่วนตำบล กรุงเทพมหานคร", "กระทรวง กรม อำเภอ", "ผู้ว่าราชการจังหวัด นายอำเภอ กำนัน", "สำนักงบประมาณ สำนักงาน ก.พ. สำนักงานคณะกรรมการกฤษฎีกา"], "answer": 0, "explanation": "เทศบาล อบต. อบจ. กทม. เมืองพัทยา เป็นราชการส่วนท้องถิ่นที่ประชาชนเลือกตั้ง (ก) (ข) ส่วนกลางและส่วนภูมิภาค (ค) ส่วนภูมิภาค (ง) เป็นหน่วยงานราชการส่วนกลาง", "shortcut": "เลือกตั้ง = ท้องถิ่น · แต่งตั้ง = ส่วนกลาง/ภูมิภาค", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0003", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "provincial_admin", "difficulty": 2, "stem": "ผู้ว่าราชการจังหวัดมาจากที่ใด?", "figure_svg": null, "choices": ["การเลือกตั้งของประชาชนในจังหวัด", "การแต่งตั้งโดยส่วนราชการส่วนกลาง", "การเลือกตั้งโดยกำนันผู้ใหญ่บ้าน", "การแต่งตั้งโดยสภาเทศบาล"], "answer": 1, "explanation": "ผู้ว่าราชการจังหวัดเป็นข้าราชการที่ได้รับการแต่งตั้งจากส่วนกลาง (ผ่านปลัดกระทรวงมหาดไทย/รัฐบาล) เป็นตัวแทนส่วนกลางในพื้นที่ ไม่ใช่การเลือกตั้งโดยตรงของประชาชน (ข) (ก)(ค) ไม่ใช่กลไกการได้มาซึ่งผู้ว่าฯ (ง) สภาเทศบาลไม่มีอำนาจแต่งตั้งผู้ว่าฯ", "shortcut": "ผู้ว่าฯ แต่งตั้ง — นายกเทศมนตรี นายก อบต. ผู้ว่าฯ กทม. เลือกตั้ง", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0004", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "central_admin", "difficulty": 2, "stem": "หน่วยงานใดอยู่ในราชการส่วนกลาง?", "figure_svg": null, "choices": ["องค์การบริหารส่วนจังหวัด", "สำนักงานคณะกรรมการกฤษฎีกา", "เทศบาลเมือง", "สำนักงานเขตกรุงเทพมหานคร"], "answer": 1, "explanation": "สำนักงานคณะกรรมการกฤษฎีกาเป็นหน่วยงานราชการส่วนกลาง (ทำหน้าที่กลั่นกรองกฎหมาย) (ข) (ก) อบจ. = ส่วนท้องถิ่น (ค) เทศบาล = ส่วนท้องถิ่น (ง) สำนักงานเขต = ส่วนท้องถิ่น (สังกัด กทม.)", "shortcut": "สำนักงานกลางระดับชาติ (ก.พ. กฤษฎีกา งบประมาณ เลขานายกฯ) = ส่วนกลาง", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0005", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "ministerial_structure", "difficulty": 2, "stem": "ลำดับชั้นของราชการส่วนกลางจากใหญ่ไปเล็กที่ถูกต้องคือข้อใด?", "figure_svg": null, "choices": ["กรม → ทบวง → กระทรวง", "กระทรวง → กรม → ทบวง", "กระทรวง → ทบวง → กรม", "ทบวง → กระทรวง → กรม"], "answer": 2, "explanation": "ลำดับชั้นราชการส่วนกลาง: กระทรวง (ใหญ่สุด มีรัฐมนตรีว่าการ) → ทบวง → กรม (เล็กสุด มีอธิบดี) (ค) ตัวเลือกอื่นเรียงลำดับผิด", "shortcut": "กระทรวง > ทบวง > กรม — รัฐมนตรี > อธิบดี", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0006", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "local_elected", "difficulty": 2, "stem": "ข้อใดเป็นหัวหน้าองค์กรปกครองส่วนท้องถิ่นที่มาจากการเลือกตั้ง?", "figure_svg": null, "choices": ["นายอำเภอ", "ปลัดกระทรวง", "นายกเทศมนตรี", "ผู้อำนวยการสำนักงบประมาณ"], "answer": 2, "explanation": "นายกเทศมนตรีมาจากการเลือกตั้งของประชาชนในเขตเทศบาล (ค) (ก) นายอำเภอ = ข้าราชการแต่งตั้ง (ส่วนภูมิภาค) (ข) ปลัดกระทรวง = ข้าราชการแต่งตั้ง (ส่วนกลาง) (ง) ผู้อำนวยการสำนักงบประมาณ = แต่งตั้ง (ส่วนกลาง)", "shortcut": "นายกฯ ท้องถิ่นเลือกตั้ง: นายกเทศมนตรี นายก อบต. นายก อบจ. ผู้ว่าฯ กทม. นายกเมืองพัทยา", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0007", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "regional_vs_local", "difficulty": 3, "stem": "ข้อใดแยกความแตกต่างระหว่างราชการส่วนภูมิภาคกับราชการส่วนท้องถิ่นได้ถูกต้องที่สุด?", "figure_svg": null, "choices": ["ส่วนภูมิภาคได้งบประมาณจากประชาชนในพื้นที่", "ส่วนท้องถิ่นเป็นตัวแทนส่วนกลาง ส่วนภูมิภาคเป็นการเลือกตั้ง", "ส่วนภูมิภาคเป็นตัวแทนส่วนกลางในพื้นที่ ส่วนท้องถิ่นเป็นองค์กรที่ประชาชนเลือกตั้ง", "ทั้งสองส่วนเหมือนกันทุกประการ"], "answer": 2, "explanation": "ส่วนภูมิภาค (จังหวัด อำเภอ ตำบล หมู่บ้าน) คือตัวแทนส่วนกลางในพื้นที่ ผู้นำแต่งตั้ง ส่วนท้องถิ่น (เทศบาล อบต. อบจ. กทม.) เป็นองค์กรปกครองตนเอง ผู้นำมาจากการเลือกตั้ง (ค) (ก) งบส่วนภูมิภาคมาจากส่วนกลาง (ข) กลับกัน (ง) ผิด", "shortcut": "ภูมิภาค = แต่งตั้ง ตัวแทนกลาง · ท้องถิ่น = เลือกตั้ง ปกครองตนเอง", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0008", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "tambon_structure", "difficulty": 2, "stem": "กำนันเป็นหัวหน้าส่วนราชการในระดับใด?", "figure_svg": null, "choices": ["หมู่บ้าน", "ตำบล", "อำเภอ", "จังหวัด"], "answer": 1, "explanation": "กำนันเป็นหัวหน้าส่วนราชการในระดับตำบล (มาจากการเลือกตั้งโดยผู้ใหญ่บ้าน) (ข) (ก) หมู่บ้านมีผู้ใหญ่บ้านเป็นหัวหน้า (ค) อำเภอมีนายอำเภอ (ง) จังหวัดมีผู้ว่าราชการจังหวัด", "shortcut": "ผู้ใหญ่บ้าน = หมู่บ้าน · กำนัน = ตำบล · นายอำเภอ = อำเภอ · ผู้ว่าฯ = จังหวัด", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0009", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "bangkok_special", "difficulty": 3, "stem": "กรุงเทพมหานครอยู่ในราชการส่วนใด?", "figure_svg": null, "choices": ["ส่วนกลาง เพราะเป็นเมืองหลวง", "ส่วนภูมิภาค เพราะอยู่ในเขตจังหวัด", "ส่วนท้องถิ่น ในรูปแบบพิเศษ", "ไม่ได้อยู่ในระบบราชการไทย"], "answer": 2, "explanation": "กรุงเทพมหานครเป็นราชการส่วนท้องถิ่นในรูปแบบพิเศษ (เช่นเดียวกับเมืองพัทยา) มีผู้ว่าราชการกรุงเทพมหานครมาจากการเลือกตั้ง (ค) (ก)(ข) ไม่ใช่ (ง) ไม่ใช่", "shortcut": "กทม. และพัทยา = ส่วนท้องถิ่นรูปแบบพิเศษ", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-ADMIN-0010", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "practical_apply", "difficulty": 3, "stem": "นายสมชายอาศัยอยู่ในจังหวัดเชียงใหม่ ต้องการทำบัตรประชาชนใหม่ ควรติดต่อหน่วยงานใด?", "figure_svg": null, "choices": ["เทศบาลนคร", "ที่ว่าการอำเภอ (สำนักงานทะเบียนราษฎร)", "สำนักงานเขตกรุงเทพมหานครเพียงอย่างเดียว", "กรมการปกครองที่กรุงเทพฯ"], "answer": 1, "explanation": "งานทะเบียนราษฎร (บัตรประชาชน) เป็นหน้าที่ของอำเภอ (ส่วนภูมิภาค) หน่วยงานให้บริการคือ สำนักงานทะเบียน ณ ที่ว่าการอำเภอ (ข) (ก) เทศบาลไม่ใช่ผู้รับผิดชอบงานทะเบียนราษฎร (ค) สำนักงานเขตเฉพาะใน กทม. เท่านั้น ไม่ใช่เชียงใหม่ (ง) กรมการปกครองเป็นหน่วยงานระดับส่วนกลาง ไม่ใช่หน่วยบริการโดยตรง", "shortcut": "บัตรประชาชน = งานทะเบียนราษฎร = อำเภอ", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0001", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "purpose", "difficulty": 1, "stem": "พระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 มีเจตนารมณ์หลักคืออะไร?", "figure_svg": null, "choices": ["เพิ่มจำนวนส่วนราชการในแต่ละกระทรวง", "ให้การบริหารราชการเพื่อประโยชน์สุขของประชาชนเป็นสำคัญ", "ยกเลิกการประเมินผลการปฏิบัติราชการ", "รวมกระทรวงต่าง ๆ เข้าด้วยกัน"], "answer": 1, "explanation": "พระราชกฤษฎีกาฉบับนี้ (2546) วางกรอบให้ส่วนราชการบริหารเพื่อประชาชน ตอบสนองความต้องการ มีผลสัมฤทธิ์และคุ้มค่า (ข) (ก)(ค)(ง) ไม่ใช่เจตนารมณ์ของกฎหมายฉบับนี้", "shortcut": "บริหารเพื่อประชาชน — จุดเริ่มของ good governance ในไทย", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0002", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "participation", "difficulty": 1, "stem": "ส่วนราชการเปิดให้ประชาชนแสดงความเห็นผ่านเว็บไซต์ก่อนออกกฎเกณฑ์ใหม่ สอดคล้องกับหลักใดของการบริหารกิจการบ้านเมืองที่ดี?", "figure_svg": null, "choices": ["หลักความคุ้มค่า", "หลักการมีส่วนร่วม", "หลักการลดขั้นตอน", "หลักการควบคุม"], "answer": 1, "explanation": "เปิดโอกาสให้ประชาชนร่วมแสดงความเห็นก่อนตัดสินใจ = หลักการมีส่วนร่วม (participation) (ข) (ก) ความคุ้มค่า = ใช้ทรัพยากรคุ้มค่า (ค) ลดขั้นตอน = ตัดขั้นตอนเกินจำเป็น (ง) ควบคุม ไม่ใช่หลักหลักในกรอบนี้", "shortcut": "มีส่วนร่วม = ให้ประชาชนมีส่วนในการตัดสินใจก่อนเกิดกฎ/โครงการ", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0003", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "results_based", "difficulty": 2, "stem": "หน่วยงานวัดผลการปฏิบัติงานด้วย KPI และรายงานต่อผู้บังคับบัญชาทุกไตรมาส สอดคล้องหลักใดมากที่สุด?", "figure_svg": null, "choices": ["หลักความโปร่งใส", "หลักผลสัมฤทธิ์ต่อภารกิจของรัฐ", "หลักการมีส่วนร่วม", "หลักความเสมอภาค"], "answer": 1, "explanation": "การวัดผลและติดตามตามแผนปฏิบัติราชการ = การบริหารเชิงผลลัพธ์ สอดคล้อง 'ผลสัมฤทธิ์ต่อภารกิจของรัฐ' (ข) (ก) โปร่งใส = เปิดเผยข้อมูล (ค) มีส่วนร่วม = การรับฟังความเห็นประชาชน (ง) เสมอภาค = ปฏิบัติต่อทุกคนเท่าเทียม", "shortcut": "KPI และการติดตาม = ผลสัมฤทธิ์ (results-based management)", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0004", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "reduce_bureaucracy", "difficulty": 2, "stem": "ส่วนราชการหนึ่งปรับขั้นตอนขออนุญาตจาก 14 วันเหลือ 3 วัน พร้อมยื่นออนไลน์ได้ การดำเนินการนี้ตอบสนองหลักใดมากที่สุด?", "figure_svg": null, "choices": ["หลักอำนวยความสะดวกและลดขั้นตอนเกินจำเป็น", "หลักผลสัมฤทธิ์", "หลักการตรวจสอบได้", "หลักความคุ้มค่า"], "answer": 0, "explanation": "การลดขั้นตอน ตัดเวลา และให้ยื่นออนไลน์ = อำนวยความสะดวกประชาชน + ไม่มีขั้นตอนเกินความจำเป็น (ก) (ข) ผลสัมฤทธิ์เน้นผลงาน (ค) ตรวจสอบได้เน้นความโปร่งใส (ง) คุ้มค่าเน้นทรัพยากร", "shortcut": "ลดขั้นตอน–ลดเวลา–ออนไลน์ = อำนวยความสะดวกประชาชน", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0005", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "transparency", "difficulty": 2, "stem": "หน่วยงานเผยแพร่งบประมาณและสัญญาจัดซื้อจัดจ้างบนเว็บไซต์ให้ประชาชนตรวจสอบได้ สอดคล้องหลักใดมากที่สุด?", "figure_svg": null, "choices": ["หลักความรับผิดชอบ", "หลักความโปร่งใสและหลักการตรวจสอบได้", "หลักความคุ้มค่า", "หลักผลสัมฤทธิ์"], "answer": 1, "explanation": "การเปิดเผยข้อมูลงบประมาณ/สัญญาให้สาธารณชนตรวจสอบได้ = โปร่งใส + ตรวจสอบได้ (ข) (ก) รับผิดชอบ = ยอมรับผลของการกระทำของตน (ค) คุ้มค่า = ประสิทธิภาพการใช้ทรัพยากร (ง) ผลสัมฤทธิ์ = ผลลัพธ์ตามเป้าหมาย", "shortcut": "เปิดเผย = โปร่งใส + ตรวจสอบได้", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0006", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "value_for_money", "difficulty": 2, "stem": "ส่วนราชการเลือกวิธีจัดซื้อที่ประหยัดและมีคุณภาพเหมาะสมที่สุด ภายในงบประมาณที่มี ถือว่าสอดคล้องหลักใดมากที่สุด?", "figure_svg": null, "choices": ["หลักความคุ้มค่า", "หลักการมีส่วนร่วม", "หลักความเสมอภาค", "หลักนิติธรรม"], "answer": 0, "explanation": "การใช้ทรัพยากร (งบ/คน/เวลา) อย่างคุ้มค่าที่สุด = หลักความคุ้มค่า (value for money) (ก) (ข) มีส่วนร่วม = ฟังความเห็นประชาชน (ค) เสมอภาค = ปราศจากการเลือกปฏิบัติ (ง) นิติธรรม = ทุกคนอยู่ภายใต้กฎหมาย", "shortcut": "คุ้มค่า = คุณภาพดี + ต้นทุนเหมาะสม", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0007", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "one_stop", "difficulty": 3, "stem": "แนวคิด 'One Stop Service' ของส่วนราชการสะท้อนหลักการใดของการบริหารกิจการบ้านเมืองที่ดีมากที่สุด?", "figure_svg": null, "choices": ["หลักการมีส่วนร่วม", "หลักอำนวยความสะดวกและตอบสนองความต้องการของประชาชน", "หลักผลสัมฤทธิ์", "หลักประสิทธิผล"], "answer": 1, "explanation": "One Stop Service = ประชาชนติดต่อครั้งเดียวได้ครบ ≈ อำนวยความสะดวก + ตอบสนองความต้องการ (ข) (ก) มีส่วนร่วมเน้นการมีส่วนร่วมในการตัดสินใจ (ค) ผลสัมฤทธิ์เน้นผลลัพธ์ (ง) ประสิทธิผล = ทำได้ตามเป้า แต่จุดเด่นของบริการจุดเดียวคือความสะดวกของประชาชน", "shortcut": "One Stop Service = สะดวก ครบ จบในที่เดียว", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0008", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "accountability", "difficulty": 2, "stem": "หัวหน้าส่วนราชการรับผิดชอบต่อผลการปฏิบัติงานของหน่วยงาน และชี้แจงต่อสาธารณะได้ ถือว่าหลักการใดเด่นชัดที่สุด?", "figure_svg": null, "choices": ["หลักความรับผิดชอบ (accountability)", "หลักความคุ้มค่า", "หลักผลสัมฤทธิ์", "หลักความโปร่งใส"], "answer": 0, "explanation": "การยอมรับในผลการกระทำและพร้อมชี้แจง = ความรับผิดชอบ (accountability) (ก) (ข) คุ้มค่า = ประหยัดทรัพยากร (ค) ผลสัมฤทธิ์ = บรรลุเป้าหมาย (ง) โปร่งใส = เปิดเผยข้อมูล (ใกล้เคียง แต่ accountability เน้น 'ความรับผิดชอบต่อผล')", "shortcut": "accountability = ยอมรับผล + ชี้แจงได้", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0009", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "action_plan", "difficulty": 3, "stem": "ส่วนราชการต้องจัดทำแผนปฏิบัติราชการประจำปี และติดตามประเมินผลอย่างสม่ำเสมอ จุดประสงค์หลักคืออะไร?", "figure_svg": null, "choices": ["เพื่อขอเพิ่มงบประมาณ", "เพื่อให้การบริหารเน้นผลสัมฤทธิ์และตรวจสอบผลงานที่วัดได้", "เพื่อลดจำนวนข้าราชการ", "เพื่อปฏิบัติตามพิธีการเท่านั้น"], "answer": 1, "explanation": "แผนปฏิบัติราชการ + การติดตามประเมินผล = เครื่องมือบริหารเชิงผลลัพธ์ วัดงานเป็นเชิงประจักษ์ (ข) (ก)(ค)(ง) ไม่ใช่เจตนารมณ์ของการทำแผน", "shortcut": "แผน + ประเมิน = วัดผลงานได้ = ผลสัมฤทธิ์", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-GOV-0010", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "citizen_focus", "difficulty": 3, "stem": "ข้อใดสะท้อน 'การบริหารกิจการบ้านเมืองที่ดี' ได้ครบถ้วนที่สุด?", "figure_svg": null, "choices": ["หน่วยงานทำงานเร็ว แต่ไม่เปิดเผยข้อมูล", "หน่วยงานบริหารเพื่อประชาชน โปร่งใส ลดขั้นตอน และวัดผลได้", "หน่วยงานเน้นเอกสารครบถ้วนตามระเบียบอย่างเดียว", "หน่วยงานทำตามคำสั่งผู้บังคับบัญชาทุกกรณี"], "answer": 1, "explanation": "การบริหารที่ดี = เพื่อประชาชน + โปร่งใส + อำนวยความสะดวก/ลดขั้นตอน + ผลสัมฤทธิ์ ครบทั้งมิติ (ข) (ก) ขาดความโปร่งใส (ค) เน้นพิธีการ ขัดกับการลดขั้นตอน (ง) เป็น vertical control ไม่ใช่ good governance", "shortcut": "เลือกคำตอบที่ครบมิติ: ประชาชน–โปร่งใส–สะดวก–ผลงาน", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0001", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "definition", "difficulty": 1, "stem": "'คำสั่งทางปกครอง' คืออะไร?", "figure_svg": null, "choices": ["หนังสือเชิญประชุมของหน่วยงาน", "การใช้อำนาจตามกฎหมายของเจ้าหน้าที่ ซึ่งส่งผลกระทบต่อสิทธิของบุคคล", "บันทึกข้อความภายใน", "คำแถลงข่าวต่อสาธารณะ"], "answer": 1, "explanation": "คำสั่งทางปกครอง = การใช้อำนาจตามกฎหมายของเจ้าหน้าที่รัฐ ที่มีผลกระทบต่อสิทธิของบุคคลโดยตรง เช่น อนุญาต/ไม่อนุญาต/เพิกถอน (ข) (ก)(ค) เป็นเอกสารภายใน ไม่มีผลกระทบสิทธิบุคคลโดยตรง (ง) แถลงข่าวไม่ใช่คำสั่ง", "shortcut": "คำสั่งทางปกครอง = ใช้อำนาจตามกฎหมาย + กระทบสิทธิบุคคล + เป็นลายลักษณ์อักษร", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0002", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "right_to_be_heard", "difficulty": 2, "stem": "เจ้าหน้าที่จะเพิกถอนใบอนุญาตประกอบกิจการของผู้ประกอบการ ขั้นตอนแรกที่ควรทำคืออะไร?", "figure_svg": null, "choices": ["ออกคำสั่งเพิกถอนทันทีเพื่อความรวดเร็ว", "แจ้งให้ผู้ประกอบการทราบ และเปิดโอกาสให้ชี้แจง/แสดงหลักฐานก่อน", "ส่งสำเนาคำสั่งให้หลังเพิกถอนเสร็จแล้ว", "รอให้ผู้ประกอบการร้องเรียนก่อน"], "answer": 1, "explanation": "ก่อนออกคำสั่งทางปกครองที่กระทบสิทธิ ต้องแจ้งผู้เกี่ยวข้องและรับฟังคำชี้แจงก่อน (right to be heard) ยกเว้นแต่กฎหมายยกเว้น (ข) (ก)(ค) ข้ามขั้นตอนสำคัญ คำสั่งอาจไม่ชอบด้วยกฎหมาย (ง) ไม่ใช่หน้าที่ของเจ้าหน้าที่", "shortcut": "แจ้ง → รับฟัง → ออกคำสั่งพร้อมเหตุผล", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0003", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "duty_to_give_reasons", "difficulty": 2, "stem": "คำสั่งทางปกครองฉบับหนึ่งไม่ได้ระบุเหตุผลเลย ผลตามกฎหมายคืออะไร?", "figure_svg": null, "choices": ["คำสั่งยังคงใช้ได้เต็มที่เหมือนเดิม", "คำสั่งอาจไม่สมบูรณ์ตามรูปแบบที่กฎหมายกำหนด และถูกโต้แย้ง/เพิกถอนภายหลังได้", "คำสั่งมีผลเฉพาะกับเจ้าหน้าที่เท่านั้น", "คำสั่งเปลี่ยนเป็นคำแนะนำ"], "answer": 1, "explanation": "คำสั่งทางปกครองที่กระทบสิทธิ ต้องมีเหตุผลกำกับ — ขาดเหตุผล = รูปแบบไม่สมบูรณ์ อาจถูกอุทธรณ์/เพิกถอนภายหลัง (ข) (ก)(ค)(ง) ไม่ตรงกับหลักการ", "shortcut": "คำสั่ง = ต้องมีเหตุผล — ขาดเหตุผล คำสั่งอ่อนแรง", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0004", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "appeal_vs_court", "difficulty": 3, "stem": "ผู้ได้รับคำสั่งทางปกครองไม่พอใจคำสั่ง ตามลำดับขั้นตอนปกติ ควรทำอะไรก่อนนำคดีไปฟ้องศาลปกครอง?", "figure_svg": null, "choices": ["ฟ้องศาลปกครองได้ทันที", "อุทธรณ์ต่อเจ้าหน้าที่/คณะกรรมการที่กฎหมายกำหนดก่อน", "ร้องเรียนต่อ ป.ป.ช.", "รอให้คำสั่งสิ้นผลไปเอง"], "answer": 1, "explanation": "ตาม พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง ต้องอุทธรณ์ตามขั้นตอนที่กฎหมายกำหนดก่อน จึงจะนำคดีไปฟ้องศาลปกครองได้ (เว้นแต่เข้าเงื่อนไขพิเศษ เช่น เหตุฉุกเฉิน) (ข) (ก) ข้ามขั้นตอน (ค) ป.ป.ช. เป็นคนละช่องทาง (ง) ไม่ใช่ทางแก้ตามกฎหมาย", "shortcut": "อุทธรณ์ก่อน → ศาลปกครองเป็นลำดับถัดไป", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0005", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "right_to_document", "difficulty": 2, "stem": "ผู้เกี่ยวข้องกับคำสั่งทางปกครองมีสิทธิอะไรเกี่ยวกับสำนวนของเจ้าหน้าที่?", "figure_svg": null, "choices": ["ไม่มีสิทธิในเอกสารใด ๆ", "ขอตรวจ/ขอสำเนาเอกสารในสำนวน ภายในขอบเขตที่กฎหมายกำหนด", "ขอแก้ไขเอกสารในสำนวนได้ตามใจ", "ยึดสำนวนเก็บไว้ที่บ้านได้"], "answer": 1, "explanation": "กฎหมายให้สิทธิผู้เกี่ยวข้องขอตรวจเอกสารในสำนวนภายในขอบเขตที่กฎหมายกำหนด (เช่น ยกเว้นเอกสารลับ) (ข) (ก) ปิดกั้นสิทธิเกินไป (ค)(ง) เกินขอบเขตสิทธิ", "shortcut": "สิทธิตรวจสำนวน — ขอดู/ขอสำเนาได้ แต่แก้/ยึดไม่ได้", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0006", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "urgent_exception", "difficulty": 3, "stem": "ข้อใดเป็นข้อยกเว้นที่ทำให้เจ้าหน้าที่ออกคำสั่งทางปกครองโดยไม่ต้องรับฟังคู่กรณีล่วงหน้าได้?", "figure_svg": null, "choices": ["เรื่องทุกเรื่อง เพราะเจ้าหน้าที่มีอำนาจเต็ม", "กรณีเร่งด่วนหรือที่กฎหมายกำหนดไว้เป็นอย่างอื่น", "กรณีที่คู่กรณีเป็นคนมีฐานะรวย", "กรณีที่คู่กรณีอยู่ต่างจังหวัด"], "answer": 1, "explanation": "ข้อยกเว้นของการรับฟังคู่กรณีคือกรณีเร่งด่วน หรือกรณีที่กฎหมายกำหนดไว้เป็นอย่างอื่น (เช่น คำสั่งป้องกันอันตรายสาธารณะ) (ข) (ก) ไม่มีข้อยกเว้นแบบเหมารวม (ค)(ง) ไม่ใช่เงื่อนไขตามกฎหมาย", "shortcut": "ข้อยกเว้น = เร่งด่วน / กฎหมายกำหนดเป็นอย่างอื่น", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0007", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "written_format", "difficulty": 1, "stem": "คำสั่งทางปกครองมีรูปแบบเป็นอย่างไร?", "figure_svg": null, "choices": ["วาจาได้โดยไม่ต้องเป็นลายลักษณ์อักษร", "เป็นลายลักษณ์อักษร ลงชื่อเจ้าหน้าที่และระบุหน่วยงาน", "เป็นข้อความในกลุ่มแชทได้", "ไม่ต้องลงชื่อ แค่พิมพ์ก็พอ"], "answer": 1, "explanation": "คำสั่งทางปกครองต้องทำเป็นลายลักษณ์อักษร ระบุหน่วยงานและลงชื่อเจ้าหน้าที่ (ข) (ก)(ค)(ง) ไม่ครบตามรูปแบบที่กฎหมายกำหนด", "shortcut": "คำสั่ง = ลายลักษณ์อักษร + ระบุหน่วยงาน + ลงชื่อ + เหตุผล", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0008", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "unlawful_act", "difficulty": 2, "stem": "เจ้าหน้าที่ออกคำสั่งเพิกถอนสิทธิของผู้ประกอบการโดยไม่แจ้งและไม่รับฟังความคิดเห็น ผู้เสียหายสามารถอ้างอะไรได้?", "figure_svg": null, "choices": ["คำสั่งชอบด้วยกฎหมาย เพราะเจ้าหน้าที่มีอำนาจ", "คำสั่งไม่ชอบด้วยกฎหมาย และอาจถูกเพิกถอนภายหลัง", "คำสั่งมีผลทันที อุทธรณ์ไม่ได้", "ผู้เสียหายต้องไปร้องศาลอาญา"], "answer": 1, "explanation": "ออกคำสั่งโดยข้ามขั้นตอน (ไม่แจ้ง ไม่รับฟัง) = ไม่ทำตามวิธีปฏิบัติราชการทางปกครอง = คำสั่งไม่ชอบด้วยกฎหมาย อาจถูกอุทธรณ์/เพิกถอน (ข) (ก)(ค) คำสั่งที่ไม่ชอบด้วยกฎหมายไม่ใช่ 'ชอบโดยปริยาย' (ง) เป็นเรื่องคดีปกครอง ไม่ใช่อาญา", "shortcut": "ข้ามขั้นตอน = ไม่ชอบด้วยกฎหมาย", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0009", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "vs_court", "difficulty": 3, "stem": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 กับ พ.ร.บ.จัดตั้งศาลปกครองและวิธีพิจารณาคดีปกครอง พ.ศ. 2542 ต่างกันอย่างไร?", "figure_svg": null, "choices": ["ไม่ต่างกัน ใช้แทนกันได้", "ฉบับ 2539 กำหนดกระบวนการก่อนออกคำสั่ง ส่วนฉบับ 2542 กำหนดกระบวนการพิจารณาคดีในศาลปกครอง", "ฉบับ 2542 ใช้กับคดีแพ่งทั่วไป", "ฉบับ 2539 ใช้เฉพาะกับ ก.พ."], "answer": 1, "explanation": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 = กระบวนการ 'ก่อน' ออกคำสั่ง (แจ้ง รับฟัง เหตุผล อุทธรณ์) ส่วน พ.ร.บ.จัดตั้งศาลปกครองฯ พ.ศ. 2542 = กระบวนการในศาลปกครองหลังมีข้อพิพาท (ข) (ก)(ค)(ง) ไม่ถูกต้อง", "shortcut": "2539 = กระบวนการก่อนออกคำสั่ง · 2542 = กระบวนการในศาลปกครอง", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-PROC-0010", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "application_case", "difficulty": 3, "stem": "บริษัท X ยื่นขอใบอนุญาตตั้งโรงงาน เจ้าหน้าที่ไม่ตอบ ไม่แจ้งเหตุผล ทิ้งเรื่องไว้ 8 เดือน บริษัทควรทำอะไรตามลำดับที่ผ่านมา?", "figure_svg": null, "choices": ["ฟ้องศาลอาญาข้อหาละเลยหน้าที่", "ทบทวน/อุทธรณ์ตามขั้นตอน และหากยังไม่ได้ นำคดีไปฟ้องศาลปกครอง", "ยื่นเรื่องต่อสภาท้องถิ่น", "รอไปเรื่อย ๆ จนกว่าจะได้อนุญาต"], "answer": 1, "explanation": "การเพิกเฉยไม่ตอบ = คำสั่งทางปกครองโดยการนิ่งเฉย ผู้เสียหายมีสิทธิอุทธรณ์/ใช้สิทธิตามขั้นตอน พ.ร.บ.วิธีปฏิบัติฯ และหากไม่เป็นผล ฟ้องศาลปกครองได้ (ข) (ก) ไม่ใช่อาญาโดยตรง (ค) ไม่ใช่ช่องทาง (ง) เสียเวล่าและสิทธิ", "shortcut": "คำสั่งทางปกครองรวมถึงการนิ่งเฉย — อุทธรณ์ก่อน ศาลเป็นลำดับถัดไป", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0001", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "duty_scope", "difficulty": 2, "stem": "เจ้าหน้าที่ขับรถยนต์ราชการไปส่งเอกสารระหว่างปฏิบัติราชการ เบรกแตกชนทรัพย์สินผู้อื่นเสียหาย ใครต้องชดใช้ให้ผู้เสียหาย?", "figure_svg": null, "choices": ["เจ้าหน้าที่ต้องชดใช้เองเต็มจำนวน", "หน่วยงานของรัฐชดใช้ให้ผู้เสียหาย", "ผู้เสียหายต้องซ่อมเอง", "ทั้งสองฝ่ายตกลงกันเองนอกศาล"], "answer": 1, "explanation": "เป็นการละเมิด 'ในหน้าที่' โดยไม่จงใจและไม่ประมาทร้ายแรง (เบรกแตกเป็นเหตุสุดวิสัย/ปัญหาบำรุงรักษา) → ตาม พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 หน่วยงานของรัฐต้องชดใช้ให้ผู้เสียหาย (ข) (ก) ใช้เฉพาะกรณีจงใจ/ประมาทร้ายแรง (ค)(ง) ไม่ตรงกับหลักกฎหมาย", "shortcut": "ในหน้าที่ + ไม่ประมาทร้ายแรง → หน่วยงานจ่าย", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0002", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "gross_negligence", "difficulty": 3, "stem": "กรณีเดียวกับข้อ 1 แต่เจ้าหน้าที่ขับรถด้วยความเร็วสูงมากทั้งที่ฝนตกหนัก — ผลตามกฎหมายคืออะไร?", "figure_svg": null, "choices": ["หน่วยงานชดใช้ แล้วหน่วยงานไม่ไล่เบี้ยเอาคืนเด็ดขาด", "หน่วยงานชดใช้ให้ผู้เสียหายก่อน แล้วไล่เบี้ยเอาคืนจากเจ้าหน้าที่", "เจ้าหน้าที่ไม่ต้องรับผิดใด ๆ", "ผู้เสียหายฟ้องเจ้าหน้าที่ไม่ได้"], "answer": 1, "explanation": "ขับรถความเร็วสูงในฝนตกหนัก = ประมาทร้ายแรง → หน่วยงานจ่ายก่อน แล้วไล่เบี้ยคืนจากเจ้าหน้าที่ (ไล่เบี้ยได้ตามขอบเขตที่กฎหมายกำหนด) (ข) (ก) ไล่เบี้ยได้เมื่อประมาทร้ายแรง (ค)(ง) ไม่ถูกต้อง", "shortcut": "จงใจ/ประมาทร้ายแรง → หน่วยงานจ่ายก่อน ไล่เบี้ยคืน", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0003", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "outside_duty", "difficulty": 2, "stem": "เจ้าหน้าที่ขับรถส่วนตัวไปเที่ยววันหยุด ชนรถผู้อื่นเสียหาย — ใครต้องรับผิด?", "figure_svg": null, "choices": ["หน่วยงานของรัฐเป็นผู้รับผิด", "เจ้าหน้าที่รับผิดเองเต็มที่ เช่นเดียวกับบุคคลทั่วไป", "รัฐจ่ายครึ่งหนึ่ง เจ้าหน้าที่ครึ่งหนึ่ง", "ไม่มีใครต้องรับผิด"], "answer": 1, "explanation": "เป็นการกระทำนอกหน้าที่ (ไปเที่ยวส่วนตัว) → เจ้าหน้าที่รับผิดเองเต็มที่ตามหลักละเมิดทั่วไป หน่วยงานไม่เกี่ยวข้อง (ข) (ก)(ค)(ง) ไม่ถูกต้อง", "shortcut": "นอกหน้าที่ = รับผิดเองเต็ม ๆ หน่วยงานไม่เกี่ยว", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0004", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "discipline_serious", "difficulty": 2, "stem": "ข้าราชการพลเรือนกระทำความผิดวินัยอย่างร้ายแรง โทษทางวินัยที่รุนแรงที่สุดคืออะไร?", "figure_svg": null, "choices": ["ตักเตือน", "หักเงินเดือน", "ปลดออก หรือ ไล่ออก", "พักใช้ใบอนุญาตทำงาน"], "answer": 2, "explanation": "ความผิดวินัยร้ายแรงมีโทษสูงสุดคือ ปลดออก หรือ ไล่ออก (ค) (ก)(ข) เป็นโทษของความผิดวินัยไม่ร้ายแรง (ง) ไม่ใช่โทษทางวินัยข้าราชการไทย", "shortcut": "วินัยร้ายแรง → ปลดออก/ไล่ออก · ไม่ร้ายแรง → ตักเตือน/หักเงินเดือน", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0005", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "bribery_case", "difficulty": 3, "stem": "เจ้าหน้าที่รับเงินจากผู้ขอใบอนุญาตเพื่อแลกกับการอนุมัติ — การกระทำนี้ผิดมิติใดบ้าง?", "figure_svg": null, "choices": ["ผิดทางอาญาเท่านั้น", "ผิดวินัย และผิดจริยธรรม แต่อาญาต้องรอศาลตัดสิน", "อาจผิดทั้งวินัย จริยธรรม และเป็นความผิดอาญา (รับสินบน) พร้อมกันได้", "ไม่ผิด ถ้าผู้ให้เต็มใจ"], "answer": 2, "explanation": "การรับสินบนอาจผิดพร้อมกันหลายมิติ: วินัย (ประพฤติชั่วอย่างร้ายแรง) · จริยธรรม (ไม่ซื่อสัตย์สุจริต ฝ่าฝืนมาตรฐานทางจริยธรรม) · อาญา (รับสินบนตามประมวลกฎหมายอาญา) — คนละมิติแยกกัน ลงโทษซ้อนได้ (ค) (ก)(ข) ไม่ครบมิติ (ง) ผู้ให้ยินยอมก็ไม่ทำให้การรับสินบนถูก", "shortcut": "คดีทุจริต = ผิดซ้อนวินัย+อาญา+จริยธรรม ได้ในคดีเดียว", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551 / พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0006", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "gift_acceptance", "difficulty": 2, "stem": "ผู้มาติดต่อนำกระเช้าผลไม้ขนาดใหญ่มาให้หัวหน้าส่วนราชการในช่วงปีใหม่ ตามหลักจริยธรรมหัวหน้าส่วนราชการควรทำอย่างไร?", "figure_svg": null, "choices": ["รับไว้เพราะเป็นธรรมเนียมปีใหม่", "ปฏิเสธ หรือนำส่ง/แจ้งตามระเบียบของหน่วยงาน", "รับไว้แล้วแบ่งให้ลูกน้อง", "ขอให้ส่งมาให้ทุกปี"], "answer": 1, "explanation": "ทรัพย์สิน/ของขวัญจากผู้มาติดต่อ อาจเข้าข่ายผลประโยชน์ทับซ้อนและขัดกับหลักซื่อสัตย์สุจริต/จริยธรรม — ควรปฏิเสธหรือส่งตามระเบียบ (ข) (ก)(ค)(ง) ฝ่าฝืนหลักจริยธรรมและอาจเข้าข่ายวินัย", "shortcut": "ของขวัญจากผู้มาติดต่อ = ปฏิเสธหรือส่งตามระเบียบ ห้ามรับส่วนตัว", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0007", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "ethics_principles", "difficulty": 1, "stem": "ข้อใด**ไม่ใช่**องค์ประกอบของมาตรฐานทางจริยธรรมข้าราชการพลเรือน?", "figure_svg": null, "choices": ["ยึดหลักนิติธรรม ปฏิบัติหน้าที่ตามกฎหมาย", "ซื่อสัตย์สุจริต ไม่รับทรัพย์สินโดยมิชอบ", "เลือกปฏิบัติต่อผู้มาติดต่อตามความสัมพันธ์ส่วนตัว", "ประโยชน์สาธารณะมาก่อนประโยชน์ส่วนตน"], "answer": 2, "explanation": "จริยธรรมข้าราชการห้ามการเลือกปฏิบัติตามความสัมพันธ์ส่วนตัว (ต้องเสมอภาค) — ข้อ (ค) จึงไม่ใช่ส่วนหนึ่งของมาตรฐานจริยธรรม แต่เป็นสิ่งต้องห้าม (ก)(ข)(ง) ล้วนเป็นหลักจริยธรรมที่ยอมรับกัน", "shortcut": "จริยธรรม: นิติธรรม–ซื่อสัตย์–ไม่เลือกปฏิบัติ–สาธารณะมาก่อน", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0008", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "appeal_discipline", "difficulty": 3, "stem": "ข้าราชการพลเรือนไม่พอใจกับคำสั่งลงโทษทางวินัยของตนเอง ควรทำอย่างไรเป็นลำดับแรก?", "figure_svg": null, "choices": ["ฟ้องศาลปกครองทันที", "อุทธรณ์คำสั่งลงโทษทางวินัยตามขั้นตอนที่กฎหมายกำหนด", "ร้องเรียนผู้บังคับบัญชาโดยวาจา", "ลาออกทันที"], "answer": 1, "explanation": "คำสั่งลงโทษทางวินัยมีกระบวนการอุทธรณ์ที่กำหนดไว้ใน พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551 — ต้องอุทธรณ์ตามขั้นตอนก่อน (ข) (ก) ศาลปกครองเป็นช่องทางต่อเนื่องภายหลัง (ค) ไม่มีผลทางกฎหมาย (ง) เสียสิทธิโดยไม่จำเป็น", "shortcut": "ไม่พอใจโทษวินัย → อุทธรณ์ตามขั้นตอนก่อน", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0009", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "gross_negligence_def", "difficulty": 2, "stem": "'ประมาทร้ายแรง' ในหลักความรับผิดทางละเมิดของเจ้าหน้าที่หมายถึงข้อใด?", "figure_svg": null, "choices": ["ลืมเล็กน้อยโดยไม่ตั้งใจ ใคร ๆ ก็ทำได้", "ประมาทอย่างยิ่งจนไม่แยแสต่อผลเสียหายที่จะเกิดขึ้น", "ตั้งใจทำให้ผู้อื่นเสียหายโดยตรง", "คำนวณผิดเล็กน้อยในงานตัวเลข"], "answer": 1, "explanation": "ประมาทร้ายแรง = ประมาทอย่างยิ่งจนไม่แยแสผล — ระดับใกล้กับจงใจ (เช่น ขับรถเร็วมากบนถนนลื่น) (ข) (ก) เป็นประมาทธรรมดา (ค) เป็นจงใจ ไม่ใช่ประมาท (ง) ไม่เข้าข่าย", "shortcut": "ประมาทร้ายแรง ≈ ไม่แยแสผล — ใกล้จงใจ ต่างจากประมาทธรรมดา", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original"}, {"id": "S3-LIAB-0010", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "case_application", "difficulty": 3, "stem": "เจ้าหน้าที่รักษาความปลอดภัยประจำอาคารราชการ ปล่อยปละละเลยไม่ตรวจตราตามเวร จนทรัพย์สินของผู้มาติดต่องานราชการถูกขโมย ข้อใดวิเคราะห์ได้ถูกต้องที่สุด?", "figure_svg": null, "choices": ["ไม่มีใครรับผิด เพราะคนร้ายเป็นผู้กระทำ", "เจ้าหน้าที่อาจต้องรับผิดเนื่องจากละเลยหน้าที่โดยประมาท และอาจเข้าข่ายความผิดวินัย", "หน่วยงานต้องจ่ายทุกกรณีเสมอ", "ผู้มาติดต่อต้องติดตามคนร้ายเอง"], "answer": 1, "explanation": "การละเลยหน้าที่ตามที่รับมอบหมาย (ไม่ตรวจตราตามเวร) เป็นการกระทำใน/ระหว่างปฏิบัติหน้าที่โดยประมาท อาจต้องชดใช้ค่าเสียหายตามหลักละเมิด (ขึ้นกับระดับความประมาท) และอาจผิดวินัยฐานละเลยหน้าที่ (ข) (ก) ไม่ถูกต้องโดยหลักหน้าที่ (ค) 'ทุกกรณีเสมอ' ผิด — ขึ้นกับความผิดประมาท (ง) ไม่จริง", "shortcut": "ละเลยหน้าที่ = ประมาทในหน้าที่ — วิเคราะห์ทั้งมิติละเมิดและวินัย", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 / พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551", "needs_review": true, "origin": "original"}, {"id": "S2-CONV-0001", "subject": "english", "topic": "conversation", "subtopic": "thanks_response", "difficulty": 1, "stem": "A: Thank you very much for your help with the report.\nB: ______", "figure_svg": null, "choices": ["It's nothing. Don't mention it.", "You're welcome. Glad I could help.", "No, thank you.", "That's right."], "answer": 1, "explanation": "A ขอบคุณ B → คำตอบมาตรฐานคือ You're welcome / My pleasure ตัวเลือก (ก) ฟังดูเหมือนเหน็บว่าไม่ได้ช่วยอะไร ไม่สุภาพในบริบททำงาน (ค) ตอบขอบคุณกลับแบบผิดหน้าที่ (ง) ไม่ตอบประเด็น", "shortcut": "จำคู่มาตรฐาน: Thank you ↔ You're welcome / My pleasure / Don't mention it", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0002", "subject": "english", "topic": "conversation", "subtopic": "phone_call", "difficulty": 1, "stem": "A: Good morning, this is Somjai from IT Support. How can I help you?\nB: ______", "figure_svg": null, "choices": ["Give me IT now.", "I have a problem with my computer login. Could you help?", "Who are you?", "Yes, I am."], "answer": 1, "explanation": "บริบทโทรศัพท์ทางการ — B ควรบอกปัญหาสั้น ๆ และขอความช่วยเหลืออย่างสุภาพ (ข) ตรงที่สุด (ก) หยาบ ไม่สุภาพ (ค) ไม่เกี่ยวกับการขอความช่วยเหลือ (ง) ตอบรูปประโยคผิด (Yes, I am ใช้ตอบคำถาม yes/no แบบ Are you…? เท่านั้น)", "shortcut": "โทรศัพท์ทางการ: แจ้งชื่อ + ปัญหาสั้น ๆ + ขอความช่วยเหลือด้วย Could/Would you…?", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0003", "subject": "english", "topic": "conversation", "subtopic": "apology", "difficulty": 1, "stem": "A: I'm sorry, I didn't bring the file you asked for.\nB: ______", "figure_svg": null, "choices": ["That's okay. You can send it later.", "I'm sorry too.", "You must bring it now.", "It's your business."], "answer": 0, "explanation": "A ขอโทษ → B ควรตอบรับคำขอโทษอย่างใจกว้าง (ก) คือคำตอบมาตรฐาน (ข) เหมือนขอโทษกลับทั้งที่ไม่ได้ผิด (ค) สั่งห้วน ไม่สุภาพ (ง) เฉยเมย ไม่ใช่การตอบรับคำขอโทษ", "shortcut": "Sorry ↔ It's okay / That's alright / Never mind / No problem", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0004", "subject": "english", "topic": "conversation", "subtopic": "request", "difficulty": 2, "stem": "A: ______ sign here, please?\nB: Of course.", "figure_svg": null, "choices": ["You sign", "Could you", "Why you", "Are you"], "answer": 1, "explanation": "ขอร้องอย่างสุภาพต้องใช้ modal สุภาพ + กริยา — Could you sign here, please? (ข) ถูกต้อง (ก) เป็นการสั่ง (ค) โครงสร้างผิด (ง) ถาม yes/no ไม่เข้ากับคำตอบ ", "shortcut": "ขออย่างสุภาพ: Could/Would you…? + please — ห้ามใช้โครงกริยาล้วน ๆ สั่ง", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0005", "subject": "english", "topic": "conversation", "subtopic": "suggestion", "difficulty": 2, "stem": "A: The deadline is tomorrow and the data is not ready yet.\nB: Why don't we ______", "figure_svg": null, "choices": ["complain to the director?", "ask for a one-day extension from the supervisor?", "submit it incomplete?", "do nothing?"], "answer": 1, "explanation": "A เสนอปัญหา → B ควรเสนอทางแก้ที่สมเหตุสมผลและสุภาพ (ข) ขอเวลาเพิ่มเป็นทางแก้ที่เหมาะสม (ก) ไม่แก้ปัญหาจริง (ค) ทำงานไม่เสร็จและผิดมาตรฐาน (ง) เพิกเฉย ไม่รับผิดชอบ", "shortcut": "Why don't we…? = เสนอไอเดีย — เลือกคำตอบที่แก้ปัญหาจริง ไม่ใช่หนีปัญหา", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0006", "subject": "english", "topic": "conversation", "subtopic": "meeting_invite", "difficulty": 2, "stem": "A: Would you like to join us for lunch after the meeting?\nB: ______", "figure_svg": null, "choices": ["I don't like lunch.", "I'd love to, but I have another appointment.", "No, you wouldn't.", "Yes, I would like it."], "answer": 1, "explanation": "เชิญ → ตอบรับหรือปฏิเสธอย่างสุภาพ พร้อมเหตุผล (ข) สุภาพที่สุด (ก) ปฏิเสธตรงเกินไปโดยไม่มีเหตุผล (ค) ตอบกลับผิดรูป (ง) ใช้ would เกินจำเป็นและไม่ได้ปฏิเสธ", "shortcut": "Would you like…? → I'd love to / Yes, please / I'd love to, but… (+ เหตุผล)", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0007", "subject": "english", "topic": "conversation", "subtopic": "complaint", "difficulty": 2, "stem": "A: The printer on this floor has been out of order for two days.\nB: ______", "figure_svg": null, "choices": ["So?", "I see. I'll report it to the maintenance team right away.", "It's not my job.", "Buy a new one."], "answer": 1, "explanation": "A รายงานปัญหา → B ควรรับทราบและดำเนินการ (ข) คือคำตอบที่รับผิดชอบและเป็นมืออาชีพ (ก)(ค)(ง) ไม่รับผิดชอบ/หยาบ ไม่เหมาะกับการทำงานเป็นทีม", "shortcut": "พบปัญหา → รับทราบ + แจ้งคนที่เกี่ยวข้อง ไม่ใช่โบ้ยหรือเพิกเฉย", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0008", "subject": "english", "topic": "conversation", "subtopic": "offering_help", "difficulty": 2, "stem": "A: This box is quite heavy.\nB: ______", "figure_svg": null, "choices": ["Be careful.", "Let me help you carry it.", "Yes, it is heavy.", "Put it down."], "answer": 1, "explanation": "A สื่อว่าของหนัก → B ควรเสนอช่วย (ข) เสนอความช่วยเหลือตรงจุด (ก) เตือนเฉย ๆ ไม่ช่วย (ค) แค่ยืนยัน (ง) สั่งโดยไม่ช่วย", "shortcut": "เห็นคนเดือดร้อน → เสนอช่วย: Let me help you… / May I help you…?", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0009", "subject": "english", "topic": "conversation", "subtopic": "formal_refusal", "difficulty": 3, "stem": "A: Could you finish the report by this afternoon?\nB: I'm afraid that won't be possible because ______", "figure_svg": null, "choices": ["I don't want to.", "I have already committed to another urgent task, but I can submit it tomorrow morning.", "no.", "it's impossible."], "answer": 1, "explanation": "ปฏิเสธในบริบททางการต้องมีเหตุผล + ทางเลือก (ข) ปฏิเสธอย่างสุภาพพร้อมเสนอทางออก สอดคล้อง I'm afraid… (ก) ไม่สุภาพ (ค) ไม่สุภาพและไม่มีเหตุผล (ง) แข็ง ไร้ทางออก", "shortcut": "ปฏิเสธทางการ: I'm afraid… + เหตุผล + ทางเลือก — ห้ามตอบ no ลอย ๆ", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-CONV-0010", "subject": "english", "topic": "conversation", "subtopic": "congratulation", "difficulty": 3, "stem": "A: I've been promoted to senior analyst.\nB: ______", "figure_svg": null, "choices": ["About time.", "Congratulations! You really deserve it.", "That's your business.", "I don't care."], "answer": 1, "explanation": "A แจ้งข่าวดี/ความสำเร็จส่วนตัว → B ควรแสดงความยินดี (ข) ถูกต้องและเหมาะสม (ก) ดูถูก (ค) เฉยชา (ง) ไม่ให้เกียรติเพื่อนร่วมงาน", "shortcut": "ข่าวดี → Congratulations! · ข่าวร้าย → I'm sorry to hear that.", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0001", "subject": "english", "topic": "vocabulary", "subtopic": "synonym", "difficulty": 1, "stem": "The word \"crucial\" in the sentence \"It is crucial that we finish on time\" is closest in meaning to:", "figure_svg": null, "choices": ["optional", "important", "frequent", "late"], "answer": 1, "explanation": "crucial = สำคัญมาก ใกล้เคียงกับ important ที่สุด (ข) (ก) optional = ทางเลือก ไม่บังคับ ตรงข้าม (ค) frequent = บ่อย ไม่เกี่ยวความสำคัญ (ง) late = ช้า ไม่เข้าบริบท", "shortcut": "crucial ≈ vital ≈ essential ≈ significant — ทุกตัว = สำคัญมาก เลือกความแรงใกล้เคียงกัน", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0002", "subject": "english", "topic": "vocabulary", "subtopic": "office_vocab", "difficulty": 1, "stem": "The word \"approve\" in \"The committee will approve the budget next week\" means:", "figure_svg": null, "choices": ["officially accept", "reject", "sign", "delay"], "answer": 0, "explanation": "approve = อนุมัติ/รับรองอย่างเป็นทางการ → officially accept (ก) (ข) reject = ปฏิเสธ ตรงข้าม (ค) sign = ลงนาม ไม่ใช่ความหมายของ approve โดยตรง (ง) delay = เลื่อน", "shortcut": "approve ≈ officially agree to / authorize — คู่ตรงข้ามคือ reject", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0003", "subject": "english", "topic": "vocabulary", "subtopic": "confusing_words", "difficulty": 2, "stem": "The new rule will ______ all government offices from January.", "figure_svg": null, "choices": ["effect", "effort", "affect", "afford"], "answer": 2, "explanation": "ต้องการกริยา 'ส่งผลกระทบ' → affect (ค) (ก) effect เป็นนามแปลว่า ผล หรือกริยาแปลว่า ทำให้เกิด แต่ใช้ในความหมายนี้ไม่ตรง (ข) effort = ความพยายาม (ง) afford = มีกำลังซื้อ/พอจ่าย", "shortcut": "affect (v.) = กระทบ · effect (n.) = ผล — affect มาก่อน effect เสมอเมื่อแปลว่ากระทบ", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0004", "subject": "english", "topic": "vocabulary", "subtopic": "collocation", "difficulty": 2, "stem": "The team managed to ______ the deadline with two days to spare.", "figure_svg": null, "choices": ["have", "do", "take", "meet"], "answer": 3, "explanation": "meet the deadline = ส่งทันกำหนด (collocation มาตรฐาน) (ง) (ก) have the deadline เป็นโครงผิด (ข) do the deadline ไม่ใช่ collocation (ค) take the deadline ไม่ใช่ collocation", "shortcut": "collocation ทอง: meet a deadline / meet expectations — meet = ทำให้ได้ตาม", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0005", "subject": "english", "topic": "vocabulary", "subtopic": "phrasal_verb", "difficulty": 2, "stem": "The inspectors will ______ the factory next week.", "figure_svg": null, "choices": ["carry out", "put off", "turn down", "look forward to"], "answer": 0, "explanation": "carry out = ดำเนินการ (carry out an inspection) (ก) ถูกต้อง (ข) put off = เลื่อนออกไป (ค) turn down = ปฏิเสธ (ง) look forward to = รอคอย (ใช้กับ -ing)", "shortcut": "carry out = ดำเนินการ — collocation กับ inspection/plan/survey", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0006", "subject": "english", "topic": "vocabulary", "subtopic": "government_vocab", "difficulty": 2, "stem": "All departments must ______ with the new procurement regulations.", "figure_svg": null, "choices": ["apply", "supply", "comply", "imply"], "answer": 2, "explanation": "comply with = ปฏิบัติตาม (กริยาที่คู่กับ with เสมอ) (ค) (ก) apply for = สมัคร/ขอ (ข) supply = จัดหาให้ (ง) imply = สื่อความหมายโดยนัย", "shortcut": "comply **with** = ปฏิบัติตาม — ออกซ้ำแทบทุกปี ต้องจำคู่ with", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0007", "subject": "english", "topic": "vocabulary", "subtopic": "context_clue", "difficulty": 3, "stem": "Although the report was lengthy, it was clear and concise at the same time. The word \"concise\" most nearly means:", "figure_svg": null, "choices": ["confusing", "brief and clear", "detailed", "boring"], "answer": 1, "explanation": "บริบทขัดแย้งกับ lengthy (ยาว) → concise ต้องหมายถึงสั้นและชัด (ข) (ก) confusing = สับสน (ค) detailed = ละเอียด ตรงข้ามกับ concise (ง) boring = น่าเบื่อ ใช้บริบทนี้ไม่ได้", "shortcut": "เจอ however/although/but → คำที่ตามมามักมีความหมายตรงข้าม", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0008", "subject": "english", "topic": "vocabulary", "subtopic": "confusing_words", "difficulty": 2, "stem": "She gave me useful ______ about preparing the exam.", "figure_svg": null, "choices": ["advise", "advices", "advising", "advice"], "answer": 3, "explanation": "advice เป็นคำนามนับไม่ได้ แปลว่า คำแนะนำ (ง) ถูกต้อง (ก) advise เป็นกริยา (แนะนำ) (ข) advices ไม่มีรูปพหูพจน์ (ค) advising เป็น gerund ไม่เข้ากับบริบทนี้", "shortcut": "advice (n.) นับไม่ได้ — ห้ามเติม -s · advise (v.) = แนะนำ", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0009", "subject": "english", "topic": "vocabulary", "subtopic": "business_vocab", "difficulty": 3, "stem": "The company's ______ rose steadily after the new marketing campaign.", "figure_svg": null, "choices": ["revenue", "losses", "expense", "debt"], "answer": 0, "explanation": "บริบทการตลาดดี → รายได้เพิ่ม → revenue (ก) (ข) losses คือขาดทุน ตรงข้ามบริบท (ค) expense คือรายจ่าย ไม่ใช่สิ่งที่ขึ้นเพื่อบอกผลดีของแคมเปญ (ง) debt = หนี้ ไม่สัมพันธ์โดยตรง", "shortcut": "revenue = รายได้ · expense = รายจ่าย — ธุรกิจดี = revenue ขึ้น", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-VOC-0010", "subject": "english", "topic": "vocabulary", "subtopic": "phrasal_verb", "difficulty": 3, "stem": "Many staff were on sick leave, so the manager decided to ______ the meeting.", "figure_svg": null, "choices": ["called on", "put off", "taken off", "called off"], "answer": 1, "explanation": "put off = เลื่อนออกไป — บริบทขาดเจ้าหน้าที่จำนวนมาก → เลื่อนประชุม (ข) (ก) called on = แวะเยี่ยม/เรียกร้อง (ค) taken off = ถอดออก/เครื่องบินขึ้น (ง) called off = ยกเลิกถาวร — ถ้าโจทย์บอกว่า 'ยกเลิกช่วงนี้' เฉพาะคราวนี้ใช้ put off เหมาะกว่า", "shortcut": "put off = เลื่อน · call off = ยกเลิก — ดูว่าเลื่อน (ไม่แน่นอนว่าเมื่อไหร่) หรือ ยกเลิกเลย", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0001", "subject": "english", "topic": "grammar", "subtopic": "tense_past", "difficulty": 1, "stem": "The committee ______ the proposal yesterday.", "figure_svg": null, "choices": ["approves", "will approve", "approved", "has approved"], "answer": 2, "explanation": "คำใบ้ 'yesterday' → เหตุการณ์จบแล้วในอดีต ใช้ Past Simple (ค) approved (ก) approves = ปัจจุบัน (ข) will approve = อนาคต (ง) has approved = Present Perfect ห้ามใช้กับคำบอกเวลาอดีต", "shortcut": "เห็น yesterday/last/ago/in + ปีอดีต → ตอบ V2 เท่านั้น", "study_ref": "english-grammar-1", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0002", "subject": "english", "topic": "grammar", "subtopic": "present_perfect", "difficulty": 2, "stem": "The project ______ under development since 2022.", "figure_svg": null, "choices": ["is", "has been", "was", "had been"], "answer": 1, "explanation": "since + จุดเริ่มในอดีต + ต่อเนื่องถึงปัจจุบัน → Present Perfect (continuous) (ข) has been (ก) is = ปัจจุบันธรรมดา ไม่เข้ากับ since (ค) was = จบแล้ว ขัดกับ since (ง) had been = Past Perfect ใช้เมื่อเล่าอดีตเชิงลำดับเหตุการณ์", "shortcut": "since + จุดเริ่ม → have/has + V3 · for + ระยะเวลา → have/has + V3", "study_ref": "english-grammar-1", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0003", "subject": "english", "topic": "grammar", "subtopic": "subject_verb_agreement", "difficulty": 2, "stem": "The quality of the training materials ______ improved significantly this year.", "figure_svg": null, "choices": ["have", "are", "were", "has"], "answer": 3, "explanation": "ประธานคือ 'The quality' (เอกพจน์) — วลี 'of the training materials' เป็นส่วนขยาย ไม่เปลี่ยนจำนวนประธาน → has improved (ง) (ก)(ข)(ค) เป็นกริยาพหูพจน์", "shortcut": "ตัด of/with/together with … ออกแล้วนับประธานจริงก่อนผันกริยา", "study_ref": "english-grammar-1", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0004", "subject": "english", "topic": "grammar", "subtopic": "article", "difficulty": 2, "stem": "______ email must be sent to ______ director by ______ end of the week.", "figure_svg": null, "choices": ["An / the / the", "A / a / the", "An / a / an", "The / the / a"], "answer": 0, "explanation": "email ขึ้นเสียงสระ → an email · director เจาะจงคนเดียวที่รู้กัน → the · 'the end of the week' เป็นวลีตายตัว → the (ก) (ข) A ผิดเพราะ email ขึ้นเสียงสระ และ a director ไม่ระบุเจาะจง (ค) a/an ผิดตำแหน่ง (ง) the email ไม่ตรงความหมายทั่วไป", "shortcut": "a/an ดูเสียงไม่ใช่ตัวอักษร · the = เจาะจง/มีอันเดียว · the end of the week จำเป็นสำนวน", "study_ref": "english-grammar-1", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0005", "subject": "english", "topic": "grammar", "subtopic": "conditional", "difficulty": 3, "stem": "If the budget ______ approved, the project will start in December.", "figure_svg": null, "choices": ["will be", "is", "would be", "was"], "answer": 1, "explanation": "Conditional Type 1: If + Present Simple → will + V1 — ห้าม will/would ใน if-clause → is approved (ข) (ก) will be ผิดกฎ (ค) would be ผิด (ง) was = Past Simple ใช้ไม่ได้ใน if-clause แบบนี้", "shortcut": "If + V1 → will + V1 · ตัดตัวเลือกที่มี will/would ในส่วน if ทิ้งได้เลย", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0006", "subject": "english", "topic": "grammar", "subtopic": "passive_voice", "difficulty": 2, "stem": "All applications ______ by the committee before the interview.", "figure_svg": null, "choices": ["will review", "are reviewing", "reviewed", "will be reviewed"], "answer": 3, "explanation": "applications (นาม) + ต้องการความหมาย 'ถูกพิจารณา' + เวลาอนาคต (before the interview) → Future passive: will be + V3 (ง) (ก) will review = active ต้องมีกรรมตาม (ข) are reviewing = active continuous ผิดความหมาย (ค) reviewed ขาดกริยาช่วย", "shortcut": "นามถูกกระทำ + อนาคต → will be + V3", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0007", "subject": "english", "topic": "grammar", "subtopic": "relative_clause", "difficulty": 2, "stem": "The officer ______ handles procurement will contact you.", "figure_svg": null, "choices": ["whom", "which", "who", "whose"], "answer": 2, "explanation": "ขยาย 'The officer' (คน) ในตำแหน่งประธานของอนุประโยค → who (ค) (ก) whom = กรรม ไม่ใช่ประธาน (ข) which = สิ่งของ (ง) whose = ความเป็นเจ้าของ", "shortcut": "who = คน(ประธาน) · whom = คน(กรรม) · which = สิ่ง · whose = เจ้าของ", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0008", "subject": "english", "topic": "grammar", "subtopic": "connector", "difficulty": 3, "stem": "The report was well researched; ______, it lacked clear recommendations.", "figure_svg": null, "choices": ["moreover", "therefore", "however", "consequently"], "answer": 2, "explanation": "ใจความสองฝั่งขัดแย้งกัน (ดี แต่ขาดคำแนะนำ) → ตัวเชื่อมขัดแย้ง however (ค) (ก) moreover = เพิ่มเติม (ข) therefore = ดังนั้น (ง) consequently = ผลที่ตามมา ทั้งสามตัวเป็นเหตุ-ผล/เพิ่มเติม ไม่เข้ากับความขัดแย้ง", "shortcut": "สองฝั่งขัดแย้ง → however/nevertheless · สองฝั่งไปทางเดียวกัน → moreover · เหตุ-ผล → therefore/consequently", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0009", "subject": "english", "topic": "grammar", "subtopic": "parallel_structure", "difficulty": 3, "stem": "The new procedure saves time, reduces errors, and ______.", "figure_svg": null, "choices": ["improvement of morale", "improves morale", "morale improves", "to improve morale"], "answer": 1, "explanation": "โครงขนานหลัง and: saves …, reduces … → ต้องเป็นกริยาเอกพจน์เฉพาะตัว 'improves' + กรรม (ข) (ก) เป็นนามวลี ไม่ขนานกับกริยา (ค) 'morale improves' ลำดับผิดและไม่ขนาน (ง) infinitive ไม่ขนาน", "shortcut": "เจอ and/or/but → เช็คว่าโครงสร้างสองฝั่งเหมือนกันไหม (กริยาคู่กริยา)", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-GRAM-0010", "subject": "english", "topic": "grammar", "subtopic": "error_identification", "difficulty": 3, "stem": "Choose the underlined part that is WRONG:\n\n(ก) All staff must (ข) comply (ค) to the new security regulations (ง) immediately.", "figure_svg": null, "choices": ["(ก)", "(ข)", "(ค)", "(ง)"], "answer": 2, "explanation": "comply คู่กับ with ไม่ใช่ to — 'comply to' ผิด collocation ต้องเป็น 'comply with' (ค) (ก) All staff must = ถูก (ข) comply = ถูก (ง) immediately = ถูกเสมอ", "shortcut": "comply **with** · depend **on** · apply **for** · responsible **for** — คู่บุพบทต้องจำ", "study_ref": "english-error-identification", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0001", "subject": "english", "topic": "reading", "subtopic": "main_idea", "difficulty": 1, "stem": "Read the passage:\n\n\"The annual staff meeting of the Finance Division will be held on 28 November 2026 at 9:30 a.m. in Meeting Room 3. All staff members are required to attend. Those who cannot attend must notify their supervisor in writing by 20 November.\"\n\nWhat is the main purpose of the notice?", "figure_svg": null, "choices": ["To cancel the meeting", "To inform staff about the upcoming meeting", "To recruit new staff", "To announce a budget cut"], "answer": 1, "explanation": "ทั้งประกาศพูดถึงการประชุมประจำปี วัน เวลา สถานที่ และเงื่อนไขการเข้าร่วม → วัตถุประสงค์คือแจ้งให้ทราบเรื่องประชุม (ข) (ก) ตรงข้ามกับเนื้อหา (ค)(ง) ไม่มีข้อมูลในเนื้อเรื่อง", "shortcut": "main idea = สิ่งที่ทั้งข้อความพูดร่วมกัน — ตัดข้อที่แคบ/กว้างเกิน และข้อที่ไม่มีในเนื้อเรื่อง", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0002", "subject": "english", "topic": "reading", "subtopic": "detail", "difficulty": 1, "stem": "Read the passage:\n\n\"The annual staff meeting of the Finance Division will be held on 28 November 2026 at 9:30 a.m. in Meeting Room 3. All staff members are required to attend. Those who cannot attend must notify their supervisor in writing by 20 November.\"\n\nWho must inform their supervisor in writing, and by when?", "figure_svg": null, "choices": ["Everyone, by 28 November", "Those who cannot attend, by 20 November", "New staff only, by 1 December", "Supervisors, by 9:30 a.m."], "answer": 1, "explanation": "ข้อความระบุตรง ๆ ว่า 'Those who cannot attend must notify their supervisor in writing by 20 November' → (ข) (ก) ไม่ถูกเพราะคนที่มาได้ไม่ต้องแจ้ง (ค) ไม่ระบุ (ง) ไม่ใช่หน้าที่ของหัวหน้างานตามข้อความ", "shortcut": "ข้อ detail → สแกนคีย์เวิร์ด (who/by when) แล้วอ่านประโยคตรงนั้น", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0003", "subject": "english", "topic": "reading", "subtopic": "inference", "difficulty": 3, "stem": "Read the passage:\n\n\"The annual staff meeting of the Finance Division will be held on 28 November 2026 at 9:30 a.m. in Meeting Room 3. All staff members are required to attend. Those who cannot attend must notify their supervisor in writing by 20 November.\"\n\nWhich of the following can be inferred from the notice?", "figure_svg": null, "choices": ["The meeting is optional for managers.", "Attendance is mandatory unless excused in advance.", "The meeting will be cancelled.", "Only finance staff know the date."], "answer": 1, "explanation": "'required to attend' + 'those who cannot attend must notify… by 20 November' → การเข้าร่วมเป็นข้อบังคับ ยกเว้นแจ้งล่วงหน้า (ข) (ก) ขัดกับ required (ค) ไม่ระบุในเนื้อเรื่อง (ง) ไม่มีหลักฐานในเนื้อเรื่อง", "shortcut": "inference → เลือกข้อที่มี 'ร่องรอยในเนื้อเรื่อง' รองรับ ไม่ใช่ข้อเดาเอง", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0004", "subject": "english", "topic": "reading", "subtopic": "vocab_in_context", "difficulty": 2, "stem": "Read the passage:\n\n\"Dear Team, The project deadline has been moved from 5 to 12 December due to a delay in data submission from the partner agency. Please adjust your work plans accordingly. — Nok\"\n\nThe word \"delay\" most nearly means:", "figure_svg": null, "choices": ["a quick action", "a postponement", "a cancellation", "a celebration"], "answer": 1, "explanation": "บริบท: deadline ถูกขยับจาก 5→12 ธ.ค. เพราะข้อมูลส่งช้า → delay = ความล่าช้า/เลื่อนออกไป (ข) (ก) ตรงข้าม (ค) cancellation = ยกเลิก ไม่ใช่แค่เลื่อน (ง) ไม่เข้าบริบท", "shortcut": "vocab in context → แทนคำด้วยตัวเลือกแต่ละตัวในประโยคเดิม ดูความลื่นไหล", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0005", "subject": "english", "topic": "reading", "subtopic": "email_purpose", "difficulty": 2, "stem": "Read the email:\n\n\"Dear Team, The project deadline has been moved from 5 to 12 December due to a delay in data submission from the partner agency. Please adjust your work plans accordingly and submit the revised timelines to me by this Friday. — Nok\"\n\nWhat does Nok want the team to do?", "figure_svg": null, "choices": ["Cancel the project", "Submit revised timelines by Friday", "Contact the partner agency", "Work overtime"], "answer": 1, "explanation": "ประโยคสั่งตรง: 'submit the revised timelines to me by this Friday' → (ข) (ก)(ค)(ง) ไม่ได้ระบุในอีเมล", "shortcut": "อีเมล → หา 'call to action' — ประโยคที่สั่งให้ทำอะไร คือจุดตอบ", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0006", "subject": "english", "topic": "reading", "subtopic": "not_true", "difficulty": 3, "stem": "Read the passage:\n\n\"Bangkok residents can borrow up to 5 books at a time from district libraries. The loan period is 14 days, renewable once if no one else has reserved the book. A late fee of 5 baht per day applies after the due date.\"\n\nWhich of the following is NOT true?", "figure_svg": null, "choices": ["Borrowers can take 5 books at once.", "Books can be renewed more than once.", "The loan period is two weeks.", "A late fee applies after the due date."], "answer": 1, "explanation": "ข้อความระบุ 'renewable once' (ต่อได้อีกครั้งเดียว) → ต่อได้มากกว่าหนึ่งครั้งเป็นสิ่งที่ไม่จริง (ข) (ก)(ค)(ง) ทุกข้อตรงกับเนื้อหา", "shortcut": "ข้อ NOT true → หาตัวเลข/เงื่อนไขที่ถูก 'ขยายเกินจริง' — ข้อความระบุไว้จำกัดแค่ไหน ห้ามคิดเกิน", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0007", "subject": "english", "topic": "reading", "subtopic": "passage_source", "difficulty": 3, "stem": "Read the passage:\n\n\"All staff are reminded that the cafeteria will be closed for renovation from 1 to 15 December. Temporary food trucks will be provided near Gate 2 during this period. Meal allowances will not be paid during the closure.\"\n\nThis passage is most likely taken from:", "figure_svg": null, "choices": ["a weather report", "a staff announcement", "a novel", "a restaurant review"], "answer": 1, "explanation": "เนื้อเรื่องเน้นแจ้งพนักงาน: โรงอาหารปิด มีรถขายอาหารชั่วคราว งดเบี้ยเลี้ยง → เป็นประกาศภายในสำหรับพนักงาน (ข) (ก)(ค)(ง) ไม่เข้ากับน้ำเสียงและเนื้อหา", "shortcut": "passage source → ดูน้ำเสียงและคำที่ใช้เรียกผู้อ่าน (All staff → ประกาศภายใน)", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0008", "subject": "english", "topic": "reading", "subtopic": "inference_tone", "difficulty": 2, "stem": "Read the passage:\n\n\"Complaints about noise from the construction site have increased sharply since July. Residents report sleep disturbance on weekdays between 6 and 8 a.m. The contractor states that work before 7 a.m. is limited to low-noise tasks.\"\n\nWhat does the passage suggest about the current situation?", "figure_svg": null, "choices": ["Construction has stopped completely.", "Residents and the contractor disagree about the noise level.", "The construction site is closed on weekdays.", "No complaints have been filed."], "answer": 1, "explanation": "ประชาชนร้องเรียนเรื่องเสียง แต่ผู้รับเหมาโต้ว่างานก่อน 7 โมงเช้าเป็นงานเบา → สองฝ่ายมองไม่ตรงกันเรื่องระดับเสียง (ข) (ก)(ค)(ง) ขัดแย้งหรือไม่มีในเนื้อเรื่อง", "shortcut": "อ่านแบบมีจุดขัดแย้งสองฝั่ง → คำตอบ inference มักอยู่ตรงรอยต่อนั้น", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0009", "subject": "english", "topic": "reading", "subtopic": "detail_scan", "difficulty": 2, "stem": "Read the notice:\n\n\"The annual flu vaccination will be offered to all officers on 18 November, 09:00–15:00, in Room 402. Officers with a history of severe allergic reactions must consult a doctor before receiving the vaccine. Bring your staff ID card.\"\n\nWhat must officers with severe allergies do?", "figure_svg": null, "choices": ["Bring two staff ID cards", "Avoid the vaccination entirely", "Consult a doctor before vaccination", "Register online instead"], "answer": 2, "explanation": "ข้อความระบุตรง: 'Officers with a history of severe allergic reactions must consult a doctor before receiving the vaccine' → (ค) (ก) ไม่ระบุ (ข) ข้อความไม่ได้ห้าม แค่ให้ปรึกษาหมอก่อน (ง) ไม่มีข้อมูล", "shortcut": "ข้อ detail หาข้อบังคับตรง ๆ — ห้ามเดาเกินกว่าที่ข้อความระบุ", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S2-READ-0010", "subject": "english", "topic": "reading", "subtopic": "vocabulary_in_context", "difficulty": 3, "stem": "Read the passage:\n\n\"The library will remain closed until further notice while the air-conditioning system is repaired. Members are advised to use the digital lending service, which offers the same catalogue online.\"\n\nIn this passage, \"catalogue\" most nearly means:", "figure_svg": null, "choices": ["a type of furniture", "a list of available items", "a membership fee", "a repair schedule"], "answer": 1, "explanation": "digital lending service ให้ยืมออนไลน์จากรายการหนังสือ — catalogue = รายการที่มีให้ (ข) (ก)(ค)(ง) ไม่เกี่ยวกับบริบทการยืมหนังสือ", "shortcut": "catalogue = รายการสิ่งของ/หนังสือ — ในบริบทห้องสมุด = รายชื่อหนังสือทั้งหมด", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0001", "subject": "analytical", "topic": "quantitative", "subtopic": "percent", "difficulty": 1, "stem": "สินค้าราคา 150 บาท ลดราคา 20% — ราคาขายคือเท่าไร?", "figure_svg": null, "choices": ["120 บาท", "125 บาท", "130 บาท", "135 บาท"], "answer": 0, "explanation": "ส่วนลด = 150 × 20/100 = 30 บาท → ราคาขาย = 150 − 30 = 120 บาท", "shortcut": "20% = 1/5 → 150 ÷ 5 = 30 ลด เหลือ 120", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0002", "subject": "analytical", "topic": "quantitative", "subtopic": "profit_loss", "difficulty": 1, "stem": "ซื้อสินค้ามา 400 บาท ขายกำไร 25% — ได้กำไรกี่บาท?", "figure_svg": null, "choices": ["80 บาท", "100 บาท", "120 บาท", "125 บาท"], "answer": 1, "explanation": "กำไร = ทุน × อัตรากำไร = 400 × 25/100 = 100 บาท (กำไร% คิดจากทุนเสมอ)", "shortcut": "25% = 1/4 → 400 ÷ 4 = 100", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0003", "subject": "analytical", "topic": "quantitative", "subtopic": "percent", "difficulty": 1, "stem": "เงินเดือน 30,000 บาท ได้รับการปรับขึ้น 10% — เงินเดือนใหม่เท่าไร?", "figure_svg": null, "choices": ["31,000 บาท", "32,000 บาท", "33,000 บาท", "34,000 บาท"], "answer": 2, "explanation": "เงินเดือนใหม่ = 30,000 × (1 + 10/100) = 30,000 × 1.1 = 33,000 บาท", "shortcut": "10% ของ 30,000 = 3,000 บวกเข้าไป", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0004", "subject": "analytical", "topic": "quantitative", "subtopic": "percent", "difficulty": 1, "stem": "นักเรียนห้องหนึ่งมี 80 คน เป็นชาย 25% — มีนักเรียนชายกี่คน?", "figure_svg": null, "choices": ["15 คน", "18 คน", "20 คน", "25 คน"], "answer": 2, "explanation": "ชาย = 80 × 25/100 = 20 คน", "shortcut": "25% = 1/4 → 80 ÷ 4 = 20", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0005", "subject": "analytical", "topic": "quantitative", "subtopic": "ratio", "difficulty": 2, "stem": "อัตราส่วนชาย:หญิงในห้อง = 2:3 นักเรียนรวม 250 คน — มีนักเรียนชายกี่คน?", "figure_svg": null, "choices": ["100 คน", "125 คน", "150 คน", "75 คน"], "answer": 0, "explanation": "ชาย = รวม × 2/(2+3) = 250 × 2/5 = 100 คน", "shortcut": "ส่วน = ตัวเอง ÷ ผลรวมอัตราส่วน", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0006", "subject": "analytical", "topic": "quantitative", "subtopic": "percent", "difficulty": 2, "stem": "เสื้อราคา 500 บาท ลด 15% — ราคาที่ต้องจ่ายคือเท่าไร?", "figure_svg": null, "choices": ["425 บาท", "435 บาท", "450 บาท", "475 บาท"], "answer": 0, "explanation": "ส่วนลด = 500 × 15/100 = 75 บาท → จ่าย 500 − 75 = 425 บาท", "shortcut": "15% ของ 500: 10% = 50, 5% = 25 → รวม 75", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0007", "subject": "analytical", "topic": "quantitative", "subtopic": "ratio", "difficulty": 2, "stem": "พ่อแบ่งเงิน 1,200 บาท ให้ ก:ข = 3:1 — ก ได้เงินเท่าไร?", "figure_svg": null, "choices": ["300 บาท", "600 บาท", "900 บาท", "1,000 บาท"], "answer": 2, "explanation": "ก = 1,200 × 3/(3+1) = 1,200 × 3/4 = 900 บาท", "shortcut": "เศษส่วนของอัตราส่วน: 3/4 ของ 1,200", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0008", "subject": "analytical", "topic": "quantitative", "subtopic": "percent_change", "difficulty": 2, "stem": "ค่าโทรศัพท์เดือนนี้สูงขึ้น 10% จากเดิม 200 บาท — ค่าโทรเดือนนี้เท่าไร?", "figure_svg": null, "choices": ["210 บาท", "215 บาท", "220 บาท", "230 บาท"], "answer": 2, "explanation": "ค่าโทรใหม่ = 200 × 1.10 = 220 บาท", "shortcut": "10% ของ 200 = 20 บวกเข้าไป", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0009", "subject": "analytical", "topic": "quantitative", "subtopic": "percent_change", "difficulty": 3, "stem": "ราคาสินค้าราคา 500 บาท เพิ่มขึ้น 20% แล้วลดลง 20% — ราคาสุดท้ายคือเท่าไร?", "figure_svg": null, "choices": ["480 บาท", "500 บาท", "520 บาท", "460 บาท"], "answer": 0, "explanation": "500 × 1.2 = 600 แล้ว 600 × 0.8 = 480 บาท (เพิ่มแล้วลดด้วยอัตราร้อยละเท่ากัน 'ไม่เท่าเดิม') — การเพิ่ม-ลดต้องคูณกัน", "shortcut": "เพิ่มแล้วลดเท่ากัน → เหลือ (1−x²) ของเดิม = 0.96 ของเดิม", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0010", "subject": "analytical", "topic": "quantitative", "subtopic": "fraction", "difficulty": 3, "stem": "โรงเรียนแห่งหนึ่งมีนักเรียน 250 คน บริจาคทรัพย์ 3/5 ของจำนวนนักเรียน — บริจาคกี่คน?", "figure_svg": null, "choices": ["125 คน", "150 คน", "175 คน", "200 คน"], "answer": 1, "explanation": "3/5 ของ 250 = 250 × 3/5 = 150 คน", "shortcut": "3/5 = 0.6 → 250 × 0.6 = 150", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0011", "subject": "analytical", "topic": "quantitative", "subtopic": "work_time", "difficulty": 1, "stem": "A ทำงานเสร็จคนเดียวใน 10 วัน B ทำเสร็จใน 15 วัน — ทั้งคู่ช่วยกันทำเสร็จในกี่วัน?", "figure_svg": null, "choices": ["5 วัน", "6 วัน", "7 วัน", "8 วัน"], "answer": 1, "explanation": "อัตรารวม = 1/10 + 1/15 = 3/30 + 2/30 = 5/30 = 1/6 งาน/วัน → เสร็จใน 6 วัน (สูตร t = a×b/(a+b) = 150/25 = 6)", "shortcut": "t = a×b/(a+b) = 10×15/25 = 6", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0012", "subject": "analytical", "topic": "quantitative", "subtopic": "distance_time", "difficulty": 1, "stem": "รถยนต์วิ่งด้วยความเร็ว 60 กิโลเมตรต่อชั่วโมง ระยะทาง 240 กิโลเมตร — ใช้เวลาเดินทางกี่ชั่วโมง?", "figure_svg": null, "choices": ["3 ชั่วโมง", "4 ชั่วโมง", "5 ชั่วโมง", "6 ชั่วโมง"], "answer": 1, "explanation": "เวลา = ระยะทาง ÷ ความเร็ว = 240 ÷ 60 = 4 ชั่วโมง", "shortcut": "d = s×t → t = d/s", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0013", "subject": "analytical", "topic": "quantitative", "subtopic": "interest", "difficulty": 1, "stem": "เงินฝาก 10,000 บาท ดอกเบี้ยเดี่ยว 5% ต่อปี เป็นเวลา 2 ปี — ได้รับดอกเบี้ยเท่าไร?", "figure_svg": null, "choices": ["500 บาท", "1,000 บาท", "1,500 บาท", "2,000 บาท"], "answer": 1, "explanation": "I = P×r×t = 10,000 × 0.05 × 2 = 1,000 บาท", "shortcut": "5% ต่อปี = 500/ปี ×2 = 1,000", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0014", "subject": "analytical", "topic": "quantitative", "subtopic": "age", "difficulty": 2, "stem": "ปัจจุบันบิดาอายุ 40 ปี บุตรอายุ 10 ปี — อัตราส่วนอายุบิดา:บุตรคือเท่าไร?", "figure_svg": null, "choices": ["2:1", "3:1", "4:1", "5:2"], "answer": 2, "explanation": "40:10 = 4:1 (หารทั้งสองด้วย 10)", "shortcut": "ทอนอัตราส่วนด้วย ห.ร.ม. — 40:10 = 4:1", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0015", "subject": "analytical", "topic": "quantitative", "subtopic": "profit_loss", "difficulty": 2, "stem": "ซื้อสินค้ามา 200 บาท ขายไป 260 บาท — ได้กำไรร้อยละเท่าไร?", "figure_svg": null, "choices": ["20%", "25%", "30%", "35%"], "answer": 2, "explanation": "กำไร = 260 − 200 = 60 บาท กำไร% = 60/200 × 100 = 30%", "shortcut": "กำไร/ทุน×100 = 60/200 = 30%", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0016", "subject": "analytical", "topic": "quantitative", "subtopic": "distance_time", "difficulty": 2, "stem": "เมือง A และ B ห่างกัน 300 กิโลเมตร รถสองคันวิ่งสวนทางกัน ความเร็ว 40 และ 60 กิโลเมตรต่อชั่วโมง — พบกันในกี่ชั่วโมง?", "figure_svg": null, "choices": ["2 ชั่วโมง", "2.5 ชั่วโมง", "3 ชั่วโมง", "4 ชั่วโมง"], "answer": 2, "explanation": "สวนทางกัน ความเร็วสัมพัทธ์ = 40 + 60 = 100 กม./ชม. → เวลาพบกัน = 300/100 = 3 ชั่วโมง", "shortcut": "สวนทาง: บวกความเร็ว · ตามกัน: ลบความเร็ว", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0017", "subject": "analytical", "topic": "quantitative", "subtopic": "mixture", "difficulty": 2, "stem": "น้ำเกลือความเข้มข้น 10% ปริมาณ 500 มิลลิลิตร — มีเกลืออยู่กี่มิลลิลิตร?", "figure_svg": null, "choices": ["40 มล.", "45 มล.", "50 มล.", "55 มล."], "answer": 2, "explanation": "เกลือ = ปริมาณทั้งหมด × ความเข้มข้น = 500 × 10/100 = 50 มิลลิลิตร", "shortcut": "10% ของ 500 = 50", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0018", "subject": "analytical", "topic": "quantitative", "subtopic": "age", "difficulty": 3, "stem": "ปัจจุบันบิดาอายุ 42 ปี บุตรอายุ 12 ปี — อีกกี่ปีบิดาจะมีอายุเป็น 2 เท่าของบุตร?", "figure_svg": null, "choices": ["14 ปี", "16 ปี", "18 ปี", "20 ปี"], "answer": 2, "explanation": "42 + x = 2(12 + x) → 42 + x = 24 + 2x → x = 18 ปี (อีก 18 ปี บิดา 60 บุตร 30 ซึ่ง 60 = 2×30 ✅)", "shortcut": "ตั้งสมการ: อายุบิดา+x = 2(อายุบุตร+x) แล้วแก้หา x", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0019", "subject": "analytical", "topic": "quantitative", "subtopic": "compound_interest", "difficulty": 3, "stem": "เงินฝาก 10,000 บาท ดอกเบี้ยทบต้น 10% ต่อปี นาน 2 ปี — เงินฝากรวมเป็นเท่าไร?", "figure_svg": null, "choices": ["12,000 บาท", "12,100 บาท", "12,200 บาท", "12,500 บาท"], "answer": 1, "explanation": "เงินรวม = P(1+r)^t = 10,000 × 1.1² = 10,000 × 1.21 = 12,100 บาท", "shortcut": "ปี 1: 11,000 · ปี 2: 11,000 × 1.1 = 12,100", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0020", "subject": "analytical", "topic": "quantitative", "subtopic": "work_time", "difficulty": 3, "stem": "A ทำงานเสร็จคนเดียวใน 20 วัน B ทำเสร็จใน 30 วัน — ถ้าทั้งสองช่วยกันทำ จะเสร็จในกี่วัน?", "figure_svg": null, "choices": ["10 วัน", "12 วัน", "14 วัน", "15 วัน"], "answer": 1, "explanation": "อัตรารวม = 1/20 + 1/30 = 3/60 + 2/60 = 5/60 = 1/12 → เสร็จใน 12 วัน", "shortcut": "t = a×b/(a+b) = 20×30/50 = 12", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0021", "subject": "analytical", "topic": "quantitative", "subtopic": "linear_equation", "difficulty": 1, "stem": "2x + 5 = 15 — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["3", "4", "5", "6"], "answer": 2, "explanation": "2x = 15 − 5 = 10 → x = 5", "shortcut": "ลบ 5 ก่อน แล้วหาร 2", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0022", "subject": "analytical", "topic": "quantitative", "subtopic": "linear_equation", "difficulty": 1, "stem": "3x − 7 = 11 — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["4", "5", "6", "7"], "answer": 2, "explanation": "3x = 11 + 7 = 18 → x = 6", "shortcut": "บวก 7 ย้ายข้างก่อน", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0023", "subject": "analytical", "topic": "quantitative", "subtopic": "linear_equation", "difficulty": 2, "stem": "5x + 2 = 3x + 18 — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["6", "7", "8", "10"], "answer": 2, "explanation": "5x − 3x = 18 − 2 → 2x = 16 → x = 8", "shortcut": "รวมตัวแปรข้างเดียว เลขอีกข้าง", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0024", "subject": "analytical", "topic": "quantitative", "subtopic": "quadratic", "difficulty": 2, "stem": "x² − 5x + 6 = 0 — ผลคูณของรากทั้งสองเท่ากับข้อใด?", "figure_svg": null, "choices": ["−6", "5", "6", "1"], "answer": 2, "explanation": "สำหรับ x² + bx + c = 0 ผลคูณราก = c = 6 (แยกตัวประกอบได้ (x−2)(x−3)=0 → 2×3=6)", "shortcut": "ผลคูณราก = c ของ x²+bx+c", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0025", "subject": "analytical", "topic": "quantitative", "subtopic": "inequality", "difficulty": 2, "stem": "2x + 3 > 11 — ช่วงคำตอบคือข้อใด?", "figure_svg": null, "choices": ["x > 2", "x > 3", "x > 4", "x > 5"], "answer": 2, "explanation": "2x > 8 → x > 4", "shortcut": "ลบ 3 แล้วหาร 2 — ไม่ต้องกลับเครื่องหมาย (หารด้วยบวก)", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0026", "subject": "analytical", "topic": "quantitative", "subtopic": "linear_equation", "difficulty": 2, "stem": "4(x − 2) = 8 — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["2", "3", "4", "6"], "answer": 2, "explanation": "x − 2 = 8/4 = 2 → x = 4", "shortcut": "หาร 4 ก่อน แล้วค่อยบวก 2", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0027", "subject": "analytical", "topic": "quantitative", "subtopic": "system_equations", "difficulty": 2, "stem": "x + y = 10 และ x − y = 2 — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["4", "5", "6", "8"], "answer": 2, "explanation": "บวกสองสมการ: 2x = 12 → x = 6 (ตรวจ: y = 4, 4+6=10 ✅ 6−4=2 ✅)", "shortcut": "ระบบบวกลบ: บวกสมการแล้วหาร 2", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0028", "subject": "analytical", "topic": "quantitative", "subtopic": "linear_equation", "difficulty": 3, "stem": "x เป็นครึ่งหนึ่งของ y และ x + y = 12 — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["2", "4", "6", "8"], "answer": 1, "explanation": "x = y/2 → y/2 + y = 12 → 3y/2 = 12 → y = 8 → x = 4", "shortcut": "แทน x = y/2 ลงสมการ x+y=12 แล้วแก้", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0029", "subject": "analytical", "topic": "quantitative", "subtopic": "quadratic", "difficulty": 3, "stem": "2x² = 50 (x เป็นจำนวนบวก) — ค่า x เท่ากับข้อใด?", "figure_svg": null, "choices": ["5", "10", "25", "7"], "answer": 0, "explanation": "x² = 25 → x = ±5 แต่ x เป็นจำนวนบวก → x = 5", "shortcut": "หาร 2 ก่อน แล้วถอดราก (ระวังเครื่องหมาย)", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0030", "subject": "analytical", "topic": "quantitative", "subtopic": "two_points_line", "difficulty": 3, "stem": "เส้นตรงผ่านจุด (0, 2) และ (2, 6) — เมื่อ x = 4 ค่า y เท่ากับข้อใด?", "figure_svg": null, "choices": ["8", "9", "10", "12"], "answer": 2, "explanation": "ความชัน = (6−2)/(2−0) = 2 → สมการ y = 2x + 2 → x = 4: y = 10", "shortcut": "หาความชันก่อน แล้วแทนจุดที่รู้ หาสมการ", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0031", "subject": "analytical", "topic": "quantitative", "subtopic": "counting_principle", "difficulty": 1, "stem": "เสื้อมี 4 สี กางเกงมี 3 แบบ — แต่งตัวได้กี่ชุด?", "figure_svg": null, "choices": ["7 ชุด", "12 ชุด", "16 ชุด", "24 ชุด"], "answer": 1, "explanation": "หลักการคูณ: 4 × 3 = 12 ชุด", "shortcut": "เลือก 2 ขั้นตอนอิสระ → คูณ", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0032", "subject": "analytical", "topic": "quantitative", "subtopic": "probability", "difficulty": 1, "stem": "ลูกเต๋า 1 ลูก หงายแต้ม 6 — ความน่าจะเป็นเท่ากับข้อใด?", "figure_svg": null, "choices": ["1/3", "1/6", "1/2", "6/6"], "answer": 1, "explanation": "หน้าเต๋ามี 6 หน้า เท่า ๆ กัน → P(แต้ม 6) = 1/6", "shortcut": "หน้าเต๋า 6 หน้า แต่ละหน้า 1/6", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0033", "subject": "analytical", "topic": "quantitative", "subtopic": "probability", "difficulty": 2, "stem": "โยนเหรียญ 2 เหรียญ — ความน่าจะเป็นที่หงายหัวทั้งคู่คือข้อใด?", "figure_svg": null, "choices": ["1/2", "1/3", "1/4", "1/8"], "answer": 2, "explanation": "ผลลัพธ์ทั้งหมด HH, HT, TH, TT = 4 แบบ → P(HH) = 1/4", "shortcut": "เหตุการณ์อิสระ 2 ขั้น → 1/2 × 1/2 = 1/4", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0034", "subject": "analytical", "topic": "quantitative", "subtopic": "permutation", "difficulty": 2, "stem": "นักเรียน 5 คน เข้าแถวเรียงลำดับ — มีกี่วิธี?", "figure_svg": null, "choices": ["25", "60", "120", "720"], "answer": 2, "explanation": "เรียง 5 คน ซึ่งคำนึงลำดับ: 5! = 5×4×3×2×1 = 120 วิธี", "shortcut": "n! สำหรับเรียงครบทุกตัว", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0035", "subject": "analytical", "topic": "quantitative", "subtopic": "combination", "difficulty": 2, "stem": "เลือกคณะกรรมการ 2 คน จากสมาชิก 6 คน — มีกี่วิธี? (ไม่คำนึงตำแหน่ง)", "figure_svg": null, "choices": ["12 วิธี", "15 วิธี", "30 วิธี", "36 วิธี"], "answer": 1, "explanation": "C(6,2) = 6!/(2!×4!) = (6×5)/2 = 15 วิธี", "shortcut": "C(6,2) = 6×5/2 = 15", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0036", "subject": "analytical", "topic": "quantitative", "subtopic": "probability", "difficulty": 2, "stem": "ลูกเต๋า 1 ลูก หงายแต้มตั้งแต่ 5 ขึ้นไป — ความน่าจะเป็นคือข้อใด?", "figure_svg": null, "choices": ["1/6", "1/3", "1/2", "2/3"], "answer": 1, "explanation": "แต้ม ≥ 5 คือ 5 และ 6 = 2 หน้าจาก 6 หน้า → 2/6 = 1/3", "shortcut": "นับเหตุการณ์ที่ต้องการ ÷ ทั้งหมด", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0037", "subject": "analytical", "topic": "quantitative", "subtopic": "permutation", "difficulty": 3, "stem": "จากนักเรียน 8 คน เลือกประธาน 1 คน รองประธาน 1 คน — มีกี่วิธี?", "figure_svg": null, "choices": ["28 วิธี", "56 วิธี", "64 วิธี", "72 วิธี"], "answer": 1, "explanation": "เลือกประธาน 8 วิธี รองประธาน 7 วิธี ซึ่งตำแหน่งต่างกัน (คำนึงลำดับ) → P(8,2) = 8×7 = 56 วิธี", "shortcut": "ตำแหน่งต่างกัน → คำนึงลำดับ → คูณ 8×7", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0038", "subject": "analytical", "topic": "quantitative", "subtopic": "probability", "difficulty": 3, "stem": "โยนเหรียญ 3 เหรียญพร้อมกัน — ความน่าจะเป็นที่ไม่หงายหัวเลยคือข้อใด?", "figure_svg": null, "choices": ["1/4", "1/8", "3/8", "7/8"], "answer": 1, "explanation": "ไม่หงายหัวเลย = หงายก้อยทั้ง 3 เหรียญ → 1 วิธีจาก 2×2×2 = 8 วิธี → 1/8", "shortcut": "ทางที่ต้องการเพียงทางเดียว (TTT) ÷ ทั้งหมด 8", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0039", "subject": "analytical", "topic": "quantitative", "subtopic": "counting_principle", "difficulty": 1, "stem": "ร้านขายไอศกรีมมี 2 รสชาติและ 3 ท็อปปิง — เลือกรสและท็อปปิงได้กี่แบบ?", "figure_svg": null, "choices": ["5 แบบ", "6 แบบ", "8 แบบ", "9 แบบ"], "answer": 1, "explanation": "หลักการคูณ: 2 × 3 = 6 แบบ", "shortcut": "เลือกอิสระ 2 ขั้น → คูณ", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0040", "subject": "analytical", "topic": "quantitative", "subtopic": "combination", "difficulty": 3, "stem": "เลือกคณะกรรมการ 3 คน จากสมาชิก 7 คน — มีกี่วิธี?", "figure_svg": null, "choices": ["21 วิธี", "30 วิธี", "35 วิธี", "42 วิธี"], "answer": 2, "explanation": "C(7,3) = 7!/(3!×4!) = (7×6×5)/6 = 35 วิธี", "shortcut": "C(7,3) = 7×6×5/(3×2×1) = 35", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0041", "subject": "analytical", "topic": "quantitative", "subtopic": "table_reading", "difficulty": 1, "stem": "ตารางยอดขายสินค้า (หน่วย: ชิ้น) อาทิตย์นี้ — วันใดขายได้มากที่สุด?\nจันทร์ 20 · อังคาร 35 · พุธ 25 · พฤหัส 40 · ศุกร์ 30", "figure_svg": null, "choices": ["วันจันทร์", "วันอังคาร", "วันพุธ", "วันพฤหัสบดี"], "answer": 3, "explanation": "เทียบค่าในตาราง: 20, 35, 25, 40, 30 — สูงสุดคือ 40 ชิ้น วันพฤหัสบดี", "shortcut": "สแกนหาค่าสูงสุดในแถวเดียว (อย่าคำนวณ)", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0042", "subject": "analytical", "topic": "quantitative", "subtopic": "table_reading", "difficulty": 1, "stem": "จากตารางเดียวกัน (จ 20, อ 35, พ 25, พฤ 40, ศ 30 ชิ้น) — ยอดขายรวมทั้งสัปดาห์คือเท่าไร?", "figure_svg": null, "choices": ["140 ชิ้น", "150 ชิ้น", "160 ชิ้น", "170 ชิ้น"], "answer": 1, "explanation": "20 + 35 + 25 + 40 + 30 = 150 ชิ้น", "shortcut": "บวกไล่ทีละค่า — อย่าข้ามบรรทัด", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0043", "subject": "analytical", "topic": "quantitative", "subtopic": "percent_change", "difficulty": 2, "stem": "จากตารางเดียวกัน — ยอดขายวันอังคารเพิ่มขึ้นกี่เปอร์เซ็นต์เมื่อเทียบกับวันจันทร์?", "figure_svg": null, "choices": ["50%", "60%", "75%", "175%"], "answer": 2, "explanation": "(35 − 20)/20 × 100 = 15/20 = 75%", "shortcut": "ส่วนต่าง 15 จากฐาน 20 = 75%", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0044", "subject": "analytical", "topic": "quantitative", "subtopic": "table_reading", "difficulty": 2, "stem": "จากตารางเดียวกัน — ยอดขายเฉลี่ยต่อวันคือเท่าไร?", "figure_svg": null, "choices": ["25 ชิ้น", "28 ชิ้น", "30 ชิ้น", "32 ชิ้น"], "answer": 2, "explanation": "รวม 150 ÷ 5 วัน = 30 ชิ้น/วัน", "shortcut": "ใช้ผลรวมจากข้อก่อนหน้า ÷ จำนวนวัน", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0045", "subject": "analytical", "topic": "quantitative", "subtopic": "table_reading", "difficulty": 1, "stem": "ค่ายพักแรมมีผู้เข้าพัก เด็ก 120 คน ผู้ใหญ่ 180 คน — ร้อยละของเด็กต่อผู้เข้าพักทั้งหมดคือเท่าไร?", "figure_svg": null, "choices": ["20%", "30%", "40%", "50%"], "answer": 2, "explanation": "เด็ก 120 จากทั้งหมด 300 คน → 120/300 × 100 = 40%", "shortcut": "120/300 = 0.4 = 40%", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0046", "subject": "analytical", "topic": "quantitative", "subtopic": "pie_chart", "difficulty": 2, "stem": "บริษัทยอดขายทั้งปี 240,000 บาท กราฟวงกลมระบุว่าภาค ก.พ. (กุมภาพันธ์) มีสัดส่วน 25% — ยอดขายเดือน ก.พ. คือเท่าไร?", "figure_svg": null, "choices": ["50,000 บาท", "60,000 บาท", "70,000 บาท", "80,000 บาท"], "answer": 1, "explanation": "25% ของ 240,000 = 240,000 × 0.25 = 60,000 บาท", "shortcut": "25% = 1/4 → หาร 4", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0047", "subject": "analytical", "topic": "quantitative", "subtopic": "bar_chart", "difficulty": 2, "stem": "ปริมาณน้ำฝน (มม.) มิถุนายน 150 · กรกฎาคม 200 — รวมสองเดือนคือเท่าไร?", "figure_svg": null, "choices": ["300 มม.", "325 มม.", "350 มม.", "400 มม."], "answer": 2, "explanation": "150 + 200 = 350 มม.", "shortcut": "อ่านค่าสองแท่งแล้วบวกตรง ๆ", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0048", "subject": "analytical", "topic": "quantitative", "subtopic": "fraction_compare", "difficulty": 3, "stem": "ที่ดิน 500 ไร่ ชาวนาปลูกข้าว 3/5 ของที่ดินทั้งหมด — ปลูกข้าวกี่ไร่?", "figure_svg": null, "choices": ["250 ไร่", "280 ไร่", "300 ไร่", "320 ไร่"], "answer": 2, "explanation": "3/5 ของ 500 = 500 × 3/5 = 300 ไร่", "shortcut": "500 ÷ 5 = 100 × 3 = 300", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0049", "subject": "analytical", "topic": "quantitative", "subtopic": "average", "difficulty": 3, "stem": "คะแนนสอบของนักเรียน 5 คน: 60, 70, 80, 90, 100 — คะแนนเฉลี่ยคือเท่าไร?", "figure_svg": null, "choices": ["70", "75", "80", "85"], "answer": 2, "explanation": "(60+70+80+90+100)/5 = 400/5 = 80 คะแนน", "shortcut": "ค่ากลางของลำดับสมมาตร = ค่ากลาง", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}, {"id": "S1-QUAN-0050", "subject": "analytical", "topic": "quantitative", "subtopic": "pie_chart", "difficulty": 2, "stem": "โรงงานผลิตสินค้า 2,000 ชิ้น แยกตามแผนก: แผนก A 45% — แผนก A ผลิตได้กี่ชิ้น?", "figure_svg": null, "choices": ["800 ชิ้น", "850 ชิ้น", "900 ชิ้น", "950 ชิ้น"], "answer": 2, "explanation": "45% ของ 2,000 = 2,000 × 0.45 = 900 ชิ้น", "shortcut": "45% = 50% − 5% → 1,000 − 100 = 900", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original"}];
window.MOCK_SETS = [[{"id": "S1-LANG-0051", "subject": "analytical", "topic": "language", "subtopic": "main_idea", "difficulty": 2, "stem": "ข้อความใดเป็นใจความสำคัญของบทความต่อไปนี้:\n\n\"หลายคนมองว่าการนอนหลับเป็นเวลาตายตัว แต่แพทย์เตือนว่าการนอนหลับไม่พอเรื้อรังส่งผลต่อความจำ อารมณ์ และภูมิคุ้มกัน แม้จะไม่ป่วยทันทีก็ตาม การจัดเวลานอนให้เป็นเวลาจึงสำคัญเท่ากับการออกกำลังกาย\"", "figure_svg": null, "choices": ["การนอนหลับไม่สำคัญพอ ๆ กับการออกกำลังกาย", "โรคภูมิคุ้มกันเกิดจากการนอนน้อยเท่านั้น", "ทุกคนต้องนอน 8 ชั่วโมงเท่านั้น", "การนอนหลับไม่พอเรื้อรังส่งผลเสียหลายด้าน การจัดเวลานอนเป็นสิ่งสำคัญ"], "answer": 3, "explanation": "บทความพูดถึงผลเสียของการนอนไม่พอและข้อเสนอให้จัดเวลานอน (ง) ถูกต้อง (ก) ไม่ตรง (ค) ไม่มีในเนื้อเรื่อง (ข) เกินจริง เป็นเพียงผลหนึ่งของการนอนน้อย", "shortcut": "ใจความสำคัญมักอยู่ประโยคต้น/ท้ายหรือประโยคที่รวมความทุกส่วน", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0052", "subject": "analytical", "topic": "language", "subtopic": "detail", "difficulty": 1, "stem": "\"งานสัมมนารอบนี้จัดขึ้นในวันที่ 12 ธันวาคม 2569 เวลา 09.00–12.00 น. ณ หอประชุมอาคาร A ผู้เข้าร่วมต้องลงทะเบียนล่วงหน้าภายในวันที่ 5 ธันวาคม\"\n\nข้อใดถูกต้อง?", "figure_svg": null, "choices": ["สัมมนาจัดวันที่ 5 ธันวาคม", "สัมมนาจัด ณ หอประชุมอาคาร B", "สัมมนามีเวลา 6 ชั่วโมง", "ผู้เข้าร่วมต้องลงทะเบียนภายใน 5 ธันวาคม"], "answer": 3, "explanation": "ข้อความระบุตรง ๆ ว่าต้องลงทะเบียนภายใน 5 ธันวาคม (ง) (ก) ไม่ตรง (ค) สัมมนามีเวลา 3 ชั่วโมง (ข) อาคาร A ไม่ใช่ B", "shortcut": "ข้อรายละเอียด → สแกนคีย์เวิร์ด (ใคร เมื่อไหร่ ที่ไหน) โดยตรง", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0053", "subject": "analytical", "topic": "language", "subtopic": "inference", "difficulty": 3, "stem": "\"ยอดขายรถยนต์ไฟฟ้าในไทยเพิ่มขึ้นต่อเนื่องสามปี แม้โครงสร้างพื้นฐานจะยังจำกัด ผู้ผลิตจึงขยายโรงงานในประเทศมากขึ้น\"\n\nข้อใดสรุปได้จากข้อความข้างต้น?", "figure_svg": null, "choices": ["โครงสร้างพื้นฐานเพียงพอแล้ว", "ผู้ผลิตเชื่อมั่นในแนวโน้มตลาดรถยนต์ไฟฟ้า จึงลงทุนเพิ่ม", "รถยนต์ไฟฟ้าขายไม่ออก", "รัฐบาลยกเลิกมาตรการสนับสนุน"], "answer": 1, "explanation": "ยอดขายเพิ่ม + ผู้ผลิตขยายโรงงาน → ผู้ผลิตเชื่อมั่นแนวโน้มตลาด (ข) (ก) ตรงข้ามกับ 'โครงสร้างพื้นฐานยังจำกัด' (ค)(ง) ไม่มีในเนื้อเรื่อง", "shortcut": "อนุมานต้องมีร่องรอยในข้อความเสมอ ห้ามใช้ความรู้รอบตัว", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0054", "subject": "analytical", "topic": "language", "subtopic": "sentence_order", "difficulty": 2, "stem": "เรียงประโยคต่อไปนี้ให้เป็นข้อความที่ถูกต้อง:\n\n1) จึงช่วยลดค่าใช้จ่ายได้มาก\n2) หลายโรงงานหันมาใช้พลังงานแสงอาทิตย์\n3) เพราะต้นทุนแผงโซลาร์เซลล์ลดลงอย่างต่อเนื่อง\n4) ในการผลิตสินค้า", "figure_svg": null, "choices": ["2-3-4-1", "3-2-1-4", "2-4-1-3", "3-2-4-1"], "answer": 3, "explanation": "เหตุผลต้นเหตุ: (3) ต้นทุนลดลง เป็นเหตุ → (2) หลายโรงงานหันมาใช้ → (4) ในการผลิตสินค้า (ขยาย) → (1) ผล: จึงช่วยลดค่าใช้จ่าย → 3-2-4-1 (ง) ตัวเลือกอื่นเรียงเหตุ-ผลผิดลำดับ", "shortcut": "หาเหตุ (เพราะ…) วางไว้ต้น ผล (จึง…) วางไว้ท้าย — เชื่อมด้วยคำเชื่อม", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0055", "subject": "analytical", "topic": "language", "subtopic": "sentence_order", "difficulty": 3, "stem": "เรียงประโยคต่อไปนี้ให้เป็นบทความที่สมบูรณ์:\n\n1) แต่ผลลัพธ์ระยะยาวอยู่ที่คุณภาพของการพัฒนาคน\n2) การลงทุนโครงสร้างพื้นฐานสร้างการเติบโตได้เร็ว\n3) จึงต้องควบคู่กับการพัฒนาคุณภาพการศึกษา\n4) ทั้งสองด้านต้องสมดุลกันจึงจะยั่งยืน", "figure_svg": null, "choices": ["2-1-3-4", "4-2-1-3", "2-3-1-4", "1-2-4-3"], "answer": 0, "explanation": "เปิดด้วยประเด็นหลัก (2) การลงทุนโครงสร้างพื้นฐาน → (1) แต่ ผลยาวอยู่ที่คน → (3) จึง ต้องควบคู่การศึกษา → (4) สรุป สมดุลทั้งสองด้าน → 2-1-3-4 (ก) ตัวเลือกอื่นไม่มีโครง เหตุ→กลับ→สรุป ที่ต่อเนื่อง", "shortcut": "หากลุ่ม 'เปิด' (ประเด็นหลัก), กลุ่ม 'แต่' (ย้อน/ขัด), กลุ่ม 'จึง' (ผล), กลุ่ม 'สรุป' (สุดท้าย)", "study_ref": "analytical-language-sentence-order", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0056", "subject": "analytical", "topic": "language", "subtopic": "word_usage", "difficulty": 2, "stem": "ข้อใดใช้คำผิดความหมาย?", "figure_svg": null, "choices": ["เขาอนุมัติให้เลื่อนการประชุมออกไปหนึ่งสัปดาห์", "เธอสมัครใจลาออกเองโดยไม่มีใครบังคับ", "ผู้จัดการสั่งให้เขาลาออกทันที", "นักเรียนลงทะเบียนเรียนภาคเรียนนี้ 5 วิชา"], "answer": 2, "explanation": "'ลาออก' คือการกระทำด้วยความสมัครใจของเจ้าตัว จึงถูก 'สั่ง' ให้ทำไม่ได้ — ถ้าผู้บังคับบัญชาต้องการให้พ้นตำแหน่ง ต้องใช้คำว่า 'เลิกจ้าง' 'ไล่ออก' หรือ 'ปลดออก' ข้อ (ค) จึงใช้คำผิดความหมาย (ก) อนุมัติถูกต้อง (ข) สมัครใจลาออก ถูกต้อง (ง) ลงทะเบียน ถูกต้อง", "shortcut": "ลาออก = สมัครใจ · ปลด/เลิกจ้าง = นายจ้างกระทำ — คำกริยาสองมิตินี้ห้ามปน", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0057", "subject": "analytical", "topic": "language", "subtopic": "idiom", "difficulty": 2, "stem": "สำนวน 'น้ำขึ้นให้รีบตัก' มีความหมายว่าอย่างไร?", "figure_svg": null, "choices": ["พอมีโอกาสดีต้องรีบคว้าไว้", "ทำงานให้เสร็จก่อนเวลา", "ใช้เงินให้คุ้มค่าที่สุด", "ประหยัดน้ำไว้ใช้ยามจำเป็น"], "answer": 0, "explanation": "'น้ำขึ้นให้รีบตัก' = มีโอกาสดีเข้ามาควรรีบทำ เพราะโอกาสไม่ได้มาบ่อย (ก) (ข) ไม่ใช่ความหมายของสำนวนนี้ (ค)(ง) ไม่ตรง", "shortcut": "สำนวน = ภาพรวมของสุภาษิต ไม่แปลตรงตัวอักษร", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0058", "subject": "analytical", "topic": "language", "subtopic": "verbal_analogy", "difficulty": 2, "stem": "แพทย์ : คนไข้ :: ครู : ______", "figure_svg": null, "choices": ["โรงพยาบาล", "ผู้ปกครอง", "ตำรา", "นักเรียน"], "answer": 3, "explanation": "ความสัมพันธ์คือ 'ผู้ให้บริการ → ผู้รับบริการ': แพทย์รักษาคนไข้ ครูสอนนักเรียน (ง) (ก) ที่ทำงาน ไม่ใช่ผู้รับบริการ (ค) เครื่องมือ/สื่อ (ข) ไม่เกี่ยวโดยตรง", "shortcut": "หาความสัมพันธ์ก่อน: วิชาชีพ → ผู้รับบริการ", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0059", "subject": "analytical", "topic": "language", "subtopic": "condition_language", "difficulty": 3, "stem": "\"พนักงานที่มาสายเกิน 3 ครั้งในหนึ่งเดือนจะไม่ได้รับเงินรางวัลประจำเดือน\" ข้อใดอนุมานได้จากเงื่อนไขนี้?", "figure_svg": null, "choices": ["มาสาย 2 ครั้ง รับรางวัลไม่ได้", "มาสาย 3 ครั้งพอดี รับรางวัลได้", "มาสาย 4 ครั้ง รับรางวัลไม่ได้", "มาสายเท่าไหร่ก็ไม่เกี่ยวกับรางวัล"], "answer": 2, "explanation": "เงื่อนไข: มาสาย 'เกิน 3 ครั้ง' (คือ ≥4) → ไม่ได้รางวัล → 4 ครั้ง ไม่ได้ (ค) (ก) 2 ครั้ง < 3 ยังได้ (ข) 3 ครั้งพอดี ไม่ใช่ 'เกิน' ยังได้ (ง) ขัดเงื่อนไขผล", "shortcut": "อ่าน 'เกิน/มากกว่า/อย่างน้อย/ไม่เกิน' ให้ละเอียด — ขอบใช้ได้หรือไม่ใช้ได้", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0060", "subject": "analytical", "topic": "language", "subtopic": "grammar_usage", "difficulty": 1, "stem": "ข้อใดเขียนถูกต้องตามหลักภาษาไทย?", "figure_svg": null, "choices": ["เขาไม่ได้มาเพราะเขาป่วย", "จึงเขาไม่ได้มาเพราะเขาป่วย", "เขาไม่ได้มาเพราะว่าเพราะเขาป่วย", "เพราะเขาป่วยจึงเขาไม่ได้มา"], "answer": 0, "explanation": "(ก) ประโยคเหตุ-ผลเรียงถูก: ผลก่อน แล้วตามด้วยเหตุ เชื่อมด้วย 'เพราะ' ถูกต้อง (ข) 'จึง' นำหน้าประโยคไม่ได้ (มีจึงต้องอยู่หลังข้อความที่เป็นผล) (ค) ซ้อนคำเชื่อม 'เพราะว่าเพราะ' ผิด (ง) 'จึงเขาไม่ได้มา' — จึงไม่ควรขึ้นต้นวลีเหตุ ต้องอยู่หลัง clause ที่เป็นผล โครงสร้างผิด", "shortcut": "ประโยคไทยสมบูรณ์ = ประธาน + กริยา + คำเชื่อมเหตุ-ผล ที่ไม่ซ้อน", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0061", "subject": "analytical", "topic": "language", "subtopic": "paragraph_completion", "difficulty": 3, "stem": "\"การศึกษาในยุคดิจิทัลไม่ใช่การจดจำข้อมูล แต่คือการเรียนรู้ที่จะเรียนรู้ ______ นักเรียนที่ปรับตัวได้จึงมีโอกาสประสบความสำเร็จมากกว่า\" ข้อใดเติมช่องว่างได้เหมาะสมที่สุด?", "figure_svg": null, "choices": ["เพราะเทคโนโลยีราคาถูกลง", "ข้อมูลหาง่ายแต่ผู้ที่รู้วิธีวิเคราะห์จะใช้ประโยชน์ได้", "เนื่องจากครูมีเวลาสอนมากขึ้น", "เพราะทุกโรงเรียนมีคอมพิวเตอร์ครบ"], "answer": 1, "explanation": "ช่องว่างต้องเป็น 'เหตุผล' ที่สอดคล้องกับประเด็นว่า 'การเรียนรู้ที่จะเรียนรู้สำคัญกว่าการจดจำ' — (ข) ข้อมูลหาง่าย แต่ผู้วิเคราะห์ได้คือผู้ได้เปรียบ สอดคล้องเต็มที่ (ก)(ค)(ง) ไม่เกี่ยวกับประเด็นหลักหรือเป็นจริงบางส่วนแต่ไม่ต่อเนื่อง", "shortcut": "เติมช่องว่าง → ดูธีมทั้งย่อหน้า = เรียนรู้ที่จะเรียนรู้ → เลือกเหตุผลที่เสริมธีมเดียวกัน", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0062", "subject": "analytical", "topic": "language", "subtopic": "summary", "difficulty": 1, "stem": "ข้อใดสรุปใจความของประโยคนี้ได้ถูกต้องที่สุด: \"แม้จะมีอุปสรรคมากมาย โครงการก็ยังคงเดินหน้าต่อไปได้\"", "figure_svg": null, "choices": ["โครงการถูกยกเลิกเพราะอุปสรรค", "โครงการชะลอไว้ก่อน", "โครงการไม่มีอุปสรรคใด ๆ", "โครงการยังดำเนินต่อ แม้มีอุปสรรค"], "answer": 3, "explanation": "ประโยคบอก 'แม้…อุปสรรค…ยังเดินหน้า' = ดำเนินต่อไปได้ (ง) (ก)(ค)(ข) ขัดแย้งหรือไม่ปรากฏ", "shortcut": "'แม้…ก็…' = ขัดแย้งแต่ยังเกิด — จับแก่นตรง 'ก็'", "study_ref": "analytical-language-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0063", "subject": "analytical", "topic": "language", "subtopic": "vocab_context", "difficulty": 1, "stem": "\"นโยบายนี้เอื้อประโยชน์ต่อผู้ประกอบการรายย่อยเป็นอย่างมาก\" คำว่า 'เอื้อ' ในบริบทนี้หมายความว่า?", "figure_svg": null, "choices": ["ขัดขวาง", "ช่วยเหลือ/อำนวย", "วิจารณ์", "ยกเลิก"], "answer": 1, "explanation": "'เอื้อ' = อำนวย/ช่วยให้เกิด (เอื้อประโยชน์ = ให้ได้รับประโยชน์) (ข) (ก)(ค)(ง) ตรงข้ามหรือไม่ตรงความหมาย", "shortcut": "เอื้อ = อำนวย — 'เอื้อเฟื้อ' ก็แปลว่าช่วยเหลือ", "study_ref": "analytical-language-word-usage", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0064", "subject": "analytical", "topic": "language", "subtopic": "idiom_proverb", "difficulty": 1, "stem": "สำนวน 'เข้าเมืองตาหลิ่ว ต้องหลิ่วตาตาม' สื่อถึงอะไร?", "figure_svg": null, "choices": ["เปลี่ยนร่างกายให้เข้ากับที่อยู่", "อย่าเชื่ออะไรง่าย ๆ", "ออกไปพบคนแปลกหน้าเสมอ", "ปรับตัวให้เข้ากับจารีตของท้องถิ่น"], "answer": 3, "explanation": "สำนวน = ไปอยู่ที่ไหนต้องทำตามจารีต/ขนบของที่นั่น (ง) (ก) แปลตรงตัวอักษรมั่ว (ค)(ข) ไม่ใช่ความหมายสำนวนนี้", "shortcut": "สำนวน 'เข้าเมือง…' ทั้งหลาย = ปรับตัวตามท้องถิ่น", "study_ref": "analytical-language-analogy", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-LANG-0065", "subject": "analytical", "topic": "language", "subtopic": "logical_condition", "difficulty": 2, "stem": "\"ผู้สมัครต้องผ่านการอบรมเท่านั้นจึงจะมีสิทธิสอบข้อเขียน\" ถ้านายเอมีสิทธิสอบข้อเขียน สรุปได้ว่า?", "figure_svg": null, "choices": ["นายเอผ่านการอบรมแล้ว", "นายเอยังไม่ได้อบรม", "นายเอสอบข้อเขียนไม่ได้", "นายเอไม่สามารถผ่านการอบรม"], "answer": 0, "explanation": "เงื่อนไข: ผ่านอบรม → มีสิทธิสอบ เมื่อรู้ว่า 'นายเอมีสิทธิสอบ' (ผล) อนุมานย้อนกลับได้ว่าต้อง 'ผ่านอบรมแล้ว' (modus ponens กลับด้านในทางตรรกะของสัญญาณ 'เท่านั้นจึงจะ') — (ก) (ข)(ค)(ง) ตรงข้ามเงื่อนไข", "shortcut": "'ต้อง…เท่านั้นจึงจะ…' = ต้องมีสิ่งแรกก่อนเสมอ — มีผล → ต้องผ่านเงื่อนไขแรก", "study_ref": "analytical-language-conditions", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0051", "subject": "analytical", "topic": "abstract", "subtopic": "arithmetic_sequence", "difficulty": 1, "stem": "อนุกรม 4, 9, 14, 19, ... พจน์ถัดไปคือ?", "figure_svg": null, "choices": ["22", "24", "26", "28"], "answer": 1, "explanation": "ผลต่าง: 9-4=5, 14-9=5, 19-14=5 คงที่ (+5) → ถัดไป 19+5 = 24 (ข) (ก)(ค)(ง) ผลต่างไม่ใช่ 5", "shortcut": "ดูผลต่างพจน์ติดกันก่อนเสมอ", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0052", "subject": "analytical", "topic": "abstract", "subtopic": "geometric_sequence", "difficulty": 1, "stem": "อนุกรม 3, 6, 12, 24, ... พจน์ถัดไปคือ?", "figure_svg": null, "choices": ["30", "36", "42", "48"], "answer": 3, "explanation": "อัตราส่วน: 6/3=2, 12/6=2, 24/12=2 คงที่ → พจน์ถัดไป 24×2 = 48 (ง) (ก)(ข)(ค) ผิดอัตราส่วน", "shortcut": "ดูอัตราส่วน (คูณ/หาร) ถ้าผลต่างไม่คงที่", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0053", "subject": "analytical", "topic": "abstract", "subtopic": "second_difference", "difficulty": 2, "stem": "อนุกรม 1, 4, 10, 19, 31, ... พจน์ถัดไปคือ?", "figure_svg": null, "choices": ["46", "44", "48", "50"], "answer": 0, "explanation": "ผลต่างชั้นแรก: 3, 6, 9, 12 (เพิ่มทีละ 3) → ผลต่างถัดไป 15 → 31+15 = 46 (ก) (ข)(ค)(ง) คำนวณผลต่างชั้นสองผิด", "shortcut": "ผลต่างชั้นแรกไม่คงที่ แต่ต่างกันคงที่ → ใช้ผลต่างชั้นสอง", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0054", "subject": "analytical", "topic": "abstract", "subtopic": "linear_growth", "difficulty": 2, "stem": "อนุกรม 2, 3, 5, 8, 12, ... พจน์ถัดไปคือ?", "figure_svg": null, "choices": ["15", "16", "17", "18"], "answer": 2, "explanation": "ผลต่าง: 1, 2, 3, 4 (เพิ่มทีละ 1) → ผลต่างถัดไป 5 → 12+5 = 17 (ค) (ก)(ข)(ง) ใช้ผลต่างผิด step", "shortcut": "ผลต่างโตขึ้นเรื่อย ๆ ทีละ step คงที่ → หา step แล้วบวกต่อ", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0055", "subject": "analytical", "topic": "abstract", "subtopic": "letter_sequence", "difficulty": 2, "stem": "อนุกรมตัวอักษร A, D, G, J, ... ตัวถัดไปคือ?", "figure_svg": null, "choices": ["K", "M", "L", "N"], "answer": 1, "explanation": "ตำแหน่ง: A=1, D=4, G=7, J=10 เพิ่มทีละ 3 → ถัดไป 13 = M (ข) (ก) K=11 (ค) L=12 (ง) N=14", "shortcut": "แปลงตัวอักษรเป็นเลขตำแหน่ง", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0056", "subject": "analytical", "topic": "abstract", "subtopic": "figure_sequence", "difficulty": 2, "stem": "แบบรูปต่อไปนี้เปลี่ยนไปตามลำดับ: วงกลม 1 วง → วงกลม 2 วง → วงกลม 3 วง → ... พจน์ที่ 5 มีวงกลมกี่วง?", "figure_svg": "<svg viewBox='0 0 300 60' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='วงกลมเพิ่มขึ้นทีละหนึ่งวงในแต่ละพจน์'><circle cx='15' cy='30' r='9' fill='none' stroke='currentColor' stroke-width='2'/><circle cx='65' cy='30' r='9' fill='none' stroke='currentColor' stroke-width='2'/><circle cx='85' cy='30' r='9' fill='none' stroke='currentColor' stroke-width='2'/><circle cx='135' cy='30' r='9' fill='none' stroke='currentColor' stroke-width='2'/><circle cx='155' cy='30' r='9' fill='none' stroke='currentColor' stroke-width='2'/><circle cx='175' cy='30' r='9' fill='none' stroke='currentColor' stroke-width='2'/></svg>", "choices": ["4 วง", "5 วง", "6 วง", "7 วง"], "answer": 1, "explanation": "รูปเพิ่มขึ้นทีละ 1 วงตามพจน์: พจน์ที่ 1 = 1 วง, พจน์ที่ 2 = 2 วง, พจน์ที่ 3 = 3 วง → พจน์ที่ n มี n วง ดังนั้นพจน์ที่ 5 = 5 วง (ข) (ค) 6 วง คือพจน์ที่ 6", "shortcut": "นับจำนวนรูปในแต่ละพจน์ตามลำดับ", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0057", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy", "difficulty": 1, "stem": "2 : 6 :: 5 : ?", "figure_svg": null, "choices": ["15", "10", "25", "30"], "answer": 0, "explanation": "ความสัมพันธ์: ตัวหลัง = ตัวหน้า × 3 (2×3=6) → 5×3 = 15 (ก) (ข) ไม่คูณ (ค) ยกกำลังสอง (ง) ×6", "shortcut": "หาความสัมพันธ์จากคู่แรก", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0058", "subject": "analytical", "topic": "abstract", "subtopic": "number_analogy_hard", "difficulty": 3, "stem": "2 : 8 :: 5 : ?", "figure_svg": null, "choices": ["25", "50", "125", "150"], "answer": 2, "explanation": "ความสัมพันธ์: ตัวหลัง = ตัวหน้า³ (2³=8) → 5³ = 125 (ค) (ก) 5²=25 (ข) 5×10=50 (ง) 5×30=150", "shortcut": "คู่ 2:8 คือยกกำลังสาม ไม่ใช่ ×4", "study_ref": "analytical-abstract-analogy", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0059", "subject": "analytical", "topic": "abstract", "subtopic": "syllogism", "difficulty": 2, "stem": "\"ทุกนกมีปีก\" และ \"นกกระจอกเป็นนก\" สรุปได้ว่าข้อใด?", "figure_svg": null, "choices": ["นกกระจอกไม่มีปีก", "นกกระจอกมีปีก", "นกทุกชนิดบินได้", "นกมีกระดูกกลวง"], "answer": 1, "explanation": "ตรรกะแบบสรุปนิรนัย: นกทุกตัวมีปีก (ทุก A เป็น B) + นกกระจอกเป็นนก (C เป็น A) → นกกระจอกมีปีก (C เป็น B) (ข) (ก) ตรงข้าม (ค) ไม่ได้บอกว่าบิน (ง) ไม่มีในเงื่อนไข", "shortcut": "Syllogism: ถ้าทุก A เป็น B และ C เป็น A → C เป็น B เสมอ", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0060", "subject": "analytical", "topic": "abstract", "subtopic": "venn_diagram", "difficulty": 3, "stem": "ในห้องเรียน 30 คน ชอบฟุตบอล 18 คน ชอบบาสเกตบอล 12 คน ชอบทั้งสองอย่าง 5 คน — มีคนที่ชอบอย่างใดอย่างหนึ่ง (ฟุตบอลหรือบาสเกตบอล) กี่คน?", "figure_svg": null, "choices": ["20 คน", "22 คน", "25 คน", "30 คน"], "answer": 2, "explanation": "สูตรยูเนียน: ชอบอย่างใดอย่างหนึ่ง = 18+12−5 = 25 (ค) (ก)(ข) ลบส่วนร่วมผิด (ง) 18+12=30 ไม่นับส่วนซ้ำ", "shortcut": "|A∪B| = |A|+|B|−|A∩B|", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0061", "subject": "analytical", "topic": "abstract", "subtopic": "ordering", "difficulty": 2, "stem": "นักเรียน 4 คน คือ A B C D ยืนเรียงสูงไปต่ำ: A สูงกว่า B, B สูงกว่า C, D สูงกว่า A — เรียงจากสูงไปต่ำได้เป็น?", "figure_svg": null, "choices": ["D, A, B, C", "A, D, B, C", "D, B, A, C", "B, A, D, C"], "answer": 0, "explanation": "ข้อมูล: A>B>C และ D>A → เรียงได้ D>A>B>C (ก) (ข) D ต้องสูงกว่า A (ค)(ง) ผิดลำดับ A>B", "shortcut": "จับคู่ข้อมูลทีละคู่แล้วเชื่อมลำดับ", "study_ref": "analytical-abstract-logic", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0062", "subject": "analytical", "topic": "abstract", "subtopic": "symbol_operation", "difficulty": 2, "stem": "กำหนดให้ a ★ b = a² + b ค่าของ 2 ★ 3 คือ?", "figure_svg": null, "choices": ["7", "9", "10", "13"], "answer": 0, "explanation": "2★3 = 2² + 3 = 4 + 3 = 7 (ก) (ข) ใช้ 2×3+3 (ค) 2²+3² (ง) 2³+3+... ผิด", "shortcut": "แทนค่าตามนิยามสัญลักษณ์ตรง ๆ", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0063", "subject": "analytical", "topic": "abstract", "subtopic": "conditional_logic", "difficulty": 3, "stem": "กำหนด สัญลักษณ์: P = 'ฝนตก', Q = 'ถนนเปียก' และกฎ P → Q (ถ้าฝนตก ถนนเปียก) ถ้าวันนี้ฝนตก สรุปได้ว่า?", "figure_svg": null, "choices": ["ถนนเปียก", "ถนนไม่เปียก", "ฝนไม่ตก", "สรุปไม่ได้"], "answer": 0, "explanation": "modus ponens: P→Q และ P เป็นจริง → Q เป็นจริง ดังนั้นถนนเปียก (ก) (ข)(ค)(ง) ขัดกับกฎที่กำหนด", "shortcut": "P→Q + P → Q (modus ponens)", "study_ref": "analytical-abstract-symbols", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0064", "subject": "analytical", "topic": "abstract", "subtopic": "letter_position", "difficulty": 1, "stem": "ตัวอักษรภาษาอังกฤษ K อยู่ลำดับที่เท่าใด (A=1, B=2, ...)?", "figure_svg": null, "choices": ["10", "11", "12", "13"], "answer": 1, "explanation": "A=1, B=2, C=3, D=4, E=5, F=6, G=7, H=8, I=9, J=10, K=11 (ข) (ก) J (ค) L (ง) M", "shortcut": "นับทีละตัวตัว หรือจำตำแหน่ง J=10, K=11", "study_ref": "analytical-abstract-letter-figure-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-ABST-0065", "subject": "analytical", "topic": "abstract", "subtopic": "triangular_numbers", "difficulty": 1, "stem": "อนุกรม 1, 3, 6, 10, 15, ... พจน์ถัดไปคือ?", "figure_svg": null, "choices": ["18", "20", "21", "22"], "answer": 2, "explanation": "ผลต่าง: 2, 3, 4, 5 (เพิ่มทีละ 1) → ผลต่างถัดไป 6 → 15+6 = 21 (ค) (ก) ไม่ใช้ผลต่างเพิ่มทีละ 1 (ข) 15+5 (ง) 15+7", "shortcut": "ผลต่างโตขึ้นทีละ 1 → พจน์ถัดไป = บวกผลต่างตัวถัดไป", "study_ref": "analytical-abstract-number-sequence", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0051", "subject": "analytical", "topic": "quantitative", "subtopic": "percent_basic", "difficulty": 1, "stem": "20% ของ 350 เท่ากับเท่าไร?", "figure_svg": null, "choices": ["70", "60", "65", "75"], "answer": 0, "explanation": "20/100 × 350 = 0.2 × 350 = 70 (ก) (ข) 15% ของ 400 (ค) ตัวเลขผิด (ง) ผิดการคูณ", "shortcut": "10% = 35 ดังนั้น 20% = 70", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0052", "subject": "analytical", "topic": "quantitative", "subtopic": "ratio_part", "difficulty": 1, "stem": "แบ่งเงิน 360 บาท ให้น้องตามอัตราส่วน 2:3 น้องจะได้เงินส่วนน้อยเท่าไร?", "figure_svg": null, "choices": ["140 บาท", "144 บาท", "150 บาท", "180 บาท"], "answer": 1, "explanation": "อัตราส่วน 2:3 รวม 5 ส่วน → ส่วนน้อย = 360 × 2/5 = 144 บาท (ข) (ก) ปัดผิด (ค) ใช้ผิดส่วน (ง) 360×2.5=180 ไม่ใช่ส่วน 2", "shortcut": "ส่วนน้อย = รวม × ส่วนน้อย/ผลรวมอัตราส่วน", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0053", "subject": "analytical", "topic": "quantitative", "subtopic": "fraction_add", "difficulty": 1, "stem": "2/3 + 1/6 = ?", "figure_svg": null, "choices": ["4/6", "1/2", "1", "5/6"], "answer": 3, "explanation": "ตัวส่วนรวม 6: 2/3 = 4/6, 4/6 + 1/6 = 5/6 (ง) (ก) ลืมบวกตัวเศษครบ (ข)(ค) ผิดการหาตัวส่วนร่วม", "shortcut": "ทำเศษส่วนตัวส่วนเท่ากันก่อนบวก", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0054", "subject": "analytical", "topic": "quantitative", "subtopic": "discount", "difficulty": 2, "stem": "เสื้อราคา 1,250 บาท ลด 20% ต้องจ่ายเท่าไร?", "figure_svg": null, "choices": ["1,050 บาท", "1,100 บาท", "1,150 บาท", "1,000 บาท"], "answer": 3, "explanation": "ส่วนลด = 1,250 × 0.2 = 250 → จ่าย = 1,250 − 250 = 1,000 บาท (ง) (ก)(ข)(ค) หักส่วนลดผิด", "shortcut": "จ่าย 80% = 1,250 × 0.8 = 1,000", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0055", "subject": "analytical", "topic": "quantitative", "subtopic": "profit_percent", "difficulty": 2, "stem": "ผู้ค้าซื้อสินค้ามา 800 บาท ขาย 1,000 บาท ได้กำไรกี่เปอร์เซ็นต์?", "figure_svg": null, "choices": ["25%", "20%", "30%", "22.5%"], "answer": 0, "explanation": "กำไร = 1,000−800 = 200 → กำไร% = 200/800 × 100 = 25% (ก) (ข) ใช้ฐาน 1,000 ผิด — กำไร% คิดจากทุนเสมอ (ค)(ง) ผิดการหาร", "shortcut": "กำไร% = กำไร ÷ ทุน × 100 (ไม่ใช่ ÷ ราคาขาย)", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0056", "subject": "analytical", "topic": "quantitative", "subtopic": "average", "difficulty": 1, "stem": "คะแนนสอบของนักเรียน 4 คน ได้ 60, 70, 80, 90 คะแนน — คะแนนเฉลี่ยเท่าไร?", "figure_svg": null, "choices": ["72.5", "75", "77.5", "80"], "answer": 1, "explanation": "เฉลี่ย = (60+70+80+90)/4 = 300/4 = 75 (ข) (ก) คิด 58/4×5 (ค) 310/4 (ง) ใช้มัธยฐานผิด", "shortcut": "เฉลี่ย = ผลรวม ÷ จำนวน", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0057", "subject": "analytical", "topic": "quantitative", "subtopic": "work_time", "difficulty": 2, "stem": "งานชิ้นนี้ A ทำคนเดียวเสร็จใน 12 วัน B ทำคนเดียวเสร็จใน 24 วัน — ถ้าทำร่วมกันจะเสร็จในกี่วัน?", "figure_svg": null, "choices": ["6 วัน", "10 วัน", "8 วัน", "12 วัน"], "answer": 2, "explanation": "อัตราทำงาน A = 1/12 งาน/วัน, B = 1/24 งาน/วัน → ร่วมกัน = 1/12 + 1/24 = 3/24 = 1/8 → เสร็จใน 8 วัน (ค) (ก)(ง) ผิดการบวกเศษส่วน (ข) ไม่ถูกต้อง", "shortcut": "ร่วมกัน = 1/(1/a + 1/b) = ab/(a+b) = 12×24/36 = 8", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0058", "subject": "analytical", "topic": "quantitative", "subtopic": "simple_interest", "difficulty": 2, "stem": "ฝากเงิน 10,000 บาท อัตราดอกเบี้ย 5% ต่อปี (ดอกเบี้ยอย่างง่าย) เป็นเวลา 3 ปี จะได้ดอกเบี้ยเท่าไร?", "figure_svg": null, "choices": ["1,200 บาท", "1,400 บาท", "1,600 บาท", "1,500 บาท"], "answer": 3, "explanation": "ดอกเบี้ย = ต้น × อัตรา × เวลา = 10,000 × 5/100 × 3 = 1,500 บาท (ง) (ก) คำนวณ 4% (ข) คำนวณผิดปี (ค) คำนวณ 16%", "shortcut": "I = PNR/100 = 10,000×5×3/100 = 1,500", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0059", "subject": "analytical", "topic": "quantitative", "subtopic": "linear_equation", "difficulty": 2, "stem": "ถ้า 3x + 5 = 20 แล้ว x มีค่าเท่าใด?", "figure_svg": null, "choices": ["3", "4", "5", "6"], "answer": 2, "explanation": "3x = 20−5 = 15 → x = 15/3 = 5 (ค) (ก)(ข)(ง) ย้ายข้างหรือหารผิด", "shortcut": "ย้าย 5 ไปลบก่อนแล้วหารด้วย 3", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0060", "subject": "analytical", "topic": "quantitative", "subtopic": "percent_change", "difficulty": 2, "stem": "ราคาสินค้าขึ้นจาก 80 บาท เป็น 100 บาท — เพิ่มขึ้นกี่เปอร์เซ็นต์?", "figure_svg": null, "choices": ["20%", "25%", "30%", "35%"], "answer": 1, "explanation": "เปลี่ยน/ค่าเดิม = (100−80)/80 × 100 = 20/80 × 100 = 25% (ข) (ก) ใช้ 20% ผิดเพราะคิดจากฐานตัวใหม่ (ค)(ง) หารผิด", "shortcut": "%เปลี่ยน = ส่วนที่เปลี่ยน ÷ ค่าเดิม × 100", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0061", "subject": "analytical", "topic": "quantitative", "subtopic": "ratio_word", "difficulty": 2, "stem": "อายุของ A กับ B รวมกัน 45 ปี A อายุเป็น 2 เท่าของ B — A อายุเท่าไร?", "figure_svg": null, "choices": ["15 ปี", "22.5 ปี", "30 ปี", "35 ปี"], "answer": 2, "explanation": "A = 2B, A+B = 45 → 3B = 45 → B = 15, A = 30 ปี (ค) (ก) B's age (ข) หารไม่ลง (ง) ผิด", "shortcut": "2:1 รวม 3 ส่วน → ส่วนละ 15 → A = 30", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0062", "subject": "analytical", "topic": "quantitative", "subtopic": "table_average", "difficulty": 2, "stem": "ตารางยอดขาย: ม.ค. 120 หน่วย, ก.พ. 150 หน่วย, มี.ค. 180 หน่วย — ยอดขายเฉลี่ยต่อเดือนเท่าไร?", "figure_svg": null, "choices": ["150 หน่วย", "140 หน่วย", "160 หน่วย", "165 หน่วย"], "answer": 0, "explanation": "เฉลี่ย = (120+150+180)/3 = 450/3 = 150 (ก) (ข)(ค)(ง) บวกหรือหารผิด", "shortcut": "120+150+180 = 450, ÷3 = 150", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0063", "subject": "analytical", "topic": "quantitative", "subtopic": "percent_twice", "difficulty": 3, "stem": "ราคาสินค้า 500 บาท ขึ้นราคา 10% แล้วภายหลังลดราคา 10% — ราคาสุดท้ายเท่ากับเท่าไร?", "figure_svg": null, "choices": ["450 บาท", "500 บาท", "505 บาท", "495 บาท"], "answer": 3, "explanation": "ขึ้นก่อน: 500×1.1 = 550 → ลด: 550×0.9 = 495 บาท (ง) (ก) เข้าใจผิดว่าลดจากฐานเดิม (ข) คิดว่าขึ้น-ลดหักกันหมด (ค) คูณผิด", "shortcut": "ขึ้นแล้วลดไม่ใช่ศูนย์ — (1.1)(0.9) = 0.99 → ลดลง 1%", "study_ref": "analytical-quantitative-percent", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0064", "subject": "analytical", "topic": "quantitative", "subtopic": "meet_time", "difficulty": 3, "stem": "รถสองคันห่างกัน 300 กิโลเมตร วิ่งเข้าหากัน คันแรก 60 กม./ชม. คันหลัง 90 กม./ชม. — จะพบกันในกี่ชั่วโมง?", "figure_svg": null, "choices": ["1.5 ชม.", "3 ชม.", "2 ชม.", "2.5 ชม."], "answer": 2, "explanation": "ความเร็วสัมพัทธ์เข้าหากัน = 60+90 = 150 กม./ชม. → เวลา = 300/150 = 2 ชม. (ค) (ก)(ข)(ง) หารความเร็วผิด/บวกผิด", "shortcut": "เข้าหากัน → บวกความเร็ว → ระยะ/ผลรวม", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0065", "subject": "analytical", "topic": "quantitative", "subtopic": "quadratic", "difficulty": 3, "stem": "ผลคูณของรากทั้งสองของสมการ x² − 5x + 6 = 0 คือเท่าใด?", "figure_svg": null, "choices": ["6", "5", "-5", "-6"], "answer": 0, "explanation": "ตามสูตร ผลคูณรากของ ax²+bx+c=0 คือ c/a = 6/1 = 6 (ก) (ข) ผลบวกราก (ค)(ง) เครื่องหมายผิด", "shortcut": "ผลบวก = −b/a · ผลคูณ = c/a — ไม่ต้องแก้สมการ", "study_ref": "analytical-quantitative-equations", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0066", "subject": "analytical", "topic": "quantitative", "subtopic": "combination", "difficulty": 3, "stem": "เลือกตัวแทน 3 คน จากนักเรียน 5 คน ได้กี่วิธี?", "figure_svg": null, "choices": ["6 วิธี", "10 วิธี", "20 วิธี", "60 วิธี"], "answer": 1, "explanation": "C(5,3) = 5!/(3!2!) = (5×4)/(2×1) = 10 วิธี (ข) (ก) C(5,4) (ค) เรียงสับเปลี่ยนบางส่วน (ง) P(5,3)", "shortcut": "เลือกไม่เรียงลำดับ → combination = n!/(k!(n−k)!)", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0067", "subject": "analytical", "topic": "quantitative", "subtopic": "probability", "difficulty": 2, "stem": "ทอยลูกเต๋า 1 ลูก 1 ครั้ง โอกาสที่จะออกแต้ม 1 หรือ 6 คือเท่าใด?", "figure_svg": null, "choices": ["1/6", "1/3", "1/2", "2/3"], "answer": 1, "explanation": "แต้ม 1 หรือ 6 มี 2 หน้า จาก 6 หน้า → 2/6 = 1/3 (ข) (ก) หน้าเดียว (ค)(ง) นับผิด", "shortcut": "P(A หรือ B) แยกกัน = บวกหน้าที่เป็นไปได้ / ทั้งหมด", "study_ref": "analytical-quantitative-counting", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0068", "subject": "analytical", "topic": "quantitative", "subtopic": "ratio_word_age", "difficulty": 3, "stem": "พี่กับน้องอายุรวมกัน 40 ปี อัตราส่วนอายุ 5:3 — น้องอายุเท่าไร?", "figure_svg": null, "choices": ["10 ปี", "12 ปี", "15 ปี", "25 ปี"], "answer": 2, "explanation": "5:3 รวม 8 ส่วน → ส่วนละ 40/8 = 5 → น้อง (3 ส่วน) = 15 ปี (ค) (ก)(ข) ใช้ส่วนผิด (ง) เป็นอายุพี่", "shortcut": "หาค่าส่วนละ = รวม ÷ ผลบวกอัตราส่วน", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0069", "subject": "analytical", "topic": "quantitative", "subtopic": "mixture", "difficulty": 1, "stem": "น้ำเกลือ 250 กรัม มีเกลือ 20% มีเกลือหนักกี่กรัม?", "figure_svg": null, "choices": ["20 กรัม", "40 กรัม", "60 กรัม", "50 กรัม"], "answer": 3, "explanation": "20/100 × 250 = 50 กรัม (ง) (ก)(ข)(ค) คูณร้อยละผิด", "shortcut": "20% × 250 = 50", "study_ref": "analytical-quantitative-word-problems", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S1-QUAN-0070", "subject": "analytical", "topic": "quantitative", "subtopic": "compare_quantities", "difficulty": 2, "stem": "ปริมาณ A = 3/5 ของ 250, ปริมาณ B = 40% ของ 300 — ข้อใดถูก?", "figure_svg": null, "choices": ["A < B", "A = B", "A > B", "สรุปไม่ได้"], "answer": 2, "explanation": "A = 3/5 × 250 = 150 · B = 0.4 × 300 = 120 → A > B (ค) (ก)(ข)(ง) คำนวณทีละฝั่งแล้วเทียบ", "shortcut": "คำนวณ A และ B แยกกันก่อนเทียบ", "study_ref": "analytical-quantitative-data", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-CONV-0011", "subject": "english", "topic": "conversation", "subtopic": "phone_request", "difficulty": 1, "stem": "A: Hello, Finance Department. How may I help you?\nB: ______", "figure_svg": null, "choices": ["I want money.", "What time do you close?", "Could I speak to Khun Anan, please?", "No, you can't."], "answer": 2, "explanation": "บริบทโทรศัพท์ทางการ — B ควรขอสายด้วยสำนวนสุภาพ Could I speak to…? (ค) (ก) ตรงและหยาบ (ข) ไม่เข้ากับคำถาม how may I help you (ง) ตอบกลับผิดหน้าที่", "shortcut": "ขอสาย: Could I speak to (ชื่อ), please?", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-CONV-0012", "subject": "english", "topic": "conversation", "subtopic": "office_request", "difficulty": 2, "stem": "A: The projector in Meeting Room 2 is not working.\nB: ______", "figure_svg": null, "choices": ["I'll call IT support right away.", "So what?", "It's your problem.", "Use another one, I don't care."], "answer": 0, "explanation": "A รายงานปัญหา → B ควรดำเนินการแก้ไข → แจ้ง IT (ก) (ข)(ค)(ง) ไม่รับผิดชอบ", "shortcut": "พบปัญหา → รับทราบ + ดำเนินการ", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-CONV-0013", "subject": "english", "topic": "conversation", "subtopic": "apology_response", "difficulty": 2, "stem": "A: I'm sorry I submitted the report late.\nB: ______", "figure_svg": null, "choices": ["It happens. Just submit it tomorrow morning, please.", "That's terrible. You are fired.", "I don't believe you.", "Late is never okay."], "answer": 0, "explanation": "A ขอโทษ → B ควรรับคำขอโทษและให้ทางออกอย่างสุภาพ (ก) (ข) รุนแรงเกินเหตุ (ค) ไม่ใช่การตอบรับ (ง) กว้างไป ไม่ช่วยแก้ปัญหา", "shortcut": "ขอโทษ → รับ + ทางออก ไม่ใช่ลงโทษทันที", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-CONV-0014", "subject": "english", "topic": "conversation", "subtopic": "formal_refusal", "difficulty": 3, "stem": "A: Could you take over my duties while I'm on leave?\nB: I'm afraid I can't ______", "figure_svg": null, "choices": ["because I'm free.", "because I hate extra work.", "because it's impossible.", "because I already have a full workload, but I can suggest someone who might help."], "answer": 3, "explanation": "ปฏิเสธในบริบททางการต้องมีเหตุผล + ทางเลือก → (ง) เหตุผล+เสนอทางออก (ก) ไม่ใช่เหตุผลปฏิเสธ (ข) ไม่สุภาพ (ค) ไม่มีทางออก", "shortcut": "ปฏิเสธสุภาพ: I'm afraid… because…, but… (+ ทางออก)", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-CONV-0015", "subject": "english", "topic": "conversation", "subtopic": "suggestion", "difficulty": 2, "stem": "A: The team seems confused about the new procedure.\nB: Why don't we ______", "figure_svg": null, "choices": ["ignore it?", "hold a short briefing this week?", "cancel the procedure?", "blame them?"], "answer": 1, "explanation": "เสนอทางแก้ → ประชุมชี้แจงสั้น ๆ เหมาะที่สุด (ข) (ก)(ค)(ง) ไม่แก้ปัญหา", "shortcut": "Why don't we + V1 = เสนอแนวทาง", "study_ref": "english-conversation", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-VOC-0011", "subject": "english", "topic": "vocabulary", "subtopic": "synonym", "difficulty": 1, "stem": "The word \"significant\" in \"There has been a significant improvement\" is closest in meaning to:", "figure_svg": null, "choices": ["minor", "important/noticeable", "late", "small"], "answer": 1, "explanation": "significant = สำคัญ/เห็นได้ชัด ≈ important (ข) (ก)(ง) ตรงข้าม (ค) ไม่เกี่ยว", "shortcut": "significant ≈ important ≈ considerable — ออกบ่อยมาก", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-VOC-0012", "subject": "english", "topic": "vocabulary", "subtopic": "collocation", "difficulty": 2, "stem": "We need to ______ a decision before Friday.", "figure_svg": null, "choices": ["make", "do", "take", "get"], "answer": 0, "explanation": "make a decision = ตัดสินใจ (collocation มาตรฐาน) (ก) (ข) do a decision ผิด (ค) take a decision ใช้ได้ในภาษาอังกฤษแบบบริติช แต่สำนวนที่เป็นมาตรฐานสากล/ข้อสอบคือ make (ง) get a decision ใช้ไม่ได้กับผู้ตัดสินใจโดยตรง", "shortcut": "make a decision · make a mistake · make progress", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-VOC-0013", "subject": "english", "topic": "vocabulary", "subtopic": "effect_vs_affect", "difficulty": 2, "stem": "The new regulations will ______ every department in the ministry.", "figure_svg": null, "choices": ["effect", "be affected", "affect", "effective"], "answer": 2, "explanation": "ต้องการกริยา 'กระทบ' → affect (ค) (ก) effect เป็นนาม (ผล) (ข) be affected ใช้โครง pass ไม่เข้ากับwill + (ง) effective คือคุณศัพท์ (มีผล)", "shortcut": "affect = กระทบ (v.) · effect = ผล (n.) · effective = มีผล (adj.)", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-VOC-0014", "subject": "english", "topic": "vocabulary", "subtopic": "phrasal_verb", "difficulty": 3, "stem": "The manager had to ______ the angry customers during the busy season.", "figure_svg": null, "choices": ["put off", "put away", "put on", "put up with"], "answer": 3, "explanation": "put up with = ทนกับ (ก) put off = เลื่อน (ข) put away = เก็บเข้าที่ (ค) put on = สวม/จัดขึ้น — บริบททนลูกค้า → (ง)", "shortcut": "put up with = ยอมทน · put off = เลื่อน · put away = เก็บ", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-VOC-0015", "subject": "english", "topic": "vocabulary", "subtopic": "context_clue", "difficulty": 2, "stem": "\"The instructions are too complicated; nobody can understand them.\" The word \"complicated\" most nearly means:", "figure_svg": null, "choices": ["clear", "difficult to understand", "simple", "short"], "answer": 1, "explanation": "บริบท: คำสั่งซับซ้อนจนไม่มีใครเข้าใจ → complicated = ยากที่จะเข้าใจ (ข) (ก)(ค) ตรงข้าม (ง) ไม่ตรง", "shortcut": "complicated ≈ difficult to understand ≈ complex", "study_ref": "english-vocabulary", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0011", "subject": "english", "topic": "grammar", "subtopic": "subject_verb", "difficulty": 1, "stem": "The number of applications ______ increased this year.", "figure_svg": null, "choices": ["has", "have", "are", "were"], "answer": 0, "explanation": "The number of + พหูพจน์ → กริยาเอกพจน์ → has increased (ก) (ข)(ค)(ง) พหูพจน์ผิดกฎ", "shortcut": "The number of + N พหูพจน์ → กริยาเอกพจน์ · A number of → พหูพจน์", "study_ref": "english-grammar-1", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0012", "subject": "english", "topic": "grammar", "subtopic": "past_perfect", "difficulty": 2, "stem": "By the time the inspector arrived, the staff ______ the venue.", "figure_svg": null, "choices": ["cleaned", "clean", "have cleaned", "had cleaned"], "answer": 3, "explanation": "by the time + เหตุการณ์อดีต → เหตุการณ์ก่อนหน้าใช้ Past Perfect (had + V3) (ง) (ก) Past Simple (ข) Present (ค) Present Perfect", "shortcut": "by the time + V2 → had + V3", "study_ref": "english-grammar-1", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0013", "subject": "english", "topic": "grammar", "subtopic": "passive", "difficulty": 1, "stem": "The report ______ by the legal division last week.", "figure_svg": null, "choices": ["checked", "was checked", "checks", "is checking"], "answer": 1, "explanation": "report (นาม) + อดีต + 'ถูกตรวจ' → Past passive: was + V3 (ข) (ก)(ค)(ง) ขาด was หรือผิดโครง", "shortcut": "นาม + ถูกกระทำ + อดีต → was/were + V3", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0014", "subject": "english", "topic": "grammar", "subtopic": "conditional_type2", "difficulty": 2, "stem": "If I ______ the director, I would approve the budget.", "figure_svg": null, "choices": ["am", "was", "were", "will be"], "answer": 2, "explanation": "Conditional Type 2: If + V2 (สำหรับbe ใช้ were) → would + V1 → were (ค) (ก) ผิด (ข) was ใช้ไม่ได้ในภาษาทางการ (ง) will be ผิดกฎ", "shortcut": "If I were you — were กับทุกประธานใน Type 2", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0015", "subject": "english", "topic": "grammar", "subtopic": "despite_vs_although", "difficulty": 3, "stem": "______ the high cost, the board decided to proceed.", "figure_svg": null, "choices": ["Despite", "Although", "Because", "However"], "answer": 0, "explanation": "ช่องว่างตามด้วยนามวลี 'the high cost' → despite + นาม (ก) (ข) although + ประโยค (ค) because + ประโยค (ง) however คั่นประโยค ไม่ใช่คำเชื่อมหน้าวลี", "shortcut": "despite/in spite of + นาม · although + ประโยค", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0016", "subject": "english", "topic": "grammar", "subtopic": "gerund_after_preposition", "difficulty": 2, "stem": "I look forward to ______ from you soon.", "figure_svg": null, "choices": ["hear", "hearing", "heard", "be heard"], "answer": 1, "explanation": "look forward to + V-ing (to เป็นบุพบท) → hearing (ข) (ก) to + V1 ผิด (ค)(ง) ผิดรูป", "shortcut": "look forward to + V-ing — to ไม่ใช่ to-infinitive", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-GRAM-0017", "subject": "english", "topic": "grammar", "subtopic": "parallel", "difficulty": 3, "stem": "The job requires typing, filing, and ______.", "figure_svg": null, "choices": ["answer the phone", "answering the phone", "to answering", "to answer the phone"], "answer": 1, "explanation": "โครงขนาน: typing, filing, and … → ต้องเป็น gerund เช่นกัน → answering (ข) (ก)(ง) infinitive ไม่ขนาน (ค) ผิดโครงสร้าง", "shortcut": "and เชื่อมโครงสร้างเดียวกัน — typing, filing, answering", "study_ref": "english-grammar-2", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0011", "subject": "english", "topic": "reading", "subtopic": "main_idea", "difficulty": 1, "stem": "Read: \"The library will extend its opening hours during the exam period. Starting 1 April, it will open from 7 a.m. to 10 p.m. on weekdays.\" What is the main point?", "figure_svg": null, "choices": ["The library is closing.", "The library will charge a fee.", "The library will open longer during exams.", "The library changes ownership."], "answer": 2, "explanation": "ทั้งข้อความพูดเรื่องการเพิ่มเวลาเปิดของห้องสมุดช่วงสอบ (ค) (ก)(ข)(ง) ไม่มีในเนื้อเรื่อง", "shortcut": "main point = สิ่งที่ทั้งข้อความกล่าวถึง", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0012", "subject": "english", "topic": "reading", "subtopic": "detail", "difficulty": 1, "stem": "Read: \"The library will extend its opening hours during the exam period. Starting 1 April, it will open from 7 a.m. to 10 p.m. on weekdays.\" When do the new hours begin?", "figure_svg": null, "choices": ["1 March", "1 May", "1 April", "Next Monday"], "answer": 2, "explanation": "'Starting 1 April' → (ค) (ก)(ข)(ง) ไม่ตรงกับเนื้อเรื่อง", "shortcut": "สแกนคีย์เวิร์ดเวลาในเนื้อเรื่อง", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0013", "subject": "english", "topic": "reading", "subtopic": "inference", "difficulty": 2, "stem": "Read: \"Registration for the seminar closes on 30 June. Late registrations will be placed on a waiting list and confirmed only if seats become available.\" What can be inferred?", "figure_svg": null, "choices": ["Latecomers are guaranteed seats.", "The seminar will be cancelled.", "Everyone can attend.", "Registering before 30 June is safer for securing a seat."], "answer": 3, "explanation": "ข้อความ: ลงทะเบียนช้าอยู่ใน waiting list และได้ที่นั่งเฉพาะเมื่อมีที่ว่าง → ลงทะเบียนก่อน 30 มิ.ย. ปลอดภัยกว่าสำหรับการได้ที่นั่ง (ง) (ก)(ค) ขัดกับเงื่อนไขในข้อความ (ข) ไม่มีข้อมูลว่าถูกยกเลิก", "shortcut": "inference → เลือกข้อที่ข้อความรองรับ ไม่ใช่ข้อเดาเอง", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0014", "subject": "english", "topic": "reading", "subtopic": "vocab_in_context", "difficulty": 2, "stem": "Read: \"The committee's decision was unanimous.\" In this sentence, \"unanimous\" means:", "figure_svg": null, "choices": ["divided", "postponed", "controversial", "involving everyone in agreement"], "answer": 3, "explanation": "unanimous = เป็นเอกฉันท์ (ทุกคนเห็นพ้อง) (ง) (ก)(ค) ตรงข้าม (ข) ไม่เกี่ยว", "shortcut": "unanimous ≈ agreed by all", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0015", "subject": "english", "topic": "reading", "subtopic": "email_purpose", "difficulty": 1, "stem": "Read the email: \"Dear Team, Please bring your laptop to tomorrow's workshop. We will practise on our own machines. — Pim\" What does Pim want the team to do?", "figure_svg": null, "choices": ["Buy new laptops", "Cancel the workshop", "Work from home", "Bring their laptops to the workshop"], "answer": 3, "explanation": "ประโยคคำสั่งตรง: 'Please bring your laptop' → (ง) (ก)(ข)(ค) ไม่ตรงกับอีเมล", "shortcut": "call to action → หา please + กริยา", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0016", "subject": "english", "topic": "reading", "subtopic": "not_true", "difficulty": 3, "stem": "Read: \"The museum offers free entry every first Sunday of the month. Other days, tickets cost 100 baht. Groups of ten or more receive a 20% discount.\" Which is NOT true?", "figure_svg": null, "choices": ["Entry is free on the first Sunday of each month.", "Groups of 10+ get a discount.", "Entry costs 100 baht on regular days.", "Tickets always cost 100 baht."], "answer": 3, "explanation": "ข้อความบอก first Sunday = ฟรี → 'tickets always cost 100 baht' เป็นสิ่งที่ไม่จริง (ง) (ก)(ข)(ค) ตรงกับข้อความ", "shortcut": "NOT true → หาข้อที่ขัดเงื่อนไข/ยกเว้น (ฟรี vs 100 บาท)", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0017", "subject": "english", "topic": "reading", "subtopic": "passage_tone", "difficulty": 2, "stem": "Read: \"It is with deep regret that the committee announces the cancellation of the charity concert due to insufficient ticket sales. Refunds will be processed within 14 days.\" What is the tone of the message?", "figure_svg": null, "choices": ["Celebratory", "Apologetic", "Angry", "Humorous"], "answer": 1, "explanation": "'with deep regret' + 'refunds' → โทนขอโทษ/เสียใจ (ข) (ก)(ค)(ง) ไม่ใช่โทนของข้อความ", "shortcut": "tone → ดูคำอารมณ์หลัก (regret → apologetic)", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S2-READ-0018", "subject": "english", "topic": "reading", "subtopic": "detail_scan", "difficulty": 2, "stem": "Read: \"Applicants must submit their application form, a copy of their ID card, and two passport-sized photos by 15 August. Incomplete applications will not be considered.\" What happens to incomplete applications?", "figure_svg": null, "choices": ["They are accepted with a warning.", "They are returned with comments.", "They will not be considered.", "They get priority."], "answer": 2, "explanation": "'Incomplete applications will not be considered.' (ค) (ก)(ข)(ง) ไม่ตรงกับข้อความ", "shortcut": "หาประโยคที่พูดถึง 'incomplete applications' ตรง ๆ", "study_ref": "english-reading", "law_ref": null, "needs_review": false, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0011", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "three_levels", "difficulty": 1, "stem": "การบริหารราชการแผ่นดินของไทยแบ่งออกเป็นกี่ระดับ?", "figure_svg": null, "choices": ["2 ระดับ คือ ส่วนกลางและส่วนภูมิภาค", "5 ระดับ คือ กระทรวง ทบวง กรม จังหวัด อำเภอ", "4 ระดับ คือ ภาค จังหวัด อำเภอ ตำบล", "3 ระดับ คือ ส่วนกลาง ส่วนภูมิภาค ส่วนท้องถิ่น"], "answer": 3, "explanation": "ตามโครงสร้างมาตรฐาน แบ่งเป็น 3 ระดับ: ส่วนกลาง (กระทรวง ทบวง กรม) ส่วนภูมิภาค (จังหวัด อำเภอ ตำบล หมู่บ้าน) ส่วนท้องถิ่น (เทศบาล อบต. อบจ. กทม. พัทยา) (ง) (ก)(ค)(ข) แบ่งไม่ครบหรือซ้อนชั้นผิด", "shortcut": "กลาง–ภูมิภาค–ท้องถิ่น = 3 ระดับ", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0012", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "ministry_order", "difficulty": 1, "stem": "ลำดับชั้นราชการส่วนกลางที่ถูกต้องจากใหญ่ไปเล็กคือข้อใด?", "figure_svg": null, "choices": ["กรม → ทบวง → กระทรวง", "ทบวง → กรม → กระทรวง", "กระทรวง → ทบวง → กรม", "กรม → กระทรวง → ทบวง"], "answer": 2, "explanation": "กระทรวง (ใหญ่สุด) → ทบวง → กรม (เล็กสุด) (ค) (ก)(ข)(ง) เรียงลำดับผิด", "shortcut": "กระทรวง > ทบวง > กรม", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0013", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "bangkok_special", "difficulty": 2, "stem": "เทศบาลนครเชียงใหม่สังกัดราชการส่วนใด?", "figure_svg": null, "choices": ["ส่วนกลาง", "ส่วนภูมิภาค", "ส่วนท้องถิ่น", "ไม่เป็นราชการ"], "answer": 2, "explanation": "เทศบาลทุกระดับเป็นองค์กรปกครองส่วนท้องถิ่น มีนายกเทศมนตรีมาจากการเลือกตั้ง (ค) (ก) ไม่ใช่เพราะเป็นหน่วยงานระดับชาติ (ข) ไม่ใช่ตัวแทนส่วนกลางในพื้นที่แบบผู้ว่าฯ/นายอำเภอ (ง) เทศบาลอยู่ในระบบราชการไทยตามกฎหมายจัดตั้ง", "shortcut": "เทศบาล อบต. อบจ. กทม. พัทยา = ท้องถิ่น", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0014", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "governor", "difficulty": 2, "stem": "ผู้ว่าราชการจังหวัดได้มาโดยวิธีใด?", "figure_svg": null, "choices": ["การแต่งตั้งโดยส่วนราชการส่วนกลาง", "การเลือกตั้งโดยประชาชนในจังหวัด", "การเลือกตั้งโดยกำนันผู้ใหญ่บ้าน", "การจับสลาก"], "answer": 0, "explanation": "ผู้ว่าฯ เป็นข้าราชการแต่งตั้งโดยส่วนกลาง (ผ่านรัฐบาล/ปลัดกระทรวงมหาดไทย) เป็นตัวแทนส่วนกลางในพื้นที่ ไม่ใช่การเลือกตั้ง (ก) (ข)(ค) กลไกเลือกตั้งไม่ใช่ที่มาของผู้ว่าฯ (ง) ไม่จริง", "shortcut": "ผู้ว่าฯ = แต่งตั้ง · นายกเทศมนตรี/อบต./กทม. = เลือกตั้ง", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0015", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "local_elected", "difficulty": 2, "stem": "ข้อใดเป็นราชการส่วนท้องถิ่น?", "figure_svg": null, "choices": ["จังหวัด", "สำนักงานปลัดกระทรวง", "เทศบาลตำบล", "ที่ว่าการอำเภอ"], "answer": 2, "explanation": "เทศบาลตำบลเป็นองค์กรปกครองส่วนท้องถิ่น มีนายกเทศมนตรีมาจากการเลือกตั้ง (ค) (ก) จังหวัด = ส่วนภูมิภาค (ข) ส่วนกลาง (ง) ส่วนภูมิภาค", "shortcut": "ท้องถิ่น = เลือกตั้ง · เทศบาล อบต. อบจ. กทม. พัทยา", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0016", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "regional_vs_local", "difficulty": 3, "stem": "ข้อใดแยกแยะส่วนภูมิภาคกับส่วนท้องถิ่นได้ถูกต้อง?", "figure_svg": null, "choices": ["ส่วนภูมิภาคผู้นำมาจากการเลือกตั้ง", "ส่วนท้องถิ่นบริหารงานโดยไม่ขึ้นกับการเลือกตั้ง", "ส่วนภูมิภาคเป็นตัวแทนส่วนกลาง ส่วนท้องถิ่นปกครองตนเอง", "ทั้งสองส่วนแต่งตั้งโดยส่วนกลางเหมือนกัน"], "answer": 2, "explanation": "ส่วนภูมิภาค (ผู้ว่าฯ นายอำเภอ) = ตัวแทนส่วนกลางแต่งตั้ง ส่วนท้องถิ่น (เทศบาล อบต. ฯลฯ) = ประชาชนปกครองตนเอง ผู้นำเลือกตั้ง (ค) (ก) กลับกัน (ข) ผิด — ท้องถิ่นเลือกตั้ง (ง) ผิด", "shortcut": "ภูมิภาค=แต่งตั้ง/ตัวแทนกลาง · ท้องถิ่น=เลือกตั้ง/ปกครองตนเอง", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-ADMIN-0017", "subject": "civil_knowledge", "topic": "public_admin_law", "subtopic": "district_office", "difficulty": 3, "stem": "สำนักงานเขตสังกัดราชการส่วนใด?", "figure_svg": null, "choices": ["ส่วนท้องถิ่น (กรุงเทพมหานคร)", "ส่วนภูมิภาค", "ส่วนกลาง", "ทั้งส่วนกลางและท้องถิ่นพร้อมกัน"], "answer": 0, "explanation": "สำนักงานเขตเป็นหน่วยงานย่อยของ กทม. ซึ่งเป็นส่วนท้องถิ่นรูปแบบพิเศษ → สำนักงานเขต = ส่วนท้องถิ่น (ก) (ข)(ค)(ง) ไม่ถูก", "shortcut": "สำนักงานเขต = หน่วยงานของ กทม. = ท้องถิ่น", "study_ref": "civil-public-admin-law", "law_ref": "พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-GOV-0011", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "purpose", "difficulty": 1, "stem": "เจตนารมณ์หลักของ พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 คืออะไร?", "figure_svg": null, "choices": ["ให้ราชการบริหารเพื่อประโยชน์สุขของประชาชน", "เพิ่มจำนวนข้าราชการ", "รวมส่วนราชการเข้าด้วยกัน", "ลดงบประมาณรายจ่ายทุกกรณี"], "answer": 0, "explanation": "กฎหมายฉบับนี้ต้องการให้ส่วนราชการบริหารเพื่อประโยชน์สุขของประชาชน มีผลสัมฤทธิ์ คุ้มค่า โปร่งใส (ก) ตรงเจตนารมณ์ (ข)(ค)(ง) ไม่ใช่เป้าหมายของกฎหมาย", "shortcut": "บริหารเพื่อประชาชน = หัวใจของ good governance", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-GOV-0012", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "participation", "difficulty": 2, "stem": "หน่วยงานเปิดเว็บให้ประชาชนแสดงความเห็นร่างกฎก่อนประกาศใช้ สอดคล้องหลักใด?", "figure_svg": null, "choices": ["หลักความคุ้มค่า", "หลักลดขั้นตอน", "หลักผลสัมฤทธิ์", "หลักการมีส่วนร่วม"], "answer": 3, "explanation": "การรับฟังความเห็นประชาชนก่อนตัดสินใจ = การมีส่วนร่วม (ง) (ก) คุ้มค่า = ใช้ทรัพยากร (ค) ผลสัมฤทธิ์ = ผลลัพธ์ (ข) ลดขั้นตอน = ตัดกระบวนการ", "shortcut": "เปิดรับฟัง = มีส่วนร่วม", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-GOV-0013", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "results", "difficulty": 2, "stem": "ส่วนราชการประเมินแผนปฏิบัติราชการด้วยตัวชี้วัดรายไตรมาส สอดคล้องหลักใด?", "figure_svg": null, "choices": ["หลักความโปร่งใส", "หลักการมีส่วนร่วม", "หลักผลสัมฤทธิ์ต่อภารกิจของรัฐ", "หลักความคุ้มค่า"], "answer": 2, "explanation": "การวัดผลด้วยตัวชี้วัดตามแผน = การบริหารเชิงผลลัพธ์ ≈ ผลสัมฤทธิ์ (ค) (ก) โปร่งใส = เปิดเผย (ข) มีส่วนร่วม = ฟังประชาชน (ง) คุ้มค่า = ประหยัดทรัพยากร", "shortcut": "KPI/แผนงาน/ประเมินผล = ผลสัมฤทธิ์", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-GOV-0014", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "transparency", "difficulty": 2, "stem": "กรมเผยแพร่เอกสารการจัดซื้อจัดจ้างอย่างเปิดเผย ประชาชนตรวจสอบได้ สอดคล้องหลักใดมากที่สุด?", "figure_svg": null, "choices": ["หลักประสิทธิภาพ", "หลักความรับผิดชอบ", "หลักความคุ้มค่า", "หลักความโปร่งใส"], "answer": 3, "explanation": "การเปิดเผยข้อมูลให้ตรวจสอบ = โปร่งใส (ง) (ก) ประสิทธิภาพ = ทำงานเก่ง/เร็ว (ข) รับผิดชอบ = ยอมรับผลการกระทำ (ค) คุ้มค่า = ทรัพยากรคุ้ม", "shortcut": "เปิดเผย/ตรวจสอบได้ = โปร่งใส", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-GOV-0015", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "one_stop", "difficulty": 3, "stem": "แนวคิด 'One Stop Service' สะท้อนหลักการใดมากที่สุด?", "figure_svg": null, "choices": ["หลักอำนวยความสะดวกและตอบสนองความต้องการของประชาชน", "หลักผลสัมฤทธิ์", "หลักการมีส่วนร่วม", "หลักความคุ้มค่า"], "answer": 0, "explanation": "One Stop Service = ติดต่อครั้งเดียวครบทุกขั้นตอน ≈ อำนวยความสะดวกประชาชน (ก) (ข) ผลสัมฤทธิ์ = ผลงาน (ค) มีส่วนร่วม = ฟังความเห็น (ง) คุ้มค่า = ประหยัด", "shortcut": "บริการจุดเดียว = สะดวกประชาชน", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-GOV-0016", "subject": "civil_knowledge", "topic": "good_governance", "subtopic": "value", "difficulty": 2, "stem": "หน่วยงานเลือกผู้รับจ้างที่ราคาเหมาะสมและคุณภาพได้มาตรฐาน สอดคล้องหลักใด?", "figure_svg": null, "choices": ["หลักความรับผิดชอบ", "หลักประสิทธิผล", "หลักการมีส่วนร่วม", "หลักความคุ้มค่า"], "answer": 3, "explanation": "เลือกทั้งราคาและคุณภาพ = คุ้มค่า (value for money) (ง) (ก) รับผิดชอบ = ยอมรับผล (ค) มีส่วนร่วม = ฟังความเห็น (ข) ประสิทธิผล = บรรลุเป้า", "shortcut": "คุ้มค่า = คุณภาพ + ราคาเหมาะสม", "study_ref": "civil-good-governance", "law_ref": "พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-PROC-0011", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "definition", "difficulty": 1, "stem": "ข้อใดคือ 'คำสั่งทางปกครอง' ตามความเข้าใจทั่วไปใน พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539?", "figure_svg": null, "choices": ["หนังสือเชิญประชุม", "บันทึกภายในหน่วยงาน", "การใช้อำนาจตามกฎหมายของเจ้าหน้าที่ที่กระทบสิทธิบุคคล", "คำแถลงของโฆษกรัฐบาล"], "answer": 2, "explanation": "คำสั่งทางปกครอง = การใช้อำนาจตามกฎหมายของเจ้าหน้าที่ ส่งผลกระทบต่อสิทธิบุคคลโดยตรง (ค) (ก)(ข)(ง) ไม่มีผลกระทบสิทธิบุคคลโดยตรง", "shortcut": "ใช้อำนาจ + กระทบสิทธิ = คำสั่งทางปกครอง", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-PROC-0012", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "right_to_be_heard", "difficulty": 2, "stem": "เจ้าหน้าที่จะสั่งระงับกิจกรรมของร้านค้าแห่งหนึ่ง ขั้นตอนใดที่ควรทำก่อน?", "figure_svg": null, "choices": ["แจ้งและเปิดโอกาสให้เจ้าของร้านชี้แจงก่อน", "สั่งระงับทันที แล้วงอธิบายทีหลัง", "รอให้ร้านค้าฟ้องก่อน", "ไม่ต้องมีขั้นตอนใด ๆ"], "answer": 0, "explanation": "ก่อนออกคำสั่งทางปกครองที่กระทบสิทธิ ต้องแจ้งและรับฟังคำชี้แจง (เว้นแต่เร่งด่วน/กฎหมายกำหนด) (ก) (ข)(ค)(ง) ข้ามขั้นตอน คำสั่งอาจไม่ชอบด้วยกฎหมาย", "shortcut": "แจ้ง → รับฟัง → ออกคำสั่ง + เหตุผล", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-PROC-0013", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "reasons", "difficulty": 2, "stem": "คำสั่งทางปกครองฉบับหนึ่งไม่ได้ระบุเหตุผลเลย ผลตามหลักกฎหมายปกครองคือข้อใด?", "figure_svg": null, "choices": ["คำสั่งสมบูรณ์เสมอ", "คำสั่งเปลี่ยนสภาพเป็นคำแนะนำ", "คำสั่งมีผลเฉพาะต่อเจ้าหน้าที่ชั้นสูง", "คำสั่งอาจไม่สมบูรณ์ตามรูปแบบ และถูกโต้แย้ง/เพิกถอนภายหลังได้"], "answer": 3, "explanation": "คำสั่งทางปกครองต้องมีเหตุผลกำกับ ขาดเหตุผล = รูปแบบไม่สมบูรณ์ เสี่ยงถูกอุทธรณ์/เพิกถอน (ง) (ก)(ค)(ข) ไม่ตรงกับหลักการ", "shortcut": "ไม่มีเหตุผล = คำสั่งอ่อนแรง", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-PROC-0014", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "appeal", "difficulty": 2, "stem": "ผู้ได้รับคำสั่งทางปกครองไม่เห็นด้วย ลำดับปกติก่อนนำไปฟ้องศาลปกครองคือ?", "figure_svg": null, "choices": ["ฟ้องทันที", "รอให้คำสั่งหมดอายุ", "อุทธรณ์ต่อเจ้าหน้าที่/คณะกรรมการที่กฎหมายกำหนด", "ร้องเรียนต่อสภานิติบัญญัติ"], "answer": 2, "explanation": "ต้องอุทธรณ์ตามขั้นตอนก่อน จึงฟ้องศาลปกครองได้ (เว้นแต่กรณีพิเศษ) (ค) (ก) ข้ามขั้นตอน (ข) ไม่แก้ปัญหา (ง) ไม่ใช่ช่องทางที่กฎหมายกำหนด", "shortcut": "อุทธรณ์ก่อน → ศาลปกครองทีหลัง", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-PROC-0015", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "urgent", "difficulty": 3, "stem": "ข้อใดเป็นข้อยกเว้นที่ทำให้เจ้าหน้าที่ออกคำสั่งทางปกครองได้โดยไม่ต้องรับฟังคู่กรณีล่วงหน้า?", "figure_svg": null, "choices": ["คราวใดก็ได้ตามดุลพินิจ", "กรณีคู่กรณีเป็นชาวต่างชาติ", "กรณีเร่งด่วน หรือที่กฎหมายกำหนดไว้เป็นอย่างอื่น", "กรณีคู่กรณีไม่อยู่"], "answer": 2, "explanation": "ข้อยกเว้น = กรณีเร่งด่วน/กฎหมายกำหนดเป็นอย่างอื่น (เช่น คำสั่งป้องกันอันตรายสาธารณะ) (ค) (ก)(ข)(ง) ไม่ใช่เหตุตามกฎหมาย", "shortcut": "ข้อยกเว้น: เร่งด่วน / กฎหมายกำหนดไว้", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-PROC-0016", "subject": "civil_knowledge", "topic": "administrative_procedure", "subtopic": "silence", "difficulty": 2, "stem": "ผู้ยื่นคำขอไม่ได้รับการตอบเป็นเวลานาน ความนิ่งเฉยของเจ้าหน้าที่ตามหลักกฎหมายปกครองถือว่าอย่างไร?", "figure_svg": null, "choices": ["ไม่ถือเป็นอะไร รอต่อไปได้เรื่อย ๆ", "อาจถือเป็นคำสั่งทางปกครองโดยการนิ่งเฉย และใช้สิทธิตามขั้นตอนได้", "ถือเป็นการเห็นชอบโดยปริยาย", "ถือเป็นการปฏิเสธโดยอัตโนมัติ"], "answer": 1, "explanation": "การนิ่งเฉย/ไม่ตอบคำขอในเวลาอันสมควร อาจเข้าลักษณะคำสั่งทางปกครองโดยการไม่ออกคำสั่ง ผู้เสียหายใช้สิทธิตาม พ.ร.บ.วิธีปฏิบัติฯ ได้ (ข) (ก)(ค)(ง) ไม่ตรงกับหลัก", "shortcut": "เงียบก็อาจเป็นคำสั่ง — ใช้สิทธิอุทธรณ์ได้", "study_ref": "civil-administrative-procedure", "law_ref": "พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-LIAB-0011", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "in_duty", "difficulty": 1, "stem": "เจ้าหน้าที่ทำงานตามหน้าที่ เกิดความเสียหายโดยไม่จงใจ/ไม่ประมาทร้ายแรง ใครต้องรับผิด?", "figure_svg": null, "choices": ["เจ้าหน้าที่รับผิดเองเต็มที่", "ผู้เสียหายไม่มีสิทธิใด ๆ", "ทั้งสองร่วมกันจ่ายคนละครึ่ง", "หน่วยงานของรัฐชดใช้ให้ผู้เสียหาย"], "answer": 3, "explanation": "ละเมิดในหน้าที่ + ไม่จงใจ/ไม่ประมาทร้ายแรง → หน่วยงานชดใช้ (ตาม พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539) (ง) (ก)(ค)(ข) ไม่ตรงกับหลัก", "shortcut": "ในหน้าที่ + ไม่ร้ายแรง → หน่วยงานจ่าย", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-LIAB-0012", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "gross_negligence", "difficulty": 2, "stem": "เจ้าหน้าที่ละเมิดในหน้าที่ด้วยความประมาทร้ายแรง หน่วยงานจ่ายให้ผู้เสียหายแล้ว หน่วยงานทำอะไรต่อได้?", "figure_svg": null, "choices": ["ห้ามไล่เบี้ยเด็ดขาด", "ไล่เบี้ยเอาคืนจากเจ้าหน้าที่", "ฟ้องศาลอาญาอัตโนมัติ", "โอนเงินให้คืนหน่วยงานจากงบปีถัดไป"], "answer": 1, "explanation": "เมื่อประมาทร้ายแรง หน่วยงานจ่ายก่อนแล้วไล่เบี้ยคืนจากเจ้าหน้าที่ (ภายในขอบเขตที่กฎหมายกำหนด) (ข) (ก)(ค)(ง) ไม่ตรงกับหลัก", "shortcut": "ประมาทร้ายแรง → หน่วยงานจ่าย → ไล่เบี้ยคืน", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-LIAB-0013", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "outside_duty", "difficulty": 2, "stem": "เจ้าหน้าที่ทำละเมิดนอกหน้าที่ราชการ การรับผิดเป็นอย่างไร?", "figure_svg": null, "choices": ["หน่วยงานรับผิดเสมอ", "หน่วยงานรับผิดบางส่วน", "เจ้าหน้าที่รับผิดเองเต็มที่ เหมือนบุคคลทั่วไป", "ไม่มีใครรับผิด"], "answer": 2, "explanation": "นอกหน้าที่ = เจ้าหน้าที่รับผิดเองเต็มที่ตามหลักละเมิดทั่วไป (ค) (ก)(ข)(ง) ไม่ถูก", "shortcut": "นอกหน้าที่ = รับผิดเอง 100%", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-LIAB-0014", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "serious_discipline", "difficulty": 2, "stem": "ความผิดวินัยอย่างร้ายแรงของข้าราชการพลเรือน มีโทษสูงสุดคือข้อใด?", "figure_svg": null, "choices": ["ปลดออก หรือ ไล่ออก", "ตักเตือน", "หักเงินเดือน 5%", "ย้ายสถานที่ปฏิบัติงาน"], "answer": 0, "explanation": "ความผิดวินัยร้ายแรง → ปลดออก/ไล่ออก (ก) (ข)(ค)(ง) เป็นโทษความผิดไม่ร้ายแรง/มาตรการอื่น", "shortcut": "วินัยร้ายแรง = ปลด/ไล่ออก", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-LIAB-0015", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "gift", "difficulty": 2, "stem": "ผู้มาติดต่อนำของขวัญมูลค่าสูงมาให้ข้าราชการที่กำลังพิจารณาเรื่องของตน ข้าราชการควรปฏิบัติอย่างไร?", "figure_svg": null, "choices": ["รับไว้เพราะเป็นน้ำใจไมตรี", "ปฏิเสธ หรือนำส่ง/แจ้งตามระเบียบของหน่วยงาน", "รับแล้วส่งต่อให้เพื่อนร่วมงาน", "รับแล้วบอกกับทุกคน"], "answer": 1, "explanation": "ของขวัญจากผู้มาติดต่อ = ผลประโยชน์ทับซ้อน/อาจเข้าข่ายวินัยและฝ่าฝืนจริยธรรม → ปฏิเสธหรือนำส่งตามระเบียบ (ข) (ก)(ค)(ง) ผิดหลัก", "shortcut": "ของขวัญจากผู้มาติดต่อ = ปฏิเสธ/ส่งตามระเบียบ", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562", "needs_review": true, "origin": "original", "set_id": 1}, {"id": "S3-LIAB-0016", "subject": "civil_knowledge", "topic": "liability_discipline_ethics", "subtopic": "multi_dimension", "difficulty": 2, "stem": "เจ้าหน้าที่รับเงินใต้โต๊ะเพื่อแลกกับการอนุมัติ การกระทำนี้ผิดอย่างไรได้บ้าง?", "figure_svg": null, "choices": ["ผิดด้านวินัยเพียงด้านเดียว", "ไม่ผิด ถ้าไม่มีใครเห็น", "ผิดเฉพาะคดีแพ่ง", "อาจผิดซ้อนกันทั้งวินัย จริยธรรม และความผิดอาญา"], "answer": 3, "explanation": "การรับสินบนอาจผิดพร้อมกัน: วินัย (ประพฤติชั่วร้ายแรง) · จริยธรรม (ไม่ซื่อสัตย์) · อาญา (รับสินบน) — คนละระบบ ลงโทษซ้อนได้ (ง) (ก)(ค)(ข) ไม่ครบ/ไม่จริง", "shortcut": "ทุจริต = วินัย+อาญา+จริยธรรม ซ้อนกันได้", "study_ref": "civil-liability-ethics", "law_ref": "พ.ร.บ.ระเบียบข้าราชการพลเรือน พ.ศ. 2551 / พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562", "needs_review": true, "origin": "original", "set_id": 1}]];
